    @Override
    public void start(Stage stage) {
        root = new BorderPane();
        root.getStyleClass().add("app-root");

        // DOBLE PANTALLA — no abrir más grande que la pantalla donde aparece (un
        // portátil tras venir de un monitor grande): el tamaño de diseño se acota a
        // los límites VISIBLES (sin barra de tareas) de la pantalla primaria.
        javafx.geometry.Rectangle2D vb = javafx.stage.Screen.getPrimary().getVisualBounds();
        double w = Math.min(1180, vb.getWidth());
        double h = Math.min(760, vb.getHeight());

        Scene scene = new Scene(root, w, h);
        scene.getStylesheets().add(getClass().getResource("/com/benjagest/ui/app.css").toExternalForm());
        setupGlobalShortcuts(scene);
        // Máscara de fecha (dd-MM-yyyy) en todos los DatePicker de la ventana.
        com.benjagest.ui.support.EditableCells.enableDateMaskOnFocus(scene);

        stage.setTitle("BENJAGEST");
        stage.getIcons().add(AppBrand.loadWindowIcon());
        // El mínimo tampoco puede superar la pantalla (portátiles pequeños).
        stage.setMinWidth(Math.min(920, vb.getWidth()));
        stage.setMinHeight(Math.min(640, vb.getHeight()));
        stage.setScene(scene);
        showInitialScreen();
        // Centrar en la pantalla primaria ANTES de mostrar (el tamaño ya está acotado
        // a sus límites visibles arriba). NO añadimos ningún listener dinámico: el
        // usuario debe poder mover la ventana entre pantallas y maximizar libremente.
        // El único objetivo es no ABRIR más grande que la pantalla.
        stage.setX(vb.getMinX() + Math.max(0, (vb.getWidth() - w) / 2));
        stage.setY(vb.getMinY() + Math.max(0, (vb.getHeight() - h) / 2));
        stage.show();
    }

    // ===================================================================
    //  Atajos globales (Scene-level event filter)
    //  ----------------------------------------------------------------
    //  Tab/Shift+Tab → navegacion entre campos (default JavaFX, sin
    //                   tocar nada — las TextField estan en orden de
    //                   declaracion).
    //  Ctrl+K        → command palette (buscador rapido de acciones).
    //  Ctrl+N        → nueva factura (si hay sesion).
    //  Ctrl+F        → ir a Facturacion.
    //  Ctrl+H        → ir a Inicio / dashboard.
    //  F5            → recargar dashboard.
    //
    //  Se ignoran si el foco esta dentro de un TextField/TextArea para
    //  no pisar el texto que el usuario esta escribiendo (Ctrl+N en un
    //  textarea seria una sorpresa horrible). Ctrl+K es la unica
    //  excepcion: siempre captura.
    // ===================================================================

    /**
     * Registra la pantalla actual en el historial. Si se llama desde un
     * replay (navigateBack/navigateForward) no apila — esto evita que
     * BACK quede atascado en bucle entre dos pantallas.
     */
    private void recordNav(Runnable showAgain) {
        if (navReplaying) return;
        if (navCurrent != null) {
            navBack.push(navCurrent);
            while (navBack.size() > 20) navBack.pollLast();
        }
        navForward.clear();
        navCurrent = showAgain;
    }

    private void navigateBack() {
        if (navBack.isEmpty()) return;
        Runnable previous = navBack.pop();
        if (navCurrent != null) navForward.push(navCurrent);
        navCurrent = previous;
        navReplaying = true;
        try { previous.run(); } finally { navReplaying = false; }
    }

    private void navigateForward() {
        if (navForward.isEmpty()) return;
        Runnable next = navForward.pop();
        if (navCurrent != null) navBack.push(navCurrent);
        navCurrent = next;
        navReplaying = true;
        try { next.run(); } finally { navReplaying = false; }
    }

    private void setupGlobalShortcuts(Scene scene) {
        // Listados: Escape y click en zona vacía deseleccionan en CUALQUIER
        // TableView de la aplicación (presentes y futuros). Un único punto
        // de instalación cubre los 38+ listados.
        com.benjagest.ui.support.TableSelectionHelper.attachToScene(scene);

        // Botones laterales del raton: 4 = BACK, 5 = FORWARD.
        scene.addEventFilter(javafx.scene.input.MouseEvent.MOUSE_PRESSED, ev -> {
            // Si hay algún diálogo/alert/popup modal abierto, NO navegamos
            // — el back debe afectar al dialog o ser ignorado, nunca
            // sacar al usuario del cliente cuando está leyendo un mensaje.
            // Iteramos las ventanas: si alguna está visible y NO es el
            // stage principal, asumimos que es un modal.
            for (javafx.stage.Window w : javafx.stage.Stage.getWindows()) {
                if (w.isShowing() && w != scene.getWindow()) {
                    return; // hay modal → no consumimos, dejamos que el dialog actúe
                }
            }
            if (ev.getButton() == javafx.scene.input.MouseButton.BACK) {
                navigateBack();
                ev.consume();
            } else if (ev.getButton() == javafx.scene.input.MouseButton.FORWARD) {
                navigateForward();
                ev.consume();
            }
        });

        scene.addEventFilter(javafx.scene.input.KeyEvent.KEY_PRESSED, ev -> {
            // Ctrl+K abre el command palette siempre (incluso desde un
            // TextField — es el "alfred" del app).
            if (ev.isControlDown() && ev.getCode() == javafx.scene.input.KeyCode.K) {
                if (session != null) {
                    showCommandPalette();
                }
                ev.consume();
                return;
            }

            // El resto de atajos se ignoran si el foco esta en un campo
            // de texto, para no comerse pulsaciones del usuario.
            javafx.scene.Node focused = scene.getFocusOwner();
            boolean inTextInput = focused instanceof javafx.scene.control.TextInputControl;
            if (inTextInput) {
                return;
            }

            if (session == null) {
                return;
            }

            if (ev.isControlDown() && ev.getCode() == javafx.scene.input.KeyCode.N) {
                showInvoiceEditor(null);
                ev.consume();
            } else if (ev.isControlDown() && ev.getCode() == javafx.scene.input.KeyCode.F) {
                showModule("billing");
                ev.consume();
            } else if (ev.isControlDown() && ev.getCode() == javafx.scene.input.KeyCode.H) {
                showDashboard();
                ev.consume();
            } else if (ev.getCode() == javafx.scene.input.KeyCode.F5) {
                showDashboard();
                ev.consume();
            }
        });
    }

    /**
     * Lista de acciones del command palette. Slug + label + runnable.
     * Tab fija un orden estable y lo mantiene a la hora de filtrar por
     * texto (substring case-insensitive).
     */
    private record PaletteAction(String label, String icon, Runnable action) {
    }

    private List<PaletteAction> commandPaletteActions() {
        List<PaletteAction> all = new java.util.ArrayList<>();
        all.add(new PaletteAction(t("palette.action.home"), "fas-home", this::showDashboard));
        all.add(new PaletteAction(t("palette.action.customers"), "fas-users", () -> showModule("customers")));
        all.add(new PaletteAction(t("palette.action.billing"), "fas-file-invoice-dollar", () -> showModule("billing")));
        all.add(new PaletteAction(t("palette.action.new_invoice"), "fas-plus", () -> showInvoiceEditor(null)));
        all.add(new PaletteAction(t("palette.action.settings"), "fas-cog", () -> showModule("settings")));
        all.add(new PaletteAction(t("palette.action.calendar"), "fas-calendar-alt", () -> showModule("calendar")));
        all.add(new PaletteAction(t("palette.action.purchases"), "fas-receipt", () -> showModule("purchases")));
        all.add(new PaletteAction(t("palette.action.tax"), "fas-percentage", () -> showModule("tax")));
        all.add(new PaletteAction(t("palette.action.labor"), "fas-hard-hat", () -> showModule("labor")));
        all.add(new PaletteAction(t("palette.action.reports"), "fas-chart-line", () -> showModule("reports")));
        return all;
    }

    private void showCommandPalette() {
        Dialog<PaletteAction> dialog = new Dialog<>();
        dialog.setTitle(t("palette.title"));
        dialog.setHeaderText(null);
        dialog.initStyle(javafx.stage.StageStyle.UTILITY);

        TextField search = new TextField();
        search.setPromptText(t("palette.search.prompt"));
        search.getStyleClass().add("form-input");
        search.setMaxWidth(Double.MAX_VALUE);

        javafx.scene.control.ListView<PaletteAction> listView = new javafx.scene.control.ListView<>();
        listView.setPrefHeight(280);
        listView.setCellFactory(lv -> new javafx.scene.control.ListCell<>() {
            @Override
            protected void updateItem(PaletteAction item, boolean empty) {
                super.updateItem(item, empty);
                if (empty || item == null) {
                    setText(null);
                    setGraphic(null);
                } else {
                    setText(item.label());
                    setGraphic(icon(item.icon()));
                }
            }
        });

        List<PaletteAction> all = commandPaletteActions();
        javafx.collections.ObservableList<PaletteAction> items = FXCollections.observableArrayList(all);
        listView.setItems(items);
        if (!items.isEmpty()) {
            listView.getSelectionModel().selectFirst();
        }

        search.textProperty().addListener((obs, oldV, newV) -> {
            String q = newV == null ? "" : newV.trim().toLowerCase(Locale.ROOT);
            if (q.isBlank()) {
                items.setAll(all);
            } else {
                items.setAll(all.stream()
                        .filter(a -> a.label().toLowerCase(Locale.ROOT).contains(q))
                        .toList());
            }
            if (!items.isEmpty()) {
                listView.getSelectionModel().selectFirst();
            }
        });

        // Flechas mueven la seleccion en la lista aunque el foco este en
        // el TextField; Enter elige; Esc cierra.
        search.addEventFilter(javafx.scene.input.KeyEvent.KEY_PRESSED, ev -> {
            if (ev.getCode() == javafx.scene.input.KeyCode.DOWN) {
                listView.getSelectionModel().selectNext();
                ev.consume();
            } else if (ev.getCode() == javafx.scene.input.KeyCode.UP) {
                listView.getSelectionModel().selectPrevious();
                ev.consume();
            } else if (ev.getCode() == javafx.scene.input.KeyCode.ENTER) {
                PaletteAction sel = listView.getSelectionModel().getSelectedItem();
                if (sel != null) {
                    dialog.setResult(sel);
                    dialog.close();
                }
                ev.consume();
            } else if (ev.getCode() == javafx.scene.input.KeyCode.ESCAPE) {
                dialog.setResult(null);
                dialog.close();
                ev.consume();
            }
        });
        listView.setOnMouseClicked(ev -> {
            if (ev.getClickCount() == 2) {
                PaletteAction sel = listView.getSelectionModel().getSelectedItem();
                if (sel != null) {
                    dialog.setResult(sel);
                    dialog.close();
                }
            }
        });

        VBox box = new VBox(10, search, listView);
        box.setPadding(new Insets(12));
        box.setPrefWidth(420);
        dialog.getDialogPane().setContent(box);
        dialog.getDialogPane().getButtonTypes().add(ButtonType.CANCEL);
        // Esto fuerza el foco al search cuando se abre.
        Platform.runLater(search::requestFocus);

        Optional<PaletteAction> result = dialog.showAndWait();
        result.ifPresent(action -> action.action().run());
    }

    /**
     * L4-3 — Pantalla de arranque. Decide qué mostrar:
     *   - Sin device.json local → emparejar este equipo.
     *   - Con device.json → teclado PIN.
     * El login email/password vive como flujo secundario invocado
     * desde botón "Entrar como administrador" o auto-llamado tras
     * emparejar para el OWNER.
     */
    /**
     * Arranque: si NO hay ninguna cuenta (instalación nueva), muestra el
     * REGISTRO; si ya hay cuentas, el flujo normal de login (PIN / emparejar).
     * El check es asíncrono; ante fallo de red cae al login (defensivo).
     */
    private void showInitialScreen() {
        Task<com.benjagest.ui.service.AuthApiClient.BootstrapStatus> task = new Task<>() {
            @Override protected com.benjagest.ui.service.AuthApiClient.BootstrapStatus call() {
                return authApiClient.bootstrapStatus();
            }
        };
        task.setOnSucceeded(e -> {
            var s = task.getValue();
            if (!s.hasAccounts()) {
                showRegister();                 // instalación nueva → registro
            } else if (s.hasAdvisory()) {
                showLogin();                    // asesoría → multi-puesto (emparejar/PIN)
            } else {
                showEmailLogin();               // empresario → email/contraseña, sin multi-puesto
            }
        });
        task.setOnFailed(e -> showLogin());
        start(task, "bootstrap-status");
    }

    private void showLogin() {
        java.util.Optional<com.benjagest.ui.service.DeviceConfig> dc =
                com.benjagest.ui.service.DeviceConfig.load();
        if (dc.isPresent()) {
            showPinKeypad(dc.get());
        } else {
            showPairingScreen();
        }
    }

    /**
     * L4-3 — Login email/password clásico. Era la pantalla de arranque
     * antes del modelo PIN multi-puesto; ahora es la pantalla
     * secundaria a la que se llega desde "Entrar como administrador"
     * en el teclado PIN o cuando aún no hay PINs configurados.
     */
    private void showEmailLogin() {
        VBox panel = new VBox(14);
        panel.setAlignment(Pos.CENTER);
        panel.setPadding(new Insets(42));
        panel.setMaxWidth(420);
        panel.getStyleClass().add("summary-card");

        Label title = new Label("BENJAGEST");
        title.getStyleClass().add("hero-title");
        Label subtitle = new Label("Inicia sesion con tu email y contrasena");
        subtitle.getStyleClass().add("hero-body");

        TextField emailField = new TextField();
        emailField.setPromptText("email");
        emailField.setMaxWidth(Double.MAX_VALUE);

        PasswordField passwordField = new PasswordField();
        passwordField.setPromptText("contrasena");
        passwordField.setMaxWidth(Double.MAX_VALUE);

        Button loginButton = new Button(t("login"));
        loginButton.setGraphic(icon("fas-sign-in-alt"));
        loginButton.setMaxWidth(Double.MAX_VALUE);
        loginButton.setOnAction(event -> login(emailField.getText(), passwordField.getText()));
        passwordField.setOnAction(event -> login(emailField.getText(), passwordField.getText()));

        Button googleButton = new Button(t("login.with_google"));
        googleButton.setGraphic(icon("fab-google"));
        googleButton.setMaxWidth(Double.MAX_VALUE);
        googleButton.setOnAction(ev -> startGoogleLogin(googleButton));

        javafx.scene.control.Hyperlink createAccount = new javafx.scene.control.Hyperlink(t("register.link"));
        createAccount.setOnAction(ev -> showRegister());

        panel.getChildren().addAll(
                AppBrand.createLogoMark(), title, subtitle,
                emailField, passwordWithToggle(passwordField), loginButton,
                createAccount,
                new Separator(),
                googleButton
        );

        // L4-3 — Si el PC ya está emparejado, ofrece volver al teclado PIN.
        // El email/password sigue funcionando como flujo secundario, pero
        // el día a día va por PIN.
        if (com.benjagest.ui.service.DeviceConfig.load().isPresent()) {
            javafx.scene.control.Hyperlink backToPin = new javafx.scene.control.Hyperlink(t("pin.back_to_keypad"));
            backToPin.setOnAction(ev -> showLogin());
            VBox.setMargin(backToPin, new Insets(8, 0, 0, 0));
            panel.getChildren().add(backToPin);
        }

        BorderPane wrapper = new BorderPane(panel);
        wrapper.setPadding(new Insets(70));
        BorderPane.setAlignment(panel, Pos.CENTER);
        root.setTop(null);
        root.setLeft(null);
        root.setCenter(wrapper);
        root.setBottom(null);
    }

    /**
     * REG-2 — Pantalla "Crear cuenta" (alta de asesoría o empresa). Llama a
     * {@code /api/auth/register} y, al volver OK, entra directo (auto-login).
     * El alta con Google se activa cuando la instalación configure sus propias
     * credenciales (Configuración → Integraciones); aquí queda el botón listo.
     */
    private void showRegister() {
        VBox panel = new VBox(12);
        panel.setAlignment(Pos.CENTER_LEFT);
        panel.setPadding(new Insets(36));
        panel.setMaxWidth(480);
        panel.getStyleClass().add("summary-card");

        Label title = new Label(t("register.title"));
        title.getStyleClass().add("hero-title");
        Label subtitle = new Label(t("register.subtitle"));
        subtitle.getStyleClass().add("hero-body");
        subtitle.setWrapText(true);

        ComboBox<String> typeCombo = new ComboBox<>();
        typeCombo.getItems().addAll("ADVISORY", "BUSINESS");
        typeCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String s) { return s == null ? "" : t("register.type." + s); }
            @Override public String fromString(String s) { return null; }
        });
        typeCombo.getSelectionModel().select("ADVISORY");
        typeCombo.setMaxWidth(Double.MAX_VALUE);

        TextField legalName = field(t("register.legal_name"));
        TextField taxId = field(t("register.tax_id"));
        TextField addressLine = field(t("register.address"));
        TextField city = field(t("register.city"));
        TextField province = field(t("register.province"));
        TextField postalCode = field(t("register.postal_code"));
        TextField displayName = field(t("register.owner_name"));
        TextField email = field(t("register.email"));
        PasswordField password = new PasswordField();
        password.setPromptText(t("register.password"));
        password.setMaxWidth(Double.MAX_VALUE);
        PasswordField password2 = new PasswordField();
        password2.setPromptText(t("register.password2"));
        password2.setMaxWidth(Double.MAX_VALUE);

        GridPane g = new GridPane();
        g.setHgap(10); g.setVgap(8);
        int r = 0;
        g.add(new Label(t("register.type")), 0, r); g.add(typeCombo, 1, r++);
        g.add(new Label(t("register.legal_name")), 0, r); g.add(legalName, 1, r++);
        g.add(new Label(t("register.tax_id")), 0, r); g.add(taxId, 1, r++);
        g.add(new Label(t("register.address")), 0, r); g.add(addressLine, 1, r++);
        g.add(new Label(t("register.city")), 0, r); g.add(city, 1, r++);
        g.add(new Label(t("register.province")), 0, r); g.add(province, 1, r++);
        g.add(new Label(t("register.postal_code")), 0, r); g.add(postalCode, 1, r++);
        g.add(new Label(t("register.owner_name")), 0, r); g.add(displayName, 1, r++);
        g.add(new Label(t("register.email")), 0, r); g.add(email, 1, r++);
        g.add(new Label(t("register.password")), 0, r); g.add(passwordWithToggle(password), 1, r++);
        g.add(new Label(t("register.password2")), 0, r); g.add(passwordWithToggle(password2), 1, r++);
        javafx.scene.layout.ColumnConstraints c0 = new javafx.scene.layout.ColumnConstraints();
        javafx.scene.layout.ColumnConstraints c1 = new javafx.scene.layout.ColumnConstraints();
        c1.setHgrow(Priority.ALWAYS); c1.setFillWidth(true);
        g.getColumnConstraints().addAll(c0, c1);

        Button createBtn = new Button(t("register.submit"));
        createBtn.getStyleClass().add("button-primary");
        createBtn.setMaxWidth(Double.MAX_VALUE);
        createBtn.setOnAction(ev -> doRegister(createBtn, typeCombo.getValue(), legalName.getText(), taxId.getText(),
                addressLine.getText(), city.getText(), province.getText(), postalCode.getText(),
                displayName.getText(), email.getText(), password.getText(), password2.getText()));

        Button googleBtn = new Button(t("register.with_google"));
        googleBtn.setGraphic(icon("fab-google"));
        googleBtn.setMaxWidth(Double.MAX_VALUE);
        googleBtn.setOnAction(ev -> startGoogleRegister(googleBtn, typeCombo.getValue(),
                legalName.getText(), taxId.getText(), addressLine.getText(), city.getText(),
                province.getText(), postalCode.getText(), displayName.getText()));

        javafx.scene.control.Hyperlink back = new javafx.scene.control.Hyperlink(t("register.back"));
        back.setOnAction(ev -> showEmailLogin());

        panel.getChildren().addAll(title, subtitle, g, createBtn,
                new Separator(), googleBtn, back);

        javafx.scene.control.ScrollPane sp = new javafx.scene.control.ScrollPane(panel);
        sp.setFitToWidth(true);
        sp.getStyleClass().add("edge-to-edge");
        BorderPane wrapper = new BorderPane(sp);
        wrapper.setPadding(new Insets(40));
        BorderPane.setAlignment(sp, Pos.CENTER);
        root.setTop(null); root.setLeft(null); root.setBottom(null);
        root.setCenter(wrapper);
    }

    private TextField field(String prompt) {
        TextField f = new TextField();
        f.setPromptText(prompt);
        f.setMaxWidth(Double.MAX_VALUE);
        return f;
    }

    /**
     * Envuelve un {@link PasswordField} con un botón "ojo" para ver/ocultar la
     * contraseña. Se mantiene el mismo {@code PasswordField} (su {@code getText()}
     * sigue valiendo) y se superpone un TextField visible sincronizado por
     * binding bidireccional. Devuelve el contenedor a colocar en el layout.
     */
    private Node passwordWithToggle(PasswordField pf) {
        TextField visible = new TextField();
        visible.setPromptText(pf.getPromptText());
        visible.setManaged(false);
        visible.setVisible(false);
        visible.textProperty().bindBidirectional(pf.textProperty());
        javafx.scene.layout.StackPane stack = new javafx.scene.layout.StackPane(pf, visible);
        HBox.setHgrow(stack, Priority.ALWAYS);

        javafx.scene.control.ToggleButton eye = new javafx.scene.control.ToggleButton();
        eye.setGraphic(icon("fas-eye"));
        eye.setFocusTraversable(false);
        eye.setTooltip(new javafx.scene.control.Tooltip(t("password.toggle")));
        eye.setOnAction(e -> {
            boolean show = eye.isSelected();
            pf.setVisible(!show); pf.setManaged(!show);
            visible.setVisible(show); visible.setManaged(show);
            eye.setGraphic(icon(show ? "fas-eye-slash" : "fas-eye"));
        });

        HBox box = new HBox(4, stack, eye);
        box.setAlignment(Pos.CENTER_LEFT);
        box.setMaxWidth(Double.MAX_VALUE);
        return box;
    }

    private void doRegister(Button submitBtn, String type, String legalName, String taxId, String address,
                            String city, String province, String postalCode, String displayName,
                            String email, String password, String password2) {
        if (blankAny(type, legalName, taxId, address, city, displayName, email, password)) {
            showError(t("register.title"), t("register.err.required"));
            return;
        }
        if (!password.equals(password2)) {
            showError(t("register.title"), t("register.err.password_mismatch"));
            return;
        }
        if (password.length() < 8) {
            showError(t("register.title"), t("register.err.password_short"));
            return;
        }
        // Anti doble-clic: el botón se bloquea hasta que la llamada termina.
        submitBtn.setDisable(true);
        Task<Void> task = new Task<>() {
            @Override protected Void call() throws Exception {
                authApiClient.register(type, legalName.trim(), taxId.trim(), address.trim(),
                        city.trim(), province == null ? "" : province.trim(),
                        postalCode == null ? "" : postalCode.trim(),
                        displayName.trim(), email.trim(), password);
                return null;
            }
        };
        task.setOnSucceeded(ev -> handleLoginSuccess());
        task.setOnFailed(ev -> {
            submitBtn.setDisable(false);
            showError(t("register.err.title"),
                    task.getException() == null ? t("register.err.generic") : task.getException().getMessage());
        });
        start(task, "register");
    }

    private boolean blankAny(String... vs) {
        for (String v : vs) if (v == null || v.isBlank()) return true;
        return false;
    }

    /** Trae la ventana de la app al frente (tras entrar con Google, que deja el
     *  foco en el navegador del sistema). */
    private void bringToFront() {
        try {
            if (root != null && root.getScene() != null
                    && root.getScene().getWindow() instanceof javafx.stage.Stage st) {
                st.setIconified(false);
                st.toFront();
                st.requestFocus();
            }
        } catch (Exception ignored) {
        }
    }

    /** REG-3 — Login con Google: abre el navegador, intercambia en backend, entra. */
    private void startGoogleLogin(Button btn) {
        btn.setDisable(true);
        Task<Void> task = new Task<>() {
            @Override protected Void call() throws Exception {
                com.benjagest.ui.service.AuthApiClient.GoogleConfig cfg = authApiClient.googleConfig();
                if (!cfg.enabled() || cfg.clientId() == null) throw new IllegalStateException(t("google.not_configured"));
                authApiClient.googleLogin(com.benjagest.ui.service.GoogleDesktopOAuth.authorize(cfg.clientId()));
                return null;
            }
        };
        task.setOnSucceeded(e -> { handleLoginSuccess(); bringToFront(); });
        task.setOnFailed(e -> { btn.setDisable(false); showError(t("google.title"),
                task.getException() == null ? t("google.failed") : task.getException().getMessage()); });
        start(task, "google-login");
    }

    /** REG-3 — Alta con Google: valida los datos de empresa, abre el navegador y crea la cuenta. */
    private void startGoogleRegister(Button btn, String type, String legalName, String taxId, String address,
                                     String city, String province, String postalCode, String displayName) {
        if (blankAny(type, legalName, taxId, address, city)) {
            showError(t("register.title"), t("register.err.required"));
            return;
        }
        btn.setDisable(true);
        Task<Void> task = new Task<>() {
            @Override protected Void call() throws Exception {
                com.benjagest.ui.service.AuthApiClient.GoogleConfig cfg = authApiClient.googleConfig();
                if (!cfg.enabled() || cfg.clientId() == null) throw new IllegalStateException(t("google.not_configured"));
                com.benjagest.ui.service.GoogleDesktopOAuth.Result oauth =
                        com.benjagest.ui.service.GoogleDesktopOAuth.authorize(cfg.clientId());
                authApiClient.googleRegister(oauth, type, legalName.trim(), taxId.trim(), address.trim(),
                        city.trim(), province == null ? "" : province.trim(),
                        postalCode == null ? "" : postalCode.trim(),
                        displayName == null ? "" : displayName.trim());
                return null;
            }
        };
        task.setOnSucceeded(e -> { handleLoginSuccess(); bringToFront(); });
        task.setOnFailed(e -> { btn.setDisable(false); showError(t("register.err.title"),
                task.getException() == null ? t("google.failed") : task.getException().getMessage()); });
        start(task, "google-register");
    }

    private void login(String email, String password) {
        if (email == null || email.isBlank() || password == null || password.isBlank()) {
            showError("Faltan datos", "Introduce email y contrasena para continuar.");
            return;
        }
        Task<Void> task = new Task<>() {
            @Override
            protected Void call() throws Exception {
                authApiClient.login(email.trim(), password);
                return null;
            }
        };
        task.setOnSucceeded(event -> handleLoginSuccess());
        task.setOnFailed(event -> showError(t("loginFailed"), t("loginFailedDetail")));
        start(task, "auth-login");
    }

