    private final com.benjagest.ui.service.TimeClockApiClient timeClockApi =
            new com.benjagest.ui.service.TimeClockApiClient();
    private TableView<com.benjagest.ui.model.TimeClockEntry> timeClockTable;
    // FJ-3 — banner + botones del fichaje, para resaltar el que toca segun la jornada.
    private Label timeClockSuggestBanner;
    // FJ — enlace para reactivar los botones cuando se desactivan los no sugeridos.
    private javafx.scene.control.Hyperlink timeClockOverrideLink;
    private final java.util.Map<String, Button> timeClockPunchButtons = new java.util.HashMap<>();

    private void showTimeClock() {
        // EMP-USER-MAP: el employeeId NO es el userId. Buscamos primero
        // la ficha en `employees` por (user_id, company_id). Si el
        // usuario no tiene ficha (típico de OWNERs de empresa que nunca
        // se dieron de alta como empleado), pintamos pantalla amigable
        // con instrucciones en lugar de explotar al primer fichaje.
        Task<com.benjagest.ui.service.TimeClockApiClient.MyEmployee> resolve = new Task<>() {
            @Override
            protected com.benjagest.ui.service.TimeClockApiClient.MyEmployee call() throws Exception {
                return timeClockApi.me();
            }
        };
        resolve.setOnSucceeded(ev -> renderTimeClock(resolve.getValue()));
        resolve.setOnFailed(ev -> {
            Throwable err = resolve.getException();
            if (err instanceof com.benjagest.ui.service.TimeClockApiClient.NotEnrolledException nee) {
                renderTimeClockNotEnrolled(nee.getMessage());
            } else {
                setCenterAnimated(scroll(errorPanel(t("timeclock.fail.title"))));
            }
        });
        start(resolve, "timeclock-resolve-employee");
    }

    /** Pinta una pantalla amigable cuando el usuario no tiene ficha de
     *  empleado en la empresa activa — no puede fichar hasta que el
     *  admin lo dé de alta en Personal > Empleados. */
    private void renderTimeClockNotEnrolled(String backendMsg) {
        Label header = label(t("timeclock.header"), "settings-section-title");
        Label icon = new Label("⚠");
        icon.setStyle("-fx-font-size: 48px;");
        Label title = new Label(t("timeclock.not_enrolled.title"));
        title.getStyleClass().add("settings-section-title");
        Label body = new Label(backendMsg != null && !backendMsg.isBlank()
                ? backendMsg
                : t("timeclock.not_enrolled.body"));
        body.setWrapText(true);
        body.getStyleClass().add("settings-hint");
        VBox notice = new VBox(12, icon, title, body);
        notice.setPadding(new Insets(40));
        notice.setAlignment(Pos.CENTER);
        VBox content = new VBox(16, header, notice);
        content.setPadding(new Insets(20));
        setCenterAnimated(scroll(content));
    }

    private void renderTimeClock(com.benjagest.ui.service.TimeClockApiClient.MyEmployee me) {
        String employeeId = me.employeeId();
        // Header explicativo: contexto legal RD 8/2019 y aclaración de
        // que el CSV emitido al fichar sirve para verificación pública.
        Label header = label(t("timeclock.header"), "settings-section-title");
        Label hint = new Label(t("timeclock.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        // Bloque grande con botones de fichaje. Tamaño visible para
        // que sirva también en kiosko (los empleados fichan rápido).
        Button inBtn = bigPunchButton(t("timeclock.action.in"), "fas-sign-in-alt", "IN", employeeId);
        Button outBtn = bigPunchButton(t("timeclock.action.out"), "fas-sign-out-alt", "OUT", employeeId);
        Button breakStartBtn = bigPunchButton(t("timeclock.action.break_start"), "fas-coffee", "BREAK_START", employeeId);
        Button breakEndBtn = bigPunchButton(t("timeclock.action.break_end"), "fas-utensils", "BREAK_END", employeeId);
        HBox punchRow = new HBox(12, inBtn, outBtn, breakStartBtn, breakEndBtn);

        // FJ-3 — registro de botones para poder resaltar el que toca + banner de sugerencia.
        timeClockPunchButtons.clear();
        timeClockPunchButtons.put("IN", inBtn);
        timeClockPunchButtons.put("OUT", outBtn);
        timeClockPunchButtons.put("BREAK_START", breakStartBtn);
        timeClockPunchButtons.put("BREAK_END", breakEndBtn);
        timeClockSuggestBanner = new Label();
        timeClockSuggestBanner.setWrapText(true);
        timeClockSuggestBanner.setMaxWidth(Double.MAX_VALUE);
        timeClockSuggestBanner.setManaged(false);
        timeClockSuggestBanner.setVisible(false);
        // FJ — "Fichar otra cosa": reactiva los botones desactivados (desviación real).
        timeClockOverrideLink = new javafx.scene.control.Hyperlink(t("timeclock.suggest.override"));
        timeClockOverrideLink.setManaged(false);
        timeClockOverrideLink.setVisible(false);
        timeClockOverrideLink.setOnAction(ev -> {
            timeClockPunchButtons.values().forEach(b -> b.setDisable(false));
            timeClockOverrideLink.setManaged(false);
            timeClockOverrideLink.setVisible(false);
        });

        // Listado últimos N fichajes del empleado.
        timeClockTable = new TableView<>();
        timeClockTable.getStyleClass().add("data-table");
        timeClockTable.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        timeClockTable.setPlaceholder(new Label(t("timeclock.placeholder.empty")));

        TableColumn<com.benjagest.ui.model.TimeClockEntry, String> colWhen =
                new TableColumn<>(t("timeclock.col.when"));
        colWhen.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().eventTimeIso()));
        colWhen.setPrefWidth(200);
        colWhen.setComparator(ISO_DATE_COMPARATOR);
        TableColumn<com.benjagest.ui.model.TimeClockEntry, String> colType =
                new TableColumn<>(t("timeclock.col.type"));
        colType.setCellValueFactory(c -> new SimpleStringProperty(localizedPunchType(c.getValue().eventType())));
        colType.setPrefWidth(150);
        TableColumn<com.benjagest.ui.model.TimeClockEntry, String> colOrigin =
                new TableColumn<>(t("timeclock.col.origin"));
        colOrigin.setCellValueFactory(c -> new SimpleStringProperty(localizedEnum("timeclock_origin", c.getValue().origin())));
        colOrigin.setPrefWidth(100);
        TableColumn<com.benjagest.ui.model.TimeClockEntry, String> colStatus =
                new TableColumn<>(t("timeclock.col.status"));
        colStatus.setCellValueFactory(c -> new SimpleStringProperty(localizedEnum("timeclock_status", c.getValue().status())));
        colStatus.setPrefWidth(110);
        timeClockTable.getColumns().addAll(java.util.List.of(colWhen, colType, colOrigin, colStatus));

        Button refresh = new Button(t("timeclock.action.refresh"));
        refresh.setGraphic(icon("fas-sync"));
        refresh.setOnAction(ev -> reloadTimeClock(employeeId));

        // Bloque de exportación para Inspección de Trabajo / Hacienda.
        // Defaults: trimestre actual completo (lo más habitual).
        Label exportTitle = label(t("timeclock.export.title"), "settings-section-title");
        Label exportHint = new Label(t("timeclock.export.hint"));
        exportHint.setWrapText(true);
        exportHint.getStyleClass().add("settings-hint");
        java.time.LocalDate today = java.time.LocalDate.now();
        int quarter = (today.getMonthValue() - 1) / 3;
        java.time.LocalDate quarterStart = java.time.LocalDate.of(today.getYear(), quarter * 3 + 1, 1);
        java.time.LocalDate quarterEnd = quarterStart.plusMonths(3).minusDays(1);
        DatePicker fromPicker = new DatePicker(quarterStart);
        DatePicker toPicker = new DatePicker(quarterEnd);
        Label fromLbl = new Label(t("timeclock.export.from"));
        Label toLbl = new Label(t("timeclock.export.to"));
        Button exportPdfBtn = new Button(t("timeclock.export.pdf"));
        exportPdfBtn.setGraphic(icon("fas-file-pdf"));
        exportPdfBtn.getStyleClass().add("button-primary");
        exportPdfBtn.setOnAction(ev -> downloadTimeClockExport("pdf",
                fromPicker.getValue(), toPicker.getValue(), employeeId));
        Button exportCsvBtn = new Button(t("timeclock.export.csv"));
        exportCsvBtn.setGraphic(icon("fas-file-csv"));
        exportCsvBtn.setOnAction(ev -> downloadTimeClockExport("csv",
                fromPicker.getValue(), toPicker.getValue(), employeeId));
        HBox exportRow = new HBox(8, fromLbl, fromPicker, toLbl, toPicker,
                exportPdfBtn, exportCsvBtn);
        exportRow.setAlignment(Pos.CENTER_LEFT);
        VBox exportBlock = new VBox(8, exportTitle, exportHint, exportRow);

        VBox body = new VBox(16, header, hint, timeClockSuggestBanner, punchRow, timeClockOverrideLink,
                refresh, timeClockTable,
                new Separator(), exportBlock);
        body.setPadding(new Insets(20));

        setCenterAnimated(scroll(body));
        reloadTimeClock(employeeId);
        refreshTimeClockSuggestion();
        // NOTIF-RT — refresco en vivo de la lista + sugerencia cuando llega un fichaje.
        com.benjagest.ui.support.RefreshBus.subscribe(
                com.benjagest.ui.support.RefreshBus.TOPIC_TIMECLOCK,
                () -> { reloadTimeClock(employeeId); refreshTimeClockSuggestion(); },
                timeClockTable);
    }

    /**
     * FJ-3 — Pide la sugerencia de "que toca fichar ahora" segun la jornada
     * asignada y, si estamos en ventana (+/-15 min), resalta ese boton y muestra
     * un banner. Fuera de ventana o jornada completa: banner suave. Sin jornada
     * hoy: no muestra nada (todos los botones normales). Nunca bloquea ni rompe
     * el fichaje si la sugerencia falla.
     */
    private void refreshTimeClockSuggestion() {
        if (timeClockSuggestBanner == null) return;
        Task<com.benjagest.ui.service.TimeClockApiClient.Suggestion> task = new Task<>() {
            @Override protected com.benjagest.ui.service.TimeClockApiClient.Suggestion call() throws Exception {
                return timeClockApi.suggestion();
            }
        };
        task.setOnSucceeded(ev -> applyTimeClockSuggestion(task.getValue()));
        task.setOnFailed(ev -> applyTimeClockSuggestion(null)); // silencioso
        start(task, "timeclock-suggestion");
    }

    private void applyTimeClockSuggestion(com.benjagest.ui.service.TimeClockApiClient.Suggestion s) {
        // Reset: limpia resaltado y reactiva todos los botones; oculta el override.
        timeClockPunchButtons.values().forEach(b -> {
            b.getStyleClass().remove("punch-suggested");
            b.setDisable(false);
        });
        if (timeClockOverrideLink != null) {
            timeClockOverrideLink.setManaged(false);
            timeClockOverrideLink.setVisible(false);
        }
        Label banner = timeClockSuggestBanner;
        banner.getStyleClass().removeAll("suggest-banner", "suggest-banner-soft");
        if (s == null || !s.hasSchedule()) {
            banner.setManaged(false);
            banner.setVisible(false);
            return;
        }
        banner.setManaged(true);
        banner.setVisible(true);
        if (!s.hasAction()) { // jornada completa
            banner.getStyleClass().addAll("suggest-banner", "suggest-banner-soft");
            banner.setText(t("timeclock.suggest.completed"));
            return;
        }
        String actionLabel = localizedPunchType(s.action());
        if (s.inWindow()) {
            banner.getStyleClass().add("suggest-banner");
            banner.setText(t("timeclock.suggest.now").replace("{action}", actionLabel)
                    + "  " + t("timeclock.suggest.scheduled")
                            .replace("{time}", nz(s.scheduledTime()))
                            .replace("{from}", nz(s.windowFrom()))
                            .replace("{to}", nz(s.windowTo())));
            Button b = timeClockPunchButtons.get(s.action());
            if (b != null && !b.getStyleClass().contains("punch-suggested")) {
                b.getStyleClass().add("punch-suggested");
            }
            // CONTENDO: solo el botón que toca. Desactiva los demás para no confundir;
            // "Fichar otra cosa" los reactiva (desviación real, RD 8/2019).
            timeClockPunchButtons.forEach((code, btn) -> btn.setDisable(!code.equals(s.action())));
            if (timeClockOverrideLink != null) {
                timeClockOverrideLink.setManaged(true);
                timeClockOverrideLink.setVisible(true);
            }
        } else {
            banner.getStyleClass().addAll("suggest-banner", "suggest-banner-soft");
            banner.setText(t("timeclock.suggest.next").replace("{action}", actionLabel)
                            .replace("{time}", nz(s.scheduledTime()))
                    + "  " + t("timeclock.suggest.next_hint").replace("{from}", nz(s.windowFrom())));
        }
    }

    private static String nz(String s) { return s == null ? "" : s; }

    /** Descarga el export de fichajes y ofrece guardarlo. */
    private void downloadTimeClockExport(String format,
                                          java.time.LocalDate from, java.time.LocalDate to,
                                          String employeeId) {
        if (from == null || to == null || from.isAfter(to)) {
            showError(t("timeclock.export.fail.range.title"),
                    t("timeclock.export.fail.range.body"));
            return;
        }
        Task<byte[]> task = new Task<>() {
            @Override protected byte[] call() throws Exception {
                return "pdf".equals(format)
                        ? timeClockApi.exportPdf(from.toString(), to.toString(), employeeId)
                        : timeClockApi.exportCsv(from.toString(), to.toString(), employeeId);
            }
        };
        task.setOnSucceeded(ev -> {
            byte[] body = task.getValue();
            javafx.stage.FileChooser fc = new javafx.stage.FileChooser();
            fc.setInitialFileName("fichajes-" + from + "_" + to + "." + format);
            fc.getExtensionFilters().add(new javafx.stage.FileChooser.ExtensionFilter(
                    format.toUpperCase(), "*." + format));
            java.io.File target = fc.showSaveDialog(root.getScene().getWindow());
            if (target == null) return;
            try {
                java.nio.file.Files.write(target.toPath(), body);
                showInfo(t("timeclock.export.ok.title"),
                        t("timeclock.export.ok.body") + "\n" + target.getAbsolutePath());
            } catch (java.io.IOException ex) {
                showError(t("timeclock.export.fail.write.title"), ex.getMessage());
            }
        });
        task.setOnFailed(ev -> showError(t("timeclock.export.fail.title"),
                t("timeclock.export.fail.body")));
        start(task, "timeclock-export-" + format);
    }

    private Button bigPunchButton(String text, String iconName, String eventType, String employeeId) {
        Button btn = new Button(text);
        btn.setGraphic(icon(iconName));
        btn.getStyleClass().add("invoice-validate-action");
        btn.setMinHeight(50);
        btn.setMinWidth(160);
        btn.setOnAction(ev -> punch(employeeId, eventType));
        return btn;
    }

    private void punch(String employeeId, String eventType) {
        Task<com.benjagest.ui.service.TimeClockApiClient.PunchOutcome> task = new Task<>() {
            @Override
            protected com.benjagest.ui.service.TimeClockApiClient.PunchOutcome call() throws Exception {
                return timeClockApi.punch(employeeId, eventType);
            }
        };
        task.setOnSucceeded(ev -> {
            var outcome = task.getValue();
            // Mostramos el CSV en un dialog con TextField copiable para
            // que el trabajador lo guarde si lo necesita (justificante).
            javafx.scene.control.TextField field = new javafx.scene.control.TextField(outcome.csv());
            field.setEditable(false);
            field.setPrefColumnCount(20);
            Alert ok = new Alert(Alert.AlertType.INFORMATION);
            ok.setHeaderText(t("timeclock.success.title"));
            VBox content = new VBox(8,
                    new Label(t("timeclock.success.csv_label")),
                    field);
            // TC-CAL (Benjamin 2026-06-10): si el backend devolvio
            // holidayWarning, anadir tarjeta amarilla con icono y
            // nombre del festivo. No bloquea — solo informa.
            if (outcome.hasHolidayWarning()) {
                Label warnTitle = new Label(t("timeclock.holiday_warning.title"));
                warnTitle.getStyleClass().add("holiday-warning-title");
                String typeLabel = humanizeHolidayType(outcome.holidayType());
                Label warnBody = new Label(t("timeclock.holiday_warning.body")
                        .replace("{type}", typeLabel)
                        .replace("{name}", outcome.holidayName()));
                warnBody.setWrapText(true);
                warnBody.getStyleClass().add("holiday-warning-body");
                VBox warnBox = new VBox(4, warnTitle, warnBody);
                warnBox.getStyleClass().add("holiday-warning-card");
                warnBox.setPadding(new Insets(10));
                content.getChildren().add(warnBox);
            }
            content.setPadding(new Insets(8));
            ok.getDialogPane().setContent(content);
            ok.showAndWait();
            reloadTimeClock(employeeId);
            refreshTimeClockSuggestion();
        });
        task.setOnFailed(ev -> showError(t("timeclock.fail.title"), t("timeclock.fail.body")));
        start(task, "timeclock-punch");
    }

    /** TC-CAL — humaniza el code de holiday_type para el warning. */
    private String humanizeHolidayType(String raw) {
        if (raw == null || raw.isBlank()) return "";
        return switch (raw.trim().toUpperCase(java.util.Locale.ROOT)) {
            case "FESTIVO" -> t("holiday.type.festivo");
            case "AJUSTE" -> t("holiday.type.ajuste");
            case "CIERRE" -> t("holiday.type.cierre");
            default -> raw;
        };
    }

    private void reloadTimeClock(String employeeId) {
        Task<java.util.List<com.benjagest.ui.model.TimeClockEntry>> task = new Task<>() {
            @Override
            protected java.util.List<com.benjagest.ui.model.TimeClockEntry> call() throws Exception {
                return timeClockApi.recent(employeeId, 50);
            }
        };
        task.setOnSucceeded(ev -> {
            if (timeClockTable != null) {
                timeClockTable.setItems(FXCollections.observableArrayList(task.getValue()));
            }
        });
        task.setOnFailed(ev -> {
            if (timeClockTable != null) timeClockTable.getItems().clear();
        });
        start(task, "timeclock-reload");
    }

    private String localizedPunchType(String code) {
        if (code == null) return "";
        // Para los 4 tipos estándar usamos las keys legacy que ya existían.
        // Para tipos custom (creados por el OWNER) caemos a humanizeFromKey
        // con prefix labor.cfg_timeclock.code.* (mismo prefix que el listado
        // de configuración). Así una cláusula "COMIDA" muestra "Comida"
        // si hay key, y "COMIDA" como último recurso — pero NUNCA debería
        // salir el código en bruto si el i18n está completo.
        return switch (code) {
            case "IN" -> t("timeclock.type.in");
            case "OUT" -> t("timeclock.type.out");
            case "BREAK_START" -> t("timeclock.type.break_start");
            case "BREAK_END" -> t("timeclock.type.break_end");
            default -> humanizeFromKey("labor.cfg_timeclock.code." + code,
                    humanizeCodeSafe(code));
        };
    }

    /** Última red de seguridad: COMIDA_LIBRE → "Comida libre". */
    private static String humanizeCodeSafe(String code) {
        if (code == null || code.isEmpty()) return "";
        String low = code.replace('_', ' ').toLowerCase(java.util.Locale.ROOT);
        return Character.toUpperCase(low.charAt(0)) + low.substring(1);
    }

    // ===================================================================
    //  Pantalla Configuracion (Slice C3): TabPane con 3 pestanas
    // ===================================================================

    private void showSettings() {
        // Cargamos los tres recursos en paralelo (3 llamadas REST) y
        // construimos el TabPane cuando todas hayan respondido. Si una
        // falla, mostramos error.
        Task<SettingsBundle> task = new Task<>() {
            @Override
            protected SettingsBundle call() throws Exception {
                CompanyData company = settingsApiClient.getCompany();
                EmailConfig email = settingsApiClient.getEmailConfig();
                List<CompanyModuleEntry> modules = settingsApiClient.listModules();
                return new SettingsBundle(company, email, modules);
            }
        };
        task.setOnSucceeded(event -> setCenterAnimated(settingsView(task.getValue())));
        task.setOnFailed(event -> setCenterAnimated(scroll(errorPanel(t("settings.load_failed")))));
        start(task, "settings-load");
    }

    /**
     * REG-3 — Configuración → Integraciones → Google. El admin pega el Client ID
     * y el Client Secret de SU proyecto Google (tipo "Aplicación de escritorio").
     * El secreto se guarda cifrado en el backend y nunca se vuelve a mostrar.
     */
    /**
     * Panel de conexión con Google (Gmail + Calendar) reutilizable. Vive
     * dentro del tab Correo, visible solo cuando el proveedor elegido es
     * Google. La configuración de "mi propio proyecto Google" (client-id/
     * secret per-instalación) queda plegada como avanzado: por defecto se
     * usan las credenciales centrales de BENJAGEST.
     */
    private VBox googleIntegrationPanel() {
        Label title = new Label(t("settings.integrations.google.title"));
        title.getStyleClass().add("settings-section-title");
        Label hint = new Label(t("settings.integrations.google.hint"));
        hint.getStyleClass().add("settings-hint"); hint.setWrapText(true); hint.setMaxWidth(620);
        Label steps = new Label(t("settings.integrations.google.steps"));
        steps.getStyleClass().add("settings-hint"); steps.setWrapText(true); steps.setMaxWidth(620);

        TextField clientId = new TextField();
        clientId.setPromptText("Client ID (…apps.googleusercontent.com)");
        clientId.setMaxWidth(Double.MAX_VALUE);
        PasswordField clientSecret = new PasswordField();
        clientSecret.setPromptText(t("settings.integrations.google.secret_prompt"));
        Label status = new Label();
        status.getStyleClass().add("settings-hint");

        Button save = new Button(t("settings.integrations.google.save"));
        save.getStyleClass().add("button-primary");

        Runnable loadStatus = () -> {
            Task<com.benjagest.ui.service.AuthApiClient.GoogleConfig> tk = new Task<>() {
                @Override protected com.benjagest.ui.service.AuthApiClient.GoogleConfig call() {
                    return authApiClient.googleConfig();
                }
            };
            tk.setOnSucceeded(e -> {
                var c = tk.getValue();
                if (c.clientId() != null) clientId.setText(c.clientId());
                status.setText(c.enabled()
                        ? t("settings.integrations.google.status.enabled")
                        : t("settings.integrations.google.status.disabled"));
            });
            start(tk, "google-cfg-load");
        };

        save.setOnAction(e -> {
            if (clientId.getText() == null || clientId.getText().isBlank()) {
                showError(t("settings.integrations.google.title"), t("settings.integrations.google.need_client_id"));
                return;
            }
            save.setDisable(true);
            Task<Void> tk = new Task<>() {
                @Override protected Void call() throws Exception {
                    authApiClient.saveGoogleConfig(clientId.getText().trim(), clientSecret.getText());
                    return null;
                }
            };
            tk.setOnSucceeded(ev -> {
                save.setDisable(false); clientSecret.clear(); loadStatus.run();
                showInfo(t("settings.integrations.google.title"), t("settings.integrations.google.saved"));
            });
            tk.setOnFailed(ev -> { save.setDisable(false); showError(t("settings.integrations.google.title"),
                    humanizeBackendError(tk.getException() == null ? "" : tk.getException().getMessage())); });
            start(tk, "google-cfg-save");
        });

        GridPane g = new GridPane();
        g.setHgap(10); g.setVgap(8);
        g.add(new Label(t("settings.integrations.google.client_id")), 0, 0); g.add(clientId, 1, 0);
        g.add(new Label(t("settings.integrations.google.secret")), 0, 1); g.add(passwordWithToggle(clientSecret), 1, 1);
        javafx.scene.layout.ColumnConstraints c1 = new javafx.scene.layout.ColumnConstraints();
        c1.setHgrow(Priority.ALWAYS); c1.setFillWidth(true);
        g.getColumnConstraints().addAll(new javafx.scene.layout.ColumnConstraints(), c1);

        // --- Conectar Gmail para enviar correo (sin contraseña de aplicación) ---
        Label gmailTitle = new Label(t("settings.integrations.gmail.title"));
        gmailTitle.getStyleClass().add("settings-section-title");
        Label gmailHint = new Label(t("settings.integrations.gmail.hint"));
        gmailHint.getStyleClass().add("settings-hint"); gmailHint.setWrapText(true); gmailHint.setMaxWidth(620);
        Label gmailStatusLbl = new Label();
        gmailStatusLbl.getStyleClass().add("settings-hint");
        Button connectGmailBtn = new Button(t("settings.integrations.gmail.connect"));
        connectGmailBtn.getStyleClass().add("button-primary");
        connectGmailBtn.setGraphic(icon("fab-google"));
        Button disconnectGmailBtn = new Button(t("settings.integrations.gmail.disconnect"));
        disconnectGmailBtn.getStyleClass().add("button-danger-outline");

        Runnable loadGmail = () -> {
            Task<com.benjagest.ui.service.AuthApiClient.GmailStatus> tk = new Task<>() {
                @Override protected com.benjagest.ui.service.AuthApiClient.GmailStatus call() throws Exception {
                    return authApiClient.gmailStatus();
                }
            };
            tk.setOnSucceeded(e -> {
                var s = tk.getValue();
                gmailStatusLbl.setText(s.gmail()
                        ? t("settings.integrations.gmail.connected").replace("{email}", s.email() == null ? "" : s.email())
                        : t("settings.integrations.gmail.not_connected"));
                disconnectGmailBtn.setDisable(!s.gmail());
            });
            start(tk, "gmail-status");
        };

        connectGmailBtn.setOnAction(e -> {
            connectGmailBtn.setDisable(true);
            Task<Void> tk = new Task<>() {
                @Override protected Void call() throws Exception {
                    com.benjagest.ui.service.AuthApiClient.GoogleConfig cfg = authApiClient.googleConfig();
                    if (!cfg.enabled() || cfg.clientId() == null) throw new IllegalStateException(t("google.not_configured"));
                    var oauth = com.benjagest.ui.service.GoogleDesktopOAuth.authorize(cfg.clientId(),
                            "openid email profile https://www.googleapis.com/auth/gmail.send", true);
                    authApiClient.connectGmail(oauth);
                    return null;
                }
            };
            tk.setOnSucceeded(ev -> { connectGmailBtn.setDisable(false); bringToFront(); loadGmail.run();
                    showInfo(t("settings.integrations.gmail.title"), t("settings.integrations.gmail.connected_ok")); });
            tk.setOnFailed(ev -> { connectGmailBtn.setDisable(false); bringToFront();
                    showError(t("settings.integrations.gmail.title"),
                            tk.getException() == null ? t("google.failed") : tk.getException().getMessage()); });
            start(tk, "gmail-connect");
        });
        disconnectGmailBtn.setOnAction(e -> {
            Task<Void> tk = new Task<>() {
                @Override protected Void call() throws Exception { authApiClient.disconnectGmail(); return null; }
            };
            tk.setOnSucceeded(ev -> loadGmail.run());
            start(tk, "gmail-disconnect");
        });

        // --- Conectar Google Calendar y sincronizar con la Agenda ---
        Label calTitle = new Label(t("settings.integrations.calendar.title"));
        calTitle.getStyleClass().add("settings-section-title");
        Label calHint = new Label(t("settings.integrations.calendar.hint"));
        calHint.getStyleClass().add("settings-hint"); calHint.setWrapText(true); calHint.setMaxWidth(620);
        Label calStatusLbl = new Label();
        calStatusLbl.getStyleClass().add("settings-hint");
        Button connectCalBtn = new Button(t("settings.integrations.calendar.connect"));
        connectCalBtn.getStyleClass().add("button-primary");
        connectCalBtn.setGraphic(icon("fab-google"));
        Button syncCalBtn = new Button(t("settings.integrations.calendar.sync"));
        syncCalBtn.getStyleClass().add("button-secondary");
        syncCalBtn.setGraphic(icon("fas-sync-alt"));

        Runnable loadCalendar = () -> {
            Task<com.benjagest.ui.service.AuthApiClient.GmailStatus> tk = new Task<>() {
                @Override protected com.benjagest.ui.service.AuthApiClient.GmailStatus call() throws Exception {
                    return authApiClient.gmailStatus();
                }
            };
            tk.setOnSucceeded(e -> {
                var s = tk.getValue();
                calStatusLbl.setText(s.calendar()
                        ? t("settings.integrations.calendar.connected").replace("{email}", s.email() == null ? "" : s.email())
                        : t("settings.integrations.calendar.not_connected"));
                syncCalBtn.setDisable(!s.calendar());
            });
            start(tk, "calendar-status");
        };

        connectCalBtn.setOnAction(e -> {
            connectCalBtn.setDisable(true);
            Task<Void> tk = new Task<>() {
                @Override protected Void call() throws Exception {
                    com.benjagest.ui.service.AuthApiClient.GoogleConfig cfg = authApiClient.googleConfig();
                    if (!cfg.enabled() || cfg.clientId() == null) throw new IllegalStateException(t("google.not_configured"));
                    var oauth = com.benjagest.ui.service.GoogleDesktopOAuth.authorize(cfg.clientId(),
                            "openid email profile https://www.googleapis.com/auth/calendar", true);
                    authApiClient.connectCalendar(oauth);
                    return null;
                }
            };
            tk.setOnSucceeded(ev -> { connectCalBtn.setDisable(false); bringToFront(); loadCalendar.run();
                    showInfo(t("settings.integrations.calendar.title"), t("settings.integrations.calendar.connected_ok")); });
            tk.setOnFailed(ev -> { connectCalBtn.setDisable(false); bringToFront();
                    showError(t("settings.integrations.calendar.title"),
                            tk.getException() == null ? t("google.failed") : tk.getException().getMessage()); });
            start(tk, "calendar-connect");
        });
        syncCalBtn.setOnAction(e -> {
            syncCalBtn.setDisable(true);
            Task<com.benjagest.ui.service.AuthApiClient.CalendarSync> tk = new Task<>() {
                @Override protected com.benjagest.ui.service.AuthApiClient.CalendarSync call() throws Exception {
                    return authApiClient.calendarSync();
                }
            };
            tk.setOnSucceeded(ev -> { syncCalBtn.setDisable(false);
                    var r = tk.getValue();
                    com.benjagest.ui.support.RefreshBus.emit(com.benjagest.ui.support.RefreshBus.TOPIC_CALENDAR);
                    showInfo(t("settings.integrations.calendar.title"),
                            t("settings.integrations.calendar.sync_done")
                                    .replace("{pushed}", String.valueOf(r.pushed()))
                                    .replace("{pulled}", String.valueOf(r.pulled()))); });
            tk.setOnFailed(ev -> { syncCalBtn.setDisable(false);
                    showError(t("settings.integrations.calendar.title"),
                            tk.getException() == null ? t("google.failed") : tk.getException().getMessage()); });
            start(tk, "calendar-sync");
        });

        // Config per-instalación (client-id/secret propio): AVANZADO y plegado.
        // Por defecto se usan las credenciales centrales de BENJAGEST.
        VBox advancedContent = new VBox(8, hint, steps, g, new HBox(8, save), status);
        advancedContent.setPadding(new Insets(8, 0, 0, 0));
        javafx.scene.control.TitledPane advanced = new javafx.scene.control.TitledPane(
                t("settings.integrations.google.advanced"), advancedContent);
        advanced.setExpanded(false);
        advanced.setMaxWidth(680);

        VBox box = new VBox(12, title,
                gmailTitle, gmailHint,
                new HBox(8, connectGmailBtn, disconnectGmailBtn), gmailStatusLbl,
                new Separator(), calTitle, calHint,
                new HBox(8, connectCalBtn, syncCalBtn), calStatusLbl,
                new Separator(), advanced);
        box.setMaxWidth(680);
        javafx.application.Platform.runLater(loadStatus);
        javafx.application.Platform.runLater(loadGmail);
        javafx.application.Platform.runLater(loadCalendar);
        return box;
    }

    private VBox settingsView(SettingsBundle bundle) {
        VBox content = content();

        Label title = new Label(t("settings.shell.title"));
        title.getStyleClass().add("module-detail-title");
        Label subtitle = new Label(session.companyName());
        subtitle.getStyleClass().add("module-detail-description");
        VBox titleBox = new VBox(4, title, subtitle);
        StackPane moduleIcon = iconBubble("fas-cog", "module-title-icon");
        Region spacer = new Region();
        HBox.setHgrow(spacer, Priority.ALWAYS);
        HBox header = new HBox(16, titleBox, moduleIcon, spacer);
        header.setAlignment(Pos.CENTER_LEFT);
        header.getStyleClass().add("module-detail-header");

        TabPane tabs = new TabPane();
        tabs.getStyleClass().add("settings-tabs");
        tabs.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);
        Tab companyTab = new Tab(t("settings.tab.company"), settingsCompanyTab(bundle.company()));
        companyTab.setGraphic(icon("fas-building"));
        Tab ownersTab = new Tab(t("settings.tab.owners"), settingsOwnersTab());
        ownersTab.setGraphic(icon("fas-users"));
        Tab emailTab = new Tab(t("settings.tab.email"), settingsEmailTab(bundle.email()));
        emailTab.setGraphic(icon("fas-envelope"));
        Tab modulesTab = new Tab(t("settings.tab.modules"), settingsModulesTab(bundle.modules()));
        modulesTab.setGraphic(icon("fas-cubes"));
        Tab credentialsTab = new Tab(t("settings.tab.credentials"), settingsCredentialsTab());
        credentialsTab.setGraphic(icon("fas-key"));
        // El antiguo tab "Integraciones" (Google) se fusionó en el tab Correo:
        // el panel Google aparece al elegir el proveedor Google.
        Tab certificateTab = new Tab(t("settings.tab.certificate"), settingsCertificateTab());
        certificateTab.setGraphic(icon("fas-certificate"));
        Tab auditTab = new Tab(t("settings.tab.audit"), settingsAuditTab());
        auditTab.setGraphic(icon("fas-shield-alt"));
        // PORT-4 SESSION (2026-06-10) — pestaña Sesión con timeout
        // de inactividad, PIN de sesión y salvapantallas.
        Tab sessionTab = new Tab(t("settings.tab.session"), settingsSessionTab());
        sessionTab.setGraphic(icon("fas-user-clock"));

        // "Mi asesoría" solo tiene sentido para empresas CLIENT — una
        // asesoría no necesita otra asesoría que la asesore.
        tabs.getTabs().addAll(companyTab, ownersTab, emailTab, modulesTab,
                credentialsTab, certificateTab, sessionTab);
        if (appMode != AppMode.ADVISORY) {
            Tab advisoryTab = new Tab(t("settings.tab.my_advisory"), settingsMyAdvisoryTab());
            advisoryTab.setGraphic(icon("fas-handshake"));
            tabs.getTabs().add(advisoryTab);
            // Acuerdo TPB con la asesoria — solo cliente. Aqui el
            // empresario consulta estado, descarga el PDF firmado y
            // puede firmar/revocar.
            Tab myTpbTab = new Tab(t("settings.tab.my_tpb"), settingsMyTpbTab());
            myTpbTab.setGraphic(icon("fas-file-signature"));
            tabs.getTabs().add(myTpbTab);
        }
        // BOE-RSS — Alertas BOE solo en modo asesoría.
        if (appMode == AppMode.ADVISORY) {
            Tab boeTab = new Tab(t("settings.tab.boe_alerts"), settingsBoeAlertsTab());
            boeTab.setGraphic(icon("fas-newspaper"));
            tabs.getTabs().add(boeTab);
        }
        // BACKUP-LOCAL — pestaña Backups para OWNER/ADMIN.
        Tab backupTab = new Tab(t("settings.tab.backup"), settingsBackupTab());
        backupTab.setGraphic(icon("fas-hdd"));
        tabs.getTabs().add(backupTab);
        tabs.getTabs().add(auditTab);
        // El TabPane crece hasta el final del area central; sin esto, los
        // botones del pie de cada tab podrian quedar fuera de pantalla en
        // portatil.
        VBox.setVgrow(tabs, Priority.ALWAYS);

        content.getChildren().addAll(header, tabs);
        return content;
    }

    private record SettingsBundle(CompanyData company, EmailConfig email, List<CompanyModuleEntry> modules) {
    }

    // ----- Pestana Empresa -----

    private Node settingsCompanyTab(CompanyData company) {
        TextField legalName = textInput(company.legalName(), t("settings.company.prompt.legal_name"));
        TextField tradeName = textInput(company.tradeName(), t("settings.company.prompt.trade_name"));
        TextField taxId = textInput(company.taxIdentifier(), t("settings.company.prompt.tax_id"));
        TextField email = textInput(company.email(), t("settings.company.prompt.email"));
        TextField phone = textInput(company.phone(), t("settings.company.prompt.phone"));
        TextField website = textInput(company.website(), t("settings.company.prompt.website"));

        TextField addressLine = textInput(company.addressLine(), t("settings.company.prompt.address_line"));
        TextField city = textInput(company.city(), t("settings.company.prompt.city"));
        TextField province = textInput(company.province(), t("settings.company.prompt.province"));
        TextField postalCode = textInput(company.postalCode(), t("settings.company.prompt.postal_code"));
        TextField country = textInput(company.country() == null || company.country().isBlank() ? t("settings.company.country.default") : company.country(), t("settings.company.prompt.country"));

        TextField iban = textInput(company.iban(), t("settings.company.prompt.iban"));
        TextField registry = textInput(company.registryInformation(), t("settings.company.prompt.registry"));

        GridPane generalGrid = formGrid();
        addFormRow(generalGrid, 0, t("settings.company.field.legal_name"), legalName);
        addFormRow(generalGrid, 1, t("settings.company.field.trade_name"), tradeName);
        addFormRow(generalGrid, 2, t("settings.company.field.tax_id"), taxId);
        addFormRow(generalGrid, 3, t("settings.company.field.email"), email);
        addFormRow(generalGrid, 4, t("settings.company.field.phone"), phone);
        addFormRow(generalGrid, 5, t("settings.company.field.website"), website);

        GridPane addressGrid = formGrid();
        addFormRow(addressGrid, 0, t("settings.company.field.address"), addressLine);
        addFormRow(addressGrid, 1, t("settings.company.field.city"), city);
        addFormRow(addressGrid, 2, t("settings.company.field.province"), province);
        addFormRow(addressGrid, 3, t("settings.company.field.postal_code"), postalCode);
        addFormRow(addressGrid, 4, t("settings.company.field.country"), country);

        // Tras V22 (consolidacion 2026-06-04), los textos "de factura"
        // (pie, condiciones legales, exencion IVA, IVA reducido,
        // rectificativa) se editan SOLO en Facturacion -> Configuracion
        // -> Textos legales. Aqui solo quedan los datos administrativos
        // (IBAN para domiciliacion, registro mercantil para
        // identificacion juridica).
        GridPane billingGrid = formGrid();
        addFormRow(billingGrid, 0, t("settings.company.field.iban"), iban);
        addFormRow(billingGrid, 1, t("settings.company.field.registry"), registry);
        Label billingNote = new Label(t("settings.company.billing_note"));
        billingNote.setWrapText(true);
        billingNote.getStyleClass().add("settings-hint");

        Label typeNote = new Label(t("settings.company.type_note_prefix")
                + localizedEnum("customer_type", company.companyType())
                + t("settings.company.type_note_suffix"));
        typeNote.getStyleClass().add("settings-hint");

        Button save = new Button(t("settings.company.save"));
        save.setGraphic(icon("fas-save"));
        save.setOnAction(event -> saveCompany(new CompanyData(
                company.id(),
                legalName.getText(),
                tradeName.getText(),
                taxId.getText(),
                company.companyType(),
                email.getText(),
                phone.getText(),
                website.getText(),
                addressLine.getText(),
                city.getText(),
                province.getText(),
                postalCode.getText(),
                country.getText(),
                iban.getText(),
                registry.getText()
        )));

        HBox actions = new HBox(save);
        actions.getStyleClass().add("settings-actions");

        // PORT-4 LOGO (2026-06-10) — Sección Logo de empresa.
        Node logoSection = buildCompanyLogoSection();

        VBox body = new VBox(16,
                label(t("settings.company.section.general"), "settings-section-title"),
                generalGrid,
                typeNote,
                new Separator(),
                label(t("settings.company.section.address"), "settings-section-title"),
                addressGrid,
                new Separator(),
                label(t("settings.company.section.billing"), "settings-section-title"),
                label(t("settings.company.section.billing.hint"), "settings-hint"),
                billingGrid,
                billingNote,
                new Separator(),
                logoSection
        );

        Label sectionTitle = label(t("settings.company.section_label"), "settings-section-title");
        return tabLayout(sectionTitle, body, actions);
    }

    // ============================================================
    //  PORT-4 SESSION — Pestaña "Sesión" de Configuración
    // ============================================================
    private Node settingsSessionTab() {
        VBox body = new VBox(20);
        body.setPadding(new Insets(8));

        // --- Sección 1: bloqueo por inactividad ---
        Label lockTitle = label(t("settings.session.lock.title"), "settings-section-title");
        Label lockHint = new Label(t("settings.session.lock.hint"));
        lockHint.setWrapText(true);
        lockHint.getStyleClass().add("settings-hint");
        javafx.scene.control.Spinner<Integer> timeoutSpin =
                new javafx.scene.control.Spinner<>(0, 120, 0, 1);
        timeoutSpin.setEditable(true);
        Label timeoutSuffix = new Label(t("settings.session.lock.minutes"));
        HBox timeoutRow = new HBox(8, timeoutSpin, timeoutSuffix);
        timeoutRow.setAlignment(Pos.CENTER_LEFT);
        Label zeroHint = new Label(t("settings.session.lock.zero_hint"));
        zeroHint.getStyleClass().add("settings-hint");
        zeroHint.setWrapText(true);
        VBox lockSection = new VBox(8, lockTitle, lockHint, timeoutRow, zeroHint);
        lockSection.getStyleClass().add("settings-section");

        // --- Sección 2: PIN de sesión ---
        Label pinTitle = label(t("settings.session.pin.title"), "settings-section-title");
        Label pinHint = new Label(t("settings.session.pin.hint"));
        pinHint.setWrapText(true);
        pinHint.getStyleClass().add("settings-hint");
        Label pinStatus = new Label(t("settings.session.pin.status.unknown"));
        pinStatus.getStyleClass().add("settings-hint");
        Button definePinBtn = new Button(t("settings.session.pin.btn.define"));
        definePinBtn.setGraphic(icon("fas-lock"));
        Button changePinBtn = new Button(t("settings.session.pin.btn.change"));
        changePinBtn.setGraphic(icon("fas-key"));
        Button removePinBtn = new Button(t("settings.session.pin.btn.remove"));
        removePinBtn.setGraphic(icon("fas-unlock"));
        HBox pinActions = new HBox(8, definePinBtn, changePinBtn, removePinBtn);
        pinActions.setAlignment(Pos.CENTER_LEFT);
        VBox pinSection = new VBox(8, pinTitle, pinHint, pinStatus, pinActions);
        pinSection.getStyleClass().add("settings-section");

        // --- Sección 3: Salvapantallas ---
        Label saverTitle = label(t("settings.session.saver.title"), "settings-section-title");
        Label saverHint = new Label(t("settings.session.saver.hint"));
        saverHint.setWrapText(true);
        saverHint.getStyleClass().add("settings-hint");
        ComboBox<String> saverCombo = new ComboBox<>(FXCollections.observableArrayList(
                "clock", "logo", "dark", "carousel"));
        saverCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String s) {
                if (s == null) return "";
                return switch (s) {
                    case "clock" -> t("settings.session.saver.clock");
                    case "logo" -> t("settings.session.saver.logo");
                    case "dark" -> t("settings.session.saver.dark");
                    case "carousel" -> t("settings.session.saver.carousel");
                    default -> s;
                };
            }
            @Override public String fromString(String s) { return s; }
        });
        saverCombo.setValue("clock");
        VBox saverSection = new VBox(8, saverTitle, saverHint, saverCombo);
        saverSection.getStyleClass().add("settings-section");

        // --- Footer guardar ---
        Button saveBtn = new Button(t("settings.session.save"));
        saveBtn.setGraphic(icon("fas-save"));
        saveBtn.getStyleClass().add("button-primary");
        HBox footer = new HBox(saveBtn);
        footer.setAlignment(Pos.CENTER_RIGHT);

        body.getChildren().addAll(lockSection, pinSection, saverSection, footer);

        // --- Carga + handlers ---
        Runnable reload = () -> {
            Task<com.benjagest.ui.model.SessionStatusEntry> task = new Task<>() {
                @Override protected com.benjagest.ui.model.SessionStatusEntry call() throws Exception {
                    return altaApiClient.getSessionStatus();
                }
            };
            task.setOnSucceeded(ev -> {
                var s = task.getValue();
                timeoutSpin.getValueFactory().setValue(s.pinTimeoutMin());
                saverCombo.setValue(
                        s.screensaverStyle() == null || s.screensaverStyle().isBlank()
                                ? "clock" : s.screensaverStyle());
                if (s.pinConfigured()) {
                    pinStatus.setText(t("settings.session.pin.status.configured"));
                    definePinBtn.setDisable(true);
                    changePinBtn.setDisable(false);
                    removePinBtn.setDisable(false);
                } else {
                    pinStatus.setText(t("settings.session.pin.status.missing"));
                    definePinBtn.setDisable(false);
                    changePinBtn.setDisable(true);
                    removePinBtn.setDisable(true);
                }
                // Aplicar el timeout al checker LOCK en caliente.
                refreshLockTimeout(s.pinTimeoutMin());
                this.screensaverStyle = s.screensaverStyle();
            });
            task.setOnFailed(ev -> showError(t("settings.session.fail.title"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "session-load");
        };

        saveBtn.setOnAction(ev -> {
            Task<com.benjagest.ui.model.SessionStatusEntry> save = new Task<>() {
                @Override protected com.benjagest.ui.model.SessionStatusEntry call() throws Exception {
                    return altaApiClient.saveSessionSettings(
                            timeoutSpin.getValue(), saverCombo.getValue());
                }
            };
            save.setOnSucceeded(s -> {
                refreshLockTimeout(save.getValue().pinTimeoutMin());
                this.screensaverStyle = save.getValue().screensaverStyle();
                Alert ok = new Alert(Alert.AlertType.INFORMATION);
                ok.setTitle(t("settings.session.save.ok.title"));
                ok.setHeaderText(t("settings.session.save.ok.body"));
                ok.showAndWait();
            });
            save.setOnFailed(s -> showError(t("settings.session.fail.title"),
                    save.getException() == null ? "" : save.getException().getMessage()));
            start(save, "session-save");
        });

        definePinBtn.setOnAction(ev -> openSessionPinDialog(false, reload));
        changePinBtn.setOnAction(ev -> openSessionPinDialog(true, reload));
        removePinBtn.setOnAction(ev -> openSessionPinRemoveDialog(reload));

        reload.run();

        ScrollPane scroll = new ScrollPane(body);
        scroll.setFitToWidth(true);
        scroll.getStyleClass().add("content-scroll");
        return scroll;
    }

    private void openSessionPinDialog(boolean requireCurrent, Runnable onSaved) {
        Dialog<Void> dialog = new Dialog<>();
        dialog.setTitle(t(requireCurrent
                ? "settings.session.pin.dialog.change.title"
                : "settings.session.pin.dialog.define.title"));
        dialog.setHeaderText(t(requireCurrent
                ? "settings.session.pin.dialog.change.header"
                : "settings.session.pin.dialog.define.header"));

        PasswordField currentField = new PasswordField();
        currentField.setPromptText(t("settings.session.pin.dialog.current"));
        PasswordField newField = new PasswordField();
        newField.setPromptText(t("settings.session.pin.dialog.new"));
        PasswordField confirmField = new PasswordField();
        confirmField.setPromptText(t("settings.session.pin.dialog.confirm"));

        VBox form = new VBox(10);
        if (requireCurrent) {
            form.getChildren().addAll(
                    new Label(t("settings.session.pin.dialog.current")), currentField);
        }
        form.getChildren().addAll(
                new Label(t("settings.session.pin.dialog.new")), newField,
                new Label(t("settings.session.pin.dialog.confirm")), confirmField,
                new Label(t("settings.session.pin.dialog.rules")));
        form.setPadding(new Insets(16));
        form.setPrefWidth(380);

        dialog.getDialogPane().setContent(form);
        dialog.getDialogPane().getButtonTypes().addAll(
                javafx.scene.control.ButtonType.CANCEL, javafx.scene.control.ButtonType.OK);
        ((javafx.scene.control.Button) dialog.getDialogPane()
                .lookupButton(javafx.scene.control.ButtonType.OK))
                .setText(t("settings.session.pin.dialog.save"));

        dialog.setResultConverter(bt -> {
            if (bt == javafx.scene.control.ButtonType.OK) {
                String newPin = newField.getText();
                String confirm = confirmField.getText();
                if (newPin == null || newPin.isBlank() || !newPin.equals(confirm)) {
                    showError(t("settings.session.pin.dialog.error.title"),
                            t("settings.session.pin.dialog.error.mismatch"));
                    return null;
                }
                String current = requireCurrent ? currentField.getText() : "";
                Task<Void> t = new Task<>() {
                    @Override protected Void call() throws Exception {
                        altaApiClient.setSessionPin(current, newPin);
                        return null;
                    }
                };
                t.setOnSucceeded(s -> onSaved.run());
                t.setOnFailed(s -> showError(t("settings.session.fail.title"),
                        t.getException() == null ? "" : t.getException().getMessage()));
                start(t, "session-pin-set");
            }
            return null;
        });
        dialog.showAndWait();
    }

    private void openSessionPinRemoveDialog(Runnable onDone) {
        Dialog<Void> dialog = new Dialog<>();
        dialog.setTitle(t("settings.session.pin.dialog.remove.title"));
        dialog.setHeaderText(t("settings.session.pin.dialog.remove.header"));

        PasswordField currentField = new PasswordField();
        currentField.setPromptText(t("settings.session.pin.dialog.current"));
        VBox form = new VBox(10,
                new Label(t("settings.session.pin.dialog.current")), currentField,
                new Label(t("settings.session.pin.dialog.remove.warning")));
        form.setPadding(new Insets(16));
        form.setPrefWidth(380);

        dialog.getDialogPane().setContent(form);
        dialog.getDialogPane().getButtonTypes().addAll(
                javafx.scene.control.ButtonType.CANCEL, javafx.scene.control.ButtonType.OK);
        ((javafx.scene.control.Button) dialog.getDialogPane()
                .lookupButton(javafx.scene.control.ButtonType.OK))
                .setText(t("settings.session.pin.dialog.remove.confirm"));

        dialog.setResultConverter(bt -> {
            if (bt == javafx.scene.control.ButtonType.OK) {
                String current = currentField.getText();
                if (current == null || current.isBlank()) {
                    showError(t("settings.session.pin.dialog.error.title"),
                            t("settings.session.pin.dialog.error.current_required"));
                    return null;
                }
                Task<Void> t = new Task<>() {
                    @Override protected Void call() throws Exception {
                        altaApiClient.deleteSessionPin(current);
                        return null;
                    }
                };
                t.setOnSucceeded(s -> onDone.run());
                t.setOnFailed(s -> showError(t("settings.session.fail.title"),
                        t.getException() == null ? "" : t.getException().getMessage()));
                start(t, "session-pin-delete");
            }
            return null;
        });
        dialog.showAndWait();
    }

    /** Estilo de salvapantallas activo (clock/logo/dark/carousel). */
    private String screensaverStyle = "clock";

    /** PORT-4 LOGO — Sección del logo de empresa en Configuración → Empresa. */
    private Node buildCompanyLogoSection() {
        VBox box = new VBox(10);
        Label title = label(t("settings.company.section.logo"), "settings-section-title");
        Label hint = new Label(t("settings.company.section.logo.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        javafx.scene.image.ImageView preview = new javafx.scene.image.ImageView();
        preview.setFitWidth(200);
        preview.setFitHeight(120);
        preview.setPreserveRatio(true);
        preview.setSmooth(true);
        StackPane previewBox = new StackPane(preview);
        previewBox.setMinHeight(120);
        previewBox.setMaxWidth(220);
        previewBox.setStyle("-fx-background-color: #f1f5f9; -fx-background-radius: 8;"
                + " -fx-border-color: #cbd5e1; -fx-border-radius: 8;");

        Button uploadBtn = new Button(t("settings.company.logo.upload"));
        uploadBtn.setGraphic(icon("fas-upload"));
        uploadBtn.getStyleClass().add("button-primary");
        Button deleteBtn = new Button(t("settings.company.logo.delete"));
        deleteBtn.setGraphic(icon("fas-trash"));
        deleteBtn.setDisable(true);

        Runnable reload = () -> {
            Task<byte[]> task = new Task<>() {
                @Override protected byte[] call() throws Exception {
                    return altaApiClient.getCompanyLogoBytes();
                }
            };
            task.setOnSucceeded(ev -> {
                byte[] bytes = task.getValue();
                if (bytes == null || bytes.length == 0) {
                    preview.setImage(null);
                    deleteBtn.setDisable(true);
                } else {
                    preview.setImage(new javafx.scene.image.Image(
                            new java.io.ByteArrayInputStream(bytes)));
                    deleteBtn.setDisable(false);
                }
            });
            task.setOnFailed(ev -> { /* sin logo o sin permisos — ignorar */ });
            start(task, "logo-load");
        };

        uploadBtn.setOnAction(ev -> {
            javafx.stage.FileChooser fc = new javafx.stage.FileChooser();
            fc.setTitle(t("settings.company.logo.upload"));
            fc.getExtensionFilters().add(new javafx.stage.FileChooser.ExtensionFilter(
                    "PNG / JPG", "*.png", "*.jpg", "*.jpeg"));
            java.io.File f = fc.showOpenDialog(box.getScene().getWindow());
            if (f == null) return;
            Task<Boolean> up = new Task<>() {
                @Override protected Boolean call() throws Exception {
                    return altaApiClient.uploadCompanyLogo(f);
                }
            };
            up.setOnSucceeded(s -> reload.run());
            up.setOnFailed(s -> showError(t("settings.company.logo.fail.title"),
                    up.getException() == null ? "" : up.getException().getMessage()));
            start(up, "logo-upload");
        });

        deleteBtn.setOnAction(ev -> {
            Alert confirm = new Alert(Alert.AlertType.CONFIRMATION);
            confirm.setTitle(t("settings.company.logo.delete"));
            confirm.setHeaderText(t("settings.company.logo.delete.confirm"));
            confirm.showAndWait().ifPresent(rsp -> {
                if (rsp == javafx.scene.control.ButtonType.OK) {
                    Task<Void> d = new Task<>() {
                        @Override protected Void call() throws Exception {
                            altaApiClient.deleteCompanyLogo();
                            return null;
                        }
                    };
                    d.setOnSucceeded(s -> reload.run());
                    d.setOnFailed(s -> showError(t("settings.company.logo.fail.title"),
                            d.getException() == null ? "" : d.getException().getMessage()));
                    start(d, "logo-delete");
                }
            });
        });

        HBox actions = new HBox(8, uploadBtn, deleteBtn);
        actions.setAlignment(Pos.CENTER_LEFT);

        reload.run();
        box.getChildren().addAll(title, hint, previewBox, actions);
        return box;
    }

    private void saveCompany(CompanyData data) {
        if (data.legalName() == null || data.legalName().isBlank()) {
            showError(t("settings.company.error.missing_legal_name.title"), t("settings.company.error.missing_legal_name.body"));
            return;
        }
        Task<CompanyData> task = new Task<>() {
            @Override
            protected CompanyData call() throws Exception {
                return settingsApiClient.updateCompany(data);
            }
        };
        task.setOnSucceeded(event -> {
            // Refresh silencioso: actualizamos AuthSession con la nueva
            // razon social y repintamos el shell (header + sidebar).
            // No reconstruimos la pantalla de Configuracion, asi te
            // quedas en el tab Empresa con los datos guardados visibles.
            CompanyData saved = task.getValue();
            AuthSession.get().updateActiveCompanyLegalName(saved.legalName());
            session = session.withCompanyName(saved.legalName());
            showShell();
            select("settings");
        });
        task.setOnFailed(event -> showError(t("settings.company.save.fail.title"), t("settings.company.save.fail.body")));
        start(task, "settings-company-save");
    }

    // ----- Pestana Email SMTP -----

    private Node settingsEmailTab(EmailConfig config) {
        TextField smtpHost = textInput(config.smtpHost(), t("settings.email.prompt.host"));
        TextField smtpPort = textInput(config.smtpPort() == null ? "" : config.smtpPort().toString(), t("settings.email.prompt.port"));
        TextField smtpUser = textInput(config.smtpUser(), t("settings.email.prompt.user"));
        PasswordField smtpPassword = new PasswordField();
        smtpPassword.setPromptText(config.passwordConfigured()
                ? t("settings.email.prompt.password.saved")
                : t("settings.email.prompt.password"));
        TextField fromAddress = textInput(config.fromAddress(), t("settings.email.prompt.from_address"));
        TextField fromName = textInput(config.fromName(), t("settings.email.prompt.from_name"));
        TextField replyTo = textInput(config.replyTo(), t("settings.email.prompt.reply_to"));
        CheckBox tlsEnabled = new CheckBox(t("settings.email.flag.tls"));
        tlsEnabled.setSelected(config.tlsEnabled());
        CheckBox authRequired = new CheckBox(t("settings.email.flag.auth"));
        authRequired.setSelected(config.authRequired());

        // Slice 4A — Selector de proveedor que autorrellena los campos
        // técnicos (host/puerto/TLS/auth) según el servicio elegido. El
        // asesor/empresario solo necesita pegar su email y la contraseña
        // (o app password). Detecta el proveedor por defecto a partir
        // del host actual si ya está configurado.
        ComboBox<String> providerCombo = new ComboBox<>();
        providerCombo.getItems().addAll(
                t("settings.email.provider.custom"),
                "Gmail / Google Workspace",
                "Outlook / Office 365 / Hotmail",
                "Yahoo Mail",
                "iCloud",
                "Zoho Mail",
                "Dondominio",
                "Webempresa",
                "OVH",
                "IONOS / 1&1",
                "Strato",
                "Arsys");
        providerCombo.setValue(detectProviderFromHost(smtpHost.getText()));
        providerCombo.setMaxWidth(360);

        // Hint dinámico con info específica del proveedor y link.
        javafx.scene.control.Hyperlink helpLink = new javafx.scene.control.Hyperlink();
        helpLink.setVisible(false);
        helpLink.setManaged(false);
        Label helpHint = new Label();
        helpHint.getStyleClass().add("settings-hint");
        helpHint.setWrapText(true);

        Runnable refreshHelp = () -> {
            String prov = providerCombo.getValue();
            ProviderPreset preset = providerPreset(prov);
            if (preset == null) {
                helpHint.setText(t("settings.email.help.custom"));
                helpLink.setVisible(false);
                helpLink.setManaged(false);
            } else {
                helpHint.setText(preset.hint);
                if (preset.helpUrl != null) {
                    helpLink.setText(preset.helpText);
                    helpLink.setVisible(true);
                    helpLink.setManaged(true);
                    helpLink.setOnAction(e -> openExternalUrl(preset.helpUrl));
                } else {
                    helpLink.setVisible(false);
                    helpLink.setManaged(false);
                }
            }
        };
        providerCombo.valueProperty().addListener((obs, oldV, newV) -> {
            ProviderPreset preset = providerPreset(newV);
            if (preset != null) {
                smtpHost.setText(preset.host);
                smtpPort.setText(String.valueOf(preset.port));
                tlsEnabled.setSelected(preset.tls);
                authRequired.setSelected(preset.auth);
            }
            refreshHelp.run();
        });
        refreshHelp.run();

        // Si los campos están vacíos, intenta pre-rellenar smtpUser y
        // fromAddress con el email de la empresa (pestaña Empresa →
        // contact_email) — minimiza tecleo en el alta inicial.
        if (smtpUser.getText() == null || smtpUser.getText().isBlank()) {
            String companyEmail = tryReadCompanyContactEmail();
            if (companyEmail != null) {
                smtpUser.setText(companyEmail);
                if (fromAddress.getText() == null || fromAddress.getText().isBlank()) {
                    fromAddress.setText(companyEmail);
                }
            }
        }

        GridPane grid = formGrid();
        addFormRow(grid, 0, t("settings.email.field.provider"), providerCombo);
        addFormRow(grid, 1, t("settings.email.field.host"), smtpHost);
        addFormRow(grid, 2, t("settings.email.field.port"), smtpPort);
        addFormRow(grid, 3, t("settings.email.field.user"), smtpUser);
        addFormRow(grid, 4, t("settings.email.field.password"), smtpPassword);
        addFormRow(grid, 5, t("settings.email.field.from_address"), fromAddress);
        addFormRow(grid, 6, t("settings.email.field.from_name"), fromName);
        addFormRow(grid, 7, t("settings.email.field.reply_to"), replyTo);

        VBox flags = new VBox(8, tlsEnabled, authRequired);

        // Bloque de ayuda contextual, debajo del formulario.
        VBox helpBox = new VBox(4, helpHint, helpLink);
        helpBox.setPadding(new Insets(4, 0, 0, 0));

        TextField testRecipient = new TextField();
        testRecipient.setPromptText(t("settings.email.test.prompt"));

        Button save = new Button(t("settings.email.btn.save"));
        save.setGraphic(icon("fas-save"));
        save.setOnAction(event -> saveEmailConfig(
                smtpHost.getText(),
                parseIntOrNull(smtpPort.getText()),
                smtpUser.getText(),
                smtpPassword.getText(),
                fromAddress.getText(),
                fromName.getText(),
                replyTo.getText(),
                tlsEnabled.isSelected(),
                authRequired.isSelected()
        ));

        Button test = new Button(t("settings.email.btn.test"));
        test.setGraphic(icon("fas-paper-plane"));
        test.setOnAction(event -> sendTestEmail(testRecipient.getText()));

        testRecipient.getStyleClass().add("form-input");

        HBox actions = new HBox(test, save);
        actions.getStyleClass().add("settings-actions");

        // Panel de conexión con Google (Gmail + Calendar): visible solo cuando
        // el proveedor elegido es Google. Sustituye al antiguo tab Integraciones.
        // Con Google conectado el correo sale por Gmail (OAuth) sin contraseña
        // de aplicación; si el proveedor no es Google, se usa SMTP.
        VBox googleBox = googleIntegrationPanel();
        Label googleNote = label(t("settings.email.google.note"), "settings-hint");
        googleNote.setWrapText(true); googleNote.setMaxWidth(620);
        VBox googleSection = new VBox(8, new Separator(), googleNote, googleBox);
        Runnable toggleGoogle = () -> {
            String p = providerCombo.getValue();
            boolean isGoogle = p != null && p.startsWith("Gmail");
            googleSection.setVisible(isGoogle);
            googleSection.setManaged(isGoogle);
        };
        providerCombo.valueProperty().addListener((o, ov, nv) -> toggleGoogle.run());
        toggleGoogle.run();

        VBox center = new VBox(16,
                grid,
                flags,
                helpBox,
                googleSection,
                new Separator(),
                label(t("settings.email.section.test"), "settings-section-title"),
                label(t("settings.email.section.test.hint"), "settings-hint"),
                testRecipient
        );
        return tabLayout(label(t("settings.email.section"), "settings-section-title"), center, actions);
    }

    /**
     * Slice 4A — Presets SMTP por proveedor. El usuario solo elige el
     * combo y los campos host/port/tls/auth se autorrellenan.
     */
    private record ProviderPreset(
            String host, int port, boolean tls, boolean auth,
            String hint, String helpText, String helpUrl) {}

    private ProviderPreset providerPreset(String provider) {
        if (provider == null) return null;
        if (provider.startsWith("Gmail")) return new ProviderPreset(
                "smtp.gmail.com", 587, true, true,
                t("settings.email.help.gmail"),
                t("settings.email.help.gmail.link"),
                "https://myaccount.google.com/apppasswords");
        if (provider.startsWith("Outlook")) return new ProviderPreset(
                "smtp.office365.com", 587, true, true,
                t("settings.email.help.outlook"),
                t("settings.email.help.outlook.link"),
                "https://account.live.com/proofs/AppPassword");
        if (provider.startsWith("Yahoo")) return new ProviderPreset(
                "smtp.mail.yahoo.com", 587, true, true,
                t("settings.email.help.yahoo"),
                t("settings.email.help.yahoo.link"),
                "https://login.yahoo.com/account/security/app-passwords");
        if (provider.startsWith("iCloud")) return new ProviderPreset(
                "smtp.mail.me.com", 587, true, true,
                t("settings.email.help.icloud"),
                t("settings.email.help.icloud.link"),
                "https://appleid.apple.com/account/manage");
        if (provider.startsWith("Zoho")) return new ProviderPreset(
                "smtp.zoho.eu", 587, true, true,
                t("settings.email.help.zoho"),
                t("settings.email.help.zoho.link"),
                "https://accounts.zoho.eu/u/h#sessions/apppasswords");
        if (provider.startsWith("Dondominio")) return new ProviderPreset(
                "mail.tudominio.com", 587, true, true,
                t("settings.email.help.dondominio"), null, null);
        if (provider.startsWith("Webempresa")) return new ProviderPreset(
                "mail.tudominio.com", 587, true, true,
                t("settings.email.help.generic_hosting"), null, null);
        if (provider.startsWith("OVH")) return new ProviderPreset(
                "ssl0.ovh.net", 587, true, true,
                t("settings.email.help.ovh"), null, null);
        if (provider.startsWith("IONOS")) return new ProviderPreset(
                "smtp.ionos.es", 587, true, true,
                t("settings.email.help.ionos"), null, null);
        if (provider.startsWith("Strato")) return new ProviderPreset(
                "smtp.strato.com", 587, true, true,
                t("settings.email.help.generic_hosting"), null, null);
        if (provider.startsWith("Arsys")) return new ProviderPreset(
                "smtp.arsys.es", 587, true, true,
                t("settings.email.help.generic_hosting"), null, null);
        return null; // "Personalizado" o desconocido
    }

    /**
     * Detecta el proveedor a partir del host SMTP guardado. Permite
     * que al entrar a la pantalla, el combo refleje lo que ya hay
     * configurado en lugar de quedarse en blanco.
     */
    private String detectProviderFromHost(String host) {
        if (host == null || host.isBlank()) return t("settings.email.provider.custom");
        String h = host.toLowerCase();
        if (h.contains("gmail")) return "Gmail / Google Workspace";
        if (h.contains("office365") || h.contains("outlook") || h.contains("hotmail"))
            return "Outlook / Office 365 / Hotmail";
        if (h.contains("yahoo")) return "Yahoo Mail";
        if (h.contains("me.com") || h.contains("icloud")) return "iCloud";
        if (h.contains("zoho")) return "Zoho Mail";
        if (h.contains("dondominio")) return "Dondominio";
        if (h.contains("webempresa")) return "Webempresa";
        if (h.contains("ovh")) return "OVH";
        if (h.contains("ionos") || h.contains("1and1")) return "IONOS / 1&1";
        if (h.contains("strato")) return "Strato";
        if (h.contains("arsys")) return "Arsys";
        return t("settings.email.provider.custom");
    }

    /**
     * Lee perezosamente el email de la empresa actual de la pestaña
     * "Empresa" para pre-rellenar smtpUser/fromAddress. Si el endpoint
     * falla por cualquier motivo, devolvemos null sin ruido.
     */
    private String tryReadCompanyContactEmail() {
        try {
            var company = settingsApiClient.getCompany();
            if (company != null && company.email() != null
                    && !company.email().isBlank()) {
                return company.email();
            }
        } catch (Exception ignored) {}
        return null;
    }

    /**
     * Abre una URL en el navegador del sistema. Si Desktop no está
     * soportado (entornos headless, Linux sin DE), muestra la URL
     * en un diálogo para que el usuario la copie.
     */
    private void openExternalUrl(String url) {
        try {
            if (java.awt.Desktop.isDesktopSupported()
                    && java.awt.Desktop.getDesktop().isSupported(
                            java.awt.Desktop.Action.BROWSE)) {
                java.awt.Desktop.getDesktop().browse(new java.net.URI(url));
                return;
            }
        } catch (Exception ignored) {}
        Alert a = new Alert(Alert.AlertType.INFORMATION, url, ButtonType.OK);
        a.setHeaderText(t("settings.email.help.copy_url"));
        a.showAndWait();
    }

    private Integer parseIntOrNull(String text) {
        if (text == null || text.isBlank()) {
            return null;
        }
        try {
            return Integer.parseInt(text.trim());
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    private void saveEmailConfig(String host, Integer port, String user, String password,
                                 String fromAddress, String fromName, String replyTo,
                                 boolean tls, boolean auth) {
        Task<EmailConfig> task = new Task<>() {
            @Override
            protected EmailConfig call() throws Exception {
                return settingsApiClient.updateEmailConfig(host, port, user, password,
                        fromAddress, fromName, replyTo, tls, auth);
            }
        };
        task.setOnSucceeded(event -> {
            Alert ok = new Alert(Alert.AlertType.INFORMATION,
                    t("settings.email.save.success"), ButtonType.OK);
            ok.setHeaderText(null);
            ok.showAndWait();
            showSettings();
        });
        task.setOnFailed(event -> showError(t("settings.email.save.fail.title"), t("settings.email.save.fail.body")));
        start(task, "settings-email-save");
    }

    private void sendTestEmail(String recipient) {
        if (recipient == null || recipient.isBlank()) {
            showError(t("settings.email.test.missing.title"), t("settings.email.test.missing.body"));
            return;
        }
        Task<Void> task = new Task<>() {
            @Override
            protected Void call() throws Exception {
                settingsApiClient.sendTestEmail(recipient.trim());
                return null;
            }
        };
        task.setOnSucceeded(event -> {
            Alert ok = new Alert(Alert.AlertType.INFORMATION,
                    t("settings.email.test.success_prefix") + recipient + t("settings.email.test.success_suffix"),
                    ButtonType.OK);
            ok.setHeaderText(null);
            ok.showAndWait();
        });
        task.setOnFailed(event -> {
            String detail = task.getException() == null ? null
                    : humanizeBackendError(task.getException().getMessage());
            showError(t("settings.email.test.fail.title"),
                    detail == null || detail.isBlank() ? t("settings.email.test.fail.body")
                            : t("settings.email.test.fail.body") + "\n\n" + detail);
        });
        start(task, "settings-email-test");
    }

    // ----- Pestana Modulos -----

    private Node settingsModulesTab(List<CompanyModuleEntry> modules) {
        pendingModuleChanges.clear();
        moduleBaselineState.clear();

        Label sectionTitle = label(t("settings.modules.section"), "settings-section-title");
        Label hint = new Label(t("settings.modules.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        VBox list = new VBox(8);
        list.getStyleClass().add("module-list");
        // Solo categorias raiz. Los sub-modulos no son configurables a
        // mano: se mueven en bloque con su categoria padre.
        for (CompanyModuleEntry category : modules.stream().filter(m -> m.parentSlug() == null || m.parentSlug().isBlank()).toList()) {
            CheckBox toggle = new CheckBox(category.label());
            toggle.setSelected(category.active());
            toggle.setDisable("settings".equals(category.slug()));
            moduleBaselineState.put(category.slug(), category.active());
            String slug = category.slug();
            toggle.selectedProperty().addListener((obs, was, now) -> {
                Boolean baseline = moduleBaselineState.get(slug);
                boolean baselineValue = baseline != null && baseline;
                if (now == null || now.booleanValue() == baselineValue) {
                    pendingModuleChanges.remove(slug);
                } else {
                    pendingModuleChanges.put(slug, now);
                }
                refreshSaveModulesButton();
            });
            HBox row = new HBox(toggle);
            row.setAlignment(Pos.CENTER_LEFT);
            row.getStyleClass().add("module-row");
            list.getChildren().add(row);
        }

        modulesDirtyHint = label("", "settings-hint");
        saveModulesButton = new Button(t("settings.company.save"));
        saveModulesButton.setGraphic(icon("fas-save"));
        saveModulesButton.setOnAction(event -> saveModuleChanges());

        HBox actions = new HBox(modulesDirtyHint, new Region(), saveModulesButton);
        HBox.setHgrow(actions.getChildren().get(1), Priority.ALWAYS);
        actions.getStyleClass().add("settings-actions");
        actions.setAlignment(Pos.CENTER_RIGHT);

        VBox header = new VBox(8, sectionTitle, hint);
        Node body = tabLayout(header, list, actions);
        refreshSaveModulesButton();
        return body;
    }

    // ----- Pestana Auditoria -----

    private static final List<String> AUDIT_EVENT_TYPES = List.of(
            "(todos)",
            "LOGIN_OK",
            "LOGIN_FAIL",
            "COMPANY_SWITCHED",
            "MODULE_ENABLED",
            "MODULE_DISABLED",
            "COMPANY_DATA_UPDATED"
    );

    // ===================================================================
    //  CERT-IMPORT (2026-06-05) — pestaña Certificado en Configuración
    // ===================================================================

    private TableView<com.benjagest.ui.model.CertificateSummaryEntry> certsTable;

    private Node settingsCertificateTab() {
        Label sectionTitle = label(t("settings.cert.section"), "settings-section-title");
        Label hint = new Label(t("settings.cert.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        certsTable = new TableView<>();
        certsTable.getStyleClass().add("data-table");
        certsTable.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        certsTable.setPlaceholder(new Label(t("settings.cert.placeholder.empty")));

        TableColumn<com.benjagest.ui.model.CertificateSummaryEntry, String> colAlias =
                new TableColumn<>(t("settings.cert.col.alias"));
        colAlias.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().alias()));
        colAlias.setPrefWidth(180);

        TableColumn<com.benjagest.ui.model.CertificateSummaryEntry, String> colType =
                new TableColumn<>(t("settings.cert.col.type"));
        colType.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().certificateType()));
        colType.setPrefWidth(160);

        TableColumn<com.benjagest.ui.model.CertificateSummaryEntry, String> colNif =
                new TableColumn<>(t("settings.cert.col.nif"));
        colNif.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().subjectTaxIdentifier() == null ? "—" : c.getValue().subjectTaxIdentifier()));
        colNif.setPrefWidth(110);

        TableColumn<com.benjagest.ui.model.CertificateSummaryEntry, String> colSubject =
                new TableColumn<>(t("settings.cert.col.subject"));
        colSubject.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().subjectName() == null ? "—" : c.getValue().subjectName()));

        TableColumn<com.benjagest.ui.model.CertificateSummaryEntry, String> colValidUntil =
                new TableColumn<>(t("settings.cert.col.valid_until"));
        colValidUntil.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().validTo() == null ? "—"
                        : c.getValue().validTo().atZone(java.time.ZoneId.systemDefault())
                              .toLocalDate().toString()));
        colValidUntil.setComparator(ISO_DATE_COMPARATOR);
        colValidUntil.setPrefWidth(120);

        TableColumn<com.benjagest.ui.model.CertificateSummaryEntry, String> colUploadedBy =
                new TableColumn<>(t("settings.cert.col.uploaded_by"));
        colUploadedBy.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().uploadedByAdvisory()
                        ? t("settings.cert.uploaded_by.advisory")
                        : t("settings.cert.uploaded_by.self")));
        colUploadedBy.setPrefWidth(180);

        TableColumn<com.benjagest.ui.model.CertificateSummaryEntry, Void> colActions =
                new TableColumn<>(t("settings.cert.col.actions"));
        colActions.setPrefWidth(110);
        colActions.setCellFactory(col -> new javafx.scene.control.TableCell<>() {
            private final Button del = new Button(t("settings.cert.action.delete"));
            {
                del.getStyleClass().add("button-danger-outline");
                del.setOnAction(ev -> {
                    com.benjagest.ui.model.CertificateSummaryEntry row = getTableRow().getItem();
                    if (row != null) deleteCertificate(row);
                });
            }
            @Override
            protected void updateItem(Void item, boolean empty) {
                super.updateItem(item, empty);
                setGraphic(empty ? null : del);
            }
        });

        certsTable.getColumns().setAll(colAlias, colType, colNif, colSubject,
                colValidUntil, colUploadedBy, colActions);

        Button uploadBtn = new Button(t("settings.cert.action.upload"));
        uploadBtn.getStyleClass().add("button-primary");
        uploadBtn.setOnAction(ev -> showCertificateUploadDialog());

        Button refreshBtn = new Button(t("settings.cert.action.refresh"));
        refreshBtn.setOnAction(ev -> reloadCertificates());

        HBox actions = new HBox(10, uploadBtn, refreshBtn);

        // tabLayout: header + body scroll + footer fijo. La tabla con el
        // listado puede crecer mucho en clientes con varios .p12; sin
        // este patron los botones del pie quedan fuera de pantalla en
        // portatil. Mismo enfoque que las otras pestanas de Configuracion.
        VBox header = new VBox(8, sectionTitle, hint);
        VBox body = new VBox(12, certsTable);
        VBox.setVgrow(certsTable, Priority.ALWAYS);

        reloadCertificates();
        return tabLayoutFill(header, body, actions);
    }

    private void reloadCertificates() {
        if (certsTable == null) return;
        Task<java.util.List<com.benjagest.ui.model.CertificateSummaryEntry>> task = new Task<>() {
            @Override
            protected java.util.List<com.benjagest.ui.model.CertificateSummaryEntry> call() throws Exception {
                return certificateApi.list();
            }
        };
        task.setOnSucceeded(e -> certsTable.getItems().setAll(task.getValue()));
        task.setOnFailed(e -> showError(t("settings.cert.fail.list.title"),
                t("settings.cert.fail.list.body")));
        start(task, "certificates-list");
    }

    private void deleteCertificate(com.benjagest.ui.model.CertificateSummaryEntry row) {
        Alert confirm = new Alert(Alert.AlertType.CONFIRMATION,
                t("settings.cert.confirm.delete.body") + "\n\n" + row.alias(),
                ButtonType.OK, ButtonType.CANCEL);
        confirm.setHeaderText(t("settings.cert.confirm.delete.title"));
        confirm.showAndWait().filter(b -> b == ButtonType.OK).ifPresent(b -> {
            Task<Void> task = new Task<>() {
                @Override
                protected Void call() throws Exception {
                    certificateApi.delete(row.id());
                    return null;
                }
            };
            task.setOnSucceeded(e -> reloadCertificates());
            task.setOnFailed(e -> showError(t("settings.cert.fail.delete.title"),
                    t("settings.cert.fail.delete.body")));
            start(task, "certificate-delete");
        });
    }

    private void showCertificateUploadDialog() {
        Dialog<ButtonType> dialog = new Dialog<>();
        dialog.setTitle(t("settings.cert.upload.title"));
        ButtonType saveBt = new ButtonType(t("settings.cert.upload.save"),
                ButtonBar.ButtonData.OK_DONE);
        dialog.getDialogPane().getButtonTypes().addAll(saveBt, ButtonType.CANCEL);

        Label fileLabel = new Label(t("settings.cert.upload.no_file"));
        fileLabel.getStyleClass().add("settings-hint");
        Button chooseBtn = new Button(t("settings.cert.upload.choose"));
        // Buffer del .p12 cargado (en base64 cuando se selecciona)
        final String[] base64Holder = new String[1];

        PasswordField passwordField = new PasswordField();
        passwordField.setPrefColumnCount(28);

        TextField aliasField = new TextField();
        aliasField.setPrefColumnCount(28);
        ComboBox<String> typeCombo = new ComboBox<>();
        typeCombo.getItems().addAll(
                "FNMT_PERSONA_FISICA", "FNMT_REPRESENTANTE",
                "CAMERFIRMA", "IZENPE", "ANCERT", "SELLO_EMPRESA", "OTRO");
        typeCombo.getSelectionModel().select("OTRO");
        TextField subjectField = new TextField();
        subjectField.setPrefColumnCount(28);
        TextField nifField = new TextField();
        nifField.setPrefColumnCount(16);
        TextField validFromField = new TextField();
        validFromField.setPromptText("AAAA-MM-DD");
        com.benjagest.ui.support.EditableCells.installIsoDateMask(validFromField);
        TextField validToField = new TextField();
        validToField.setPromptText("AAAA-MM-DD");
        com.benjagest.ui.support.EditableCells.installIsoDateMask(validToField);

        Button inspectBtn = new Button(t("settings.cert.upload.inspect"));
        inspectBtn.setDisable(true); // habilita cuando hay archivo

        chooseBtn.setOnAction(ev -> {
            javafx.stage.FileChooser chooser = new javafx.stage.FileChooser();
            chooser.setTitle(t("settings.cert.upload.choose"));
            chooser.getExtensionFilters().add(
                    new javafx.stage.FileChooser.ExtensionFilter("PKCS#12 (.p12, .pfx)", "*.p12", "*.pfx"));
            java.io.File file = chooser.showOpenDialog(root.getScene().getWindow());
            if (file == null) return;
            try {
                byte[] bytes = java.nio.file.Files.readAllBytes(file.toPath());
                base64Holder[0] = java.util.Base64.getEncoder().encodeToString(bytes);
                fileLabel.setText(file.getName() + " (" + (bytes.length / 1024) + " KB)");
                inspectBtn.setDisable(false);
                if (aliasField.getText().isBlank()) {
                    String name = file.getName().replaceAll("(?i)\\.(p12|pfx)$", "");
                    aliasField.setText(name);
                }
            } catch (Exception ex) {
                showError(t("settings.cert.fail.read_file.title"),
                        t("settings.cert.fail.read_file.body"));
            }
        });

        inspectBtn.setOnAction(ev -> {
            if (base64Holder[0] == null) return;
            String pwd = passwordField.getText();
            Task<com.benjagest.ui.model.CertificateInspectInfo> task = new Task<>() {
                @Override
                protected com.benjagest.ui.model.CertificateInspectInfo call() throws Exception {
                    return certificateApi.inspect(base64Holder[0], pwd);
                }
            };
            task.setOnSucceeded(e -> {
                var info = task.getValue();
                if (info.subjectName() != null) subjectField.setText(info.subjectName());
                if (info.subjectTaxIdentifier() != null) nifField.setText(info.subjectTaxIdentifier());
                if (info.certificateTypeGuess() != null) typeCombo.getSelectionModel().select(info.certificateTypeGuess());
                if (info.validFrom() != null) {
                    validFromField.setText(info.validFrom().atZone(java.time.ZoneId.systemDefault())
                            .toLocalDate().toString());
                }
                if (info.validTo() != null) {
                    validToField.setText(info.validTo().atZone(java.time.ZoneId.systemDefault())
                            .toLocalDate().toString());
                }
                if (aliasField.getText().isBlank() && info.subjectName() != null) {
                    aliasField.setText(info.subjectName());
                }
            });
            task.setOnFailed(e -> showError(t("settings.cert.fail.inspect.title"),
                    t("settings.cert.fail.inspect.body")));
            start(task, "certificate-inspect");
        });

        GridPane g = new GridPane();
        g.setHgap(12); g.setVgap(10);
        int r = 0;
        g.add(new Label(t("settings.cert.upload.file")), 0, r);
        HBox fileBox = new HBox(8, chooseBtn, fileLabel);
        g.add(fileBox, 1, r++);
        g.add(new Label(t("settings.cert.upload.password")), 0, r); g.add(passwordField, 1, r++);
        g.add(new Label(""), 0, r); g.add(inspectBtn, 1, r++);
        g.add(new Separator(), 0, r++, 2, 1);
        g.add(new Label(t("settings.cert.upload.alias")), 0, r); g.add(aliasField, 1, r++);
        g.add(new Label(t("settings.cert.upload.type")), 0, r); g.add(typeCombo, 1, r++);
        g.add(new Label(t("settings.cert.upload.subject")), 0, r); g.add(subjectField, 1, r++);
        g.add(new Label(t("settings.cert.upload.nif")), 0, r); g.add(nifField, 1, r++);
        g.add(new Label(t("settings.cert.upload.valid_from")), 0, r); g.add(validFromField, 1, r++);
        g.add(new Label(t("settings.cert.upload.valid_to")), 0, r); g.add(validToField, 1, r++);
        Label tip = new Label(t("settings.cert.upload.tip"));
        tip.setWrapText(true);
        tip.getStyleClass().add("settings-hint");
        g.add(tip, 0, r++, 2, 1);

        installDialog(dialog, g);
        dialog.getDialogPane().setPrefWidth(580);

        Button save = (Button) dialog.getDialogPane().lookupButton(saveBt);
        save.addEventFilter(javafx.event.ActionEvent.ACTION, ev -> {
            ev.consume();
            if (base64Holder[0] == null) {
                showError(t("settings.cert.fail.no_file.title"),
                        t("settings.cert.fail.no_file.body"));
                return;
            }
            if (aliasField.getText().isBlank()) {
                showError(t("settings.cert.fail.no_alias.title"),
                        t("settings.cert.fail.no_alias.body"));
                return;
            }
            java.time.Instant vFrom = parseDateInstant(validFromField.getText());
            java.time.Instant vTo = parseDateInstant(validToField.getText());
            String pwd = passwordField.getText();
            String b64 = base64Holder[0];
            String alias = aliasField.getText().trim();
            String type = typeCombo.getValue() == null ? "OTRO" : typeCombo.getValue();
            String subject = subjectField.getText().trim();
            String nif = nifField.getText().trim();
            Task<com.benjagest.ui.model.CertificateSummaryEntry> task = new Task<>() {
                @Override
                protected com.benjagest.ui.model.CertificateSummaryEntry call() throws Exception {
                    return certificateApi.upload(alias, type,
                            subject.isBlank() ? null : subject,
                            nif.isBlank() ? null : nif,
                            pwd.isBlank() ? null : pwd,
                            b64, vFrom, vTo);
                }
            };
            task.setOnSucceeded(e -> {
                dialog.setResult(saveBt);
                dialog.close();
                reloadCertificates();
            });
            task.setOnFailed(e -> showError(t("settings.cert.fail.upload.title"),
                    t("settings.cert.fail.upload.body")));
            start(task, "certificate-upload");
        });

        dialog.showAndWait();
    }

    private java.time.Instant parseDateInstant(String text) {
        if (text == null || text.isBlank()) return null;
        try {
            return java.time.LocalDate.parse(text.trim())
                    .atStartOfDay(java.time.ZoneId.systemDefault()).toInstant();
        } catch (Exception ex) {
            return null;
        }
    }

    /**
     * Pestaña "Mi asesoría" del empresario: muestra la asesoría a la
     * que está vinculado (si la hay) + botón Desvincular. Si no hay
     * vínculo, muestra hint explicando cómo aceptar una invitación
     * y ofrece un campo para pegar el token directamente (útil
     * cuando la invitación llegó pero el banner del Home no la
     * recogió, o cuando el empresario quiere re-vincularse).
     */
    private Node settingsMyAdvisoryTab() {
        Label sectionTitle = label(t("settings.my_advisory.section"), "settings-section-title");
        Label hint = new Label(t("settings.my_advisory.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        VBox infoSlot = new VBox(8);
        infoSlot.setPadding(new Insets(8, 0, 0, 0));

        // Bloque "Pegar token" — siempre visible para que el empresario
        // pueda vincularse manualmente con cualquier token que le
        // pasen, independientemente de si tiene una asesoría vinculada
        // (en ese caso, debe desvincularse primero, claro).
        Label tokenTitle = label(t("settings.my_advisory.paste_token.title"), "settings-section-title");
        Label tokenHint = new Label(t("settings.my_advisory.paste_token.hint"));
        tokenHint.setWrapText(true);
        tokenHint.getStyleClass().add("settings-hint");
        TextField tokenField = new TextField();
        tokenField.setPromptText(t("settings.my_advisory.paste_token.prompt"));
        tokenField.setPrefColumnCount(40);
        Button acceptTokenBtn = new Button(t("settings.my_advisory.paste_token.accept"));
        acceptTokenBtn.setGraphic(icon("fas-link"));
        acceptTokenBtn.getStyleClass().add("button-primary");
        HBox tokenRow = new HBox(8, tokenField, acceptTokenBtn);
        tokenRow.setAlignment(Pos.CENTER_LEFT);
        VBox tokenBlock = new VBox(8, tokenTitle, tokenHint, tokenRow);
        tokenBlock.setPadding(new Insets(12, 0, 0, 0));

        Button unlinkBtn = new Button(t("settings.my_advisory.action.unlink"));
        unlinkBtn.setGraphic(icon("fas-unlink"));
        unlinkBtn.getStyleClass().add("button-danger-outline");
        unlinkBtn.setDisable(true);

        Runnable reload = () -> {
            infoSlot.getChildren().clear();
            unlinkBtn.setDisable(true);
            Task<com.benjagest.ui.service.AdvisoryInvitationApiClient.LinkedAdvisory> task = new Task<>() {
                @Override
                protected com.benjagest.ui.service.AdvisoryInvitationApiClient.LinkedAdvisory
                        call() throws Exception {
                    return invitationsApi.getLinkedAdvisory();
                }
            };
            task.setOnSucceeded(e -> {
                var link = task.getValue();
                if (link == null) {
                    Label empty = new Label(t("settings.my_advisory.empty"));
                    empty.setWrapText(true);
                    empty.getStyleClass().add("settings-hint");
                    infoSlot.getChildren().add(empty);
                    unlinkBtn.setDisable(true);
                    return;
                }
                GridPane g = new GridPane();
                g.setHgap(12); g.setVgap(6);
                int r = 0;
                g.add(new Label(t("settings.my_advisory.field.legal_name")), 0, r);
                g.add(new Label(link.legalName() == null ? "—" : link.legalName()), 1, r++);
                if (link.tradeName() != null && !link.tradeName().isBlank()) {
                    g.add(new Label(t("settings.my_advisory.field.trade_name")), 0, r);
                    g.add(new Label(link.tradeName()), 1, r++);
                }
                g.add(new Label(t("settings.my_advisory.field.nif")), 0, r);
                g.add(new Label(link.taxIdentifier() == null ? "—" : link.taxIdentifier()), 1, r++);
                g.add(new Label(t("settings.my_advisory.field.email")), 0, r);
                g.add(new Label(link.email() == null ? "—" : link.email()), 1, r++);
                infoSlot.getChildren().add(g);
                unlinkBtn.setDisable(false);
            });
            task.setOnFailed(e -> showError(t("settings.my_advisory.fail.load.title"),
                    t("settings.my_advisory.fail.load.body")));
            start(task, "my-advisory-load");
        };

        unlinkBtn.setOnAction(ev -> {
            Alert confirm = new Alert(Alert.AlertType.CONFIRMATION,
                    t("settings.my_advisory.confirm.unlink.body"),
                    ButtonType.OK, ButtonType.CANCEL);
            confirm.setHeaderText(t("settings.my_advisory.confirm.unlink.title"));
            confirm.showAndWait().filter(b -> b == ButtonType.OK).ifPresent(b -> {
                Task<Void> task = new Task<>() {
                    @Override
                    protected Void call() throws Exception {
                        invitationsApi.unlink();
                        return null;
                    }
                };
                task.setOnSucceeded(e -> {
                    // Refresco local inmediato: la pestaña "Mi asesoría"
                    // tiene que mostrar YA que el vínculo desapareció,
                    // sin esperar al tick de 5s.
                    reload.run();
                    pollPendingInvitations();
                    // COMM-LINK 2026-06-11: el módulo Comunicación
                    // desaparece del sidebar al perder el vínculo.
                    refreshActiveModulesAndRender();
                });
                task.setOnFailed(e -> showError(t("settings.my_advisory.fail.unlink.title"),
                        t("settings.my_advisory.fail.unlink.body")));
                start(task, "my-advisory-unlink");
            });
        });

        acceptTokenBtn.setOnAction(ev -> {
            String token = tokenField.getText();
            if (token == null || token.isBlank()) {
                showError(t("settings.my_advisory.paste_token.fail.empty.title"),
                        t("settings.my_advisory.paste_token.fail.empty.body"));
                return;
            }
            Task<com.benjagest.ui.model.AdvisoryInvitationEntry> task = new Task<>() {
                @Override
                protected com.benjagest.ui.model.AdvisoryInvitationEntry call() throws Exception {
                    return invitationsApi.accept(token.trim());
                }
            };
            task.setOnSucceeded(e -> {
                showInfo(t("advisory.invitation.accept.ok.title"),
                        t("advisory.invitation.accept.ok.body"));
                tokenField.clear();
                reload.run();
                pollPendingInvitations();
            });
            task.setOnFailed(e -> showError(t("advisory.invitation.accept.fail.title"),
                    t("advisory.invitation.accept.fail.body")));
            start(task, "advisory-invitation-accept-by-token");
        });

        HBox actions = new HBox(8, unlinkBtn);
        VBox header = new VBox(8, sectionTitle, hint);
        VBox body = new VBox(12, infoSlot, new Separator(), tokenBlock);

        reload.run();
        // 2026-06-11 — los sub-tabs Mensajes y Documentos se han movido
        // al nuevo módulo "Comunicación" del sidebar (showCommModule).
        // "Mi asesoría" de Configuración mantiene solo el panel de
        // Vínculo (token de emparejado + datos asesoría + desvincular).
        return tabLayout(header, body, actions);
    }

    /**
     * Pestaña "Mensajes" del módulo Comunicación. Recibe el destinatario
     * activo como observable — el selector externo lo controla. Cuando
     * cambia el observable, recarga el timeline.
     */
    private Node buildCommMessagesPane(
            javafx.beans.value.ObservableValue<String> otherIdObs) {
        VBox root = new VBox(12);
        root.setPadding(new Insets(12, 4, 4, 4));

        // Timeline
        javafx.scene.control.ListView<com.benjagest.ui.model.AdvisoryMessageEntry> timeline =
                new javafx.scene.control.ListView<>();
        timeline.getStyleClass().add("comm-timeline");
        Label timelinePlaceholder = new Label(t("module.comm.messages.pick_recipient"));
        timelinePlaceholder.getStyleClass().add("comm-empty");
        timelinePlaceholder.setWrapText(true);
        timeline.setPlaceholder(timelinePlaceholder);
        timeline.setCellFactory(lv -> new javafx.scene.control.ListCell<com.benjagest.ui.model.AdvisoryMessageEntry>() {
            @Override protected void updateItem(
                    com.benjagest.ui.model.AdvisoryMessageEntry item, boolean empty) {
                super.updateItem(item, empty);
                if (empty || item == null) {
                    setText((String) null);
                    setGraphic((javafx.scene.Node) null);
                    return;
                }
                boolean isA2C = com.benjagest.ui.model.AdvisoryMessageEntry.DIRECTION_A2C
                        .equals(item.direction());
                VBox bubble = new VBox(2);
                Label sender = new Label(isA2C
                        ? t("module.comm.sender.advisory")
                        : t("module.comm.sender.company"));
                sender.getStyleClass().add("comm-sender");
                if (!isA2C) {
                    sender.getStyleClass().add("comm-sender-company");
                }
                Label body = new Label(item.body());
                body.setWrapText(true);
                body.getStyleClass().add("comm-bubble-body");
                Label meta = new Label(item.createdAt() == null ? ""
                        : item.createdAt().length() > 16
                            ? item.createdAt().substring(0, 16) : item.createdAt());
                meta.getStyleClass().add("comm-meta");
                bubble.getChildren().addAll(sender, body, meta);
                bubble.setMaxWidth(520);
                bubble.getStyleClass().addAll("comm-bubble",
                        isA2C ? "comm-bubble-in" : "comm-bubble-out");
                javafx.scene.layout.HBox row = new javafx.scene.layout.HBox(bubble);
                row.setPadding(new Insets(3, 4, 3, 4));
                row.setAlignment(isA2C ? Pos.CENTER_LEFT : Pos.CENTER_RIGHT);
                setGraphic(row);
            }
        });

        // Caja de envío — composer inferior estilo chat.
        javafx.scene.control.TextArea sendBox = new javafx.scene.control.TextArea();
        sendBox.setPromptText(t("advisory.messages.send_prompt"));
        sendBox.setPrefRowCount(2);
        sendBox.setWrapText(true);
        Button sendBtn = new Button(t("advisory.messages.send"));
        sendBtn.setGraphic(icon("fas-paper-plane"));
        sendBtn.getStyleClass().add("button-primary");
        // Desactivado mientras no haya destinatario seleccionado.
        sendBtn.setDisable(otherIdObs.getValue() == null || otherIdObs.getValue().isBlank());
        HBox sendRow = new HBox(8, sendBox, sendBtn);
        sendRow.getStyleClass().add("comm-composer");
        HBox.setHgrow(sendBox, Priority.ALWAYS);
        sendRow.setAlignment(Pos.BOTTOM_RIGHT);

        Runnable reloadTimeline = () -> {
            String other = otherIdObs.getValue();
            if (other == null || other.isBlank()) {
                timelinePlaceholder.setText(t("module.comm.messages.pick_recipient"));
                timeline.setItems(FXCollections.observableArrayList());
                return;
            }
            timelinePlaceholder.setText(t("module.comm.messages.empty"));
            Task<java.util.List<com.benjagest.ui.model.AdvisoryMessageEntry>> task = new Task<>() {
                @Override protected java.util.List<com.benjagest.ui.model.AdvisoryMessageEntry> call() throws Exception {
                    java.util.List<com.benjagest.ui.model.AdvisoryMessageEntry> msgs =
                            altaApiClient.listAdvisoryThread(other);
                    try { altaApiClient.markAdvisoryThreadRead(other); } catch (Exception ignore) {}
                    return msgs;
                }
            };
            task.setOnSucceeded(ev -> {
                timeline.setItems(FXCollections.observableArrayList(task.getValue()));
                if (!task.getValue().isEmpty()) {
                    timeline.scrollTo(task.getValue().size() - 1);
                }
            });
            task.setOnFailed(ev -> { /* puede no haber thread aún — silencio */ });
            start(task, "comm-thread-load");
        };

        otherIdObs.addListener((o, ov, nv) -> {
            sendBtn.setDisable(nv == null || nv.isBlank());
            reloadTimeline.run();
        });
        sendBtn.setOnAction(ev -> {
            String other = otherIdObs.getValue();
            if (other == null || other.isBlank()) return;
            String body = sendBox.getText();
            if (body == null || body.isBlank()) return;
            Task<Void> task = new Task<>() {
                @Override protected Void call() throws Exception {
                    altaApiClient.sendAdvisoryMessage(other, body, null);
                    return null;
                }
            };
            task.setOnSucceeded(e -> { sendBox.clear(); reloadTimeline.run(); });
            task.setOnFailed(e -> showError(t("advisory.messages.fail.title"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "comm-send");
        });

        reloadTimeline.run();

        // Conversación arriba (crece), composer abajo (siempre visible) — patrón chat.
        VBox body = new VBox(10, timeline, sendRow);
        VBox.setVgrow(timeline, Priority.ALWAYS);
        VBox.setVgrow(body, Priority.ALWAYS);
        root.getChildren().add(body);
        return root;
    }

    /**
     * 2026-06-10 noche — Sub-pestaña "Documentos" con upload multipart
     * real + review + download. Backend AdvisoryDocumentUploadController
     * añade endpoints upload/download al service V78.
     */
    private Node buildCommDocumentsPane(
            javafx.beans.value.ObservableValue<String> otherIdObs) {
        VBox root = new VBox(12);
        root.setPadding(new Insets(12, 4, 4, 4));

        TableView<com.benjagest.ui.model.AdvisoryDocumentEntry> table = new TableView<>();
        table.getStyleClass().add("data-table");
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPlaceholder(new Label(t("advisory.documents.empty")));

        TableColumn<com.benjagest.ui.model.AdvisoryDocumentEntry, String> cWhen =
                new TableColumn<>(t("advisory.documents.col.date"));
        cWhen.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().createdAt() == null || c.getValue().createdAt().length() < 16
                        ? c.getValue().createdAt()
                        : c.getValue().createdAt().substring(0, 16)));
        cWhen.setPrefWidth(140);
        cWhen.setComparator(ISO_DATE_COMPARATOR);
        TableColumn<com.benjagest.ui.model.AdvisoryDocumentEntry, String> cDir =
                new TableColumn<>(t("advisory.documents.col.dir"));
        cDir.setCellValueFactory(c -> new SimpleStringProperty(
                "A2C".equals(c.getValue().direction())
                        ? t("advisory.documents.dir.a2c")
                        : t("advisory.documents.dir.c2a")));
        cDir.setPrefWidth(120);
        TableColumn<com.benjagest.ui.model.AdvisoryDocumentEntry, String> cTitle =
                new TableColumn<>(t("advisory.documents.col.title"));
        cTitle.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().title()));
        TableColumn<com.benjagest.ui.model.AdvisoryDocumentEntry, String> cSize =
                new TableColumn<>(t("advisory.documents.col.size"));
        cSize.setCellValueFactory(c -> new SimpleStringProperty(
                humanSize(c.getValue().fileSizeBytes())));
        cSize.setPrefWidth(90);
        TableColumn<com.benjagest.ui.model.AdvisoryDocumentEntry, String> cStatus =
                new TableColumn<>(t("advisory.documents.col.status"));
        cStatus.setCellValueFactory(c -> new SimpleStringProperty(
                humanizeDocStatus(c.getValue().status())));
        cStatus.setPrefWidth(110);
        TableColumn<com.benjagest.ui.model.AdvisoryDocumentEntry, String> cNote =
                new TableColumn<>(t("advisory.documents.col.note"));
        cNote.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().note()));

        table.getColumns().addAll(java.util.List.of(
                cWhen, cDir, cTitle, cSize, cStatus, cNote));

        Button uploadBtn = new Button(t("advisory.documents.upload"));
        uploadBtn.setGraphic(icon("fas-upload"));
        uploadBtn.getStyleClass().add("button-primary");
        uploadBtn.setDisable(otherIdObs.getValue() == null || otherIdObs.getValue().isBlank());
        Button downloadBtn = new Button(t("advisory.documents.download"));
        downloadBtn.setGraphic(icon("fas-download"));
        downloadBtn.setDisable(true);
        Button acceptBtn = new Button(t("advisory.documents.accept"));
        acceptBtn.setGraphic(icon("fas-check"));
        acceptBtn.setDisable(true);
        Button rejectBtn = new Button(t("advisory.documents.reject"));
        rejectBtn.setGraphic(icon("fas-times"));
        rejectBtn.setDisable(true);

        HBox actions = new HBox(8, uploadBtn, downloadBtn, acceptBtn, rejectBtn);
        actions.setAlignment(Pos.CENTER_LEFT);

        Runnable reloadDocs = () -> {
            String other = otherIdObs.getValue();
            if (other == null || other.isBlank()) { table.getItems().clear(); return; }
            Task<java.util.List<com.benjagest.ui.model.AdvisoryDocumentEntry>> t = new Task<>() {
                @Override protected java.util.List<com.benjagest.ui.model.AdvisoryDocumentEntry> call() throws Exception {
                    return altaApiClient.listAdvisoryDocuments(other);
                }
            };
            t.setOnSucceeded(ev -> table.setItems(FXCollections.observableArrayList(t.getValue())));
            t.setOnFailed(ev -> { /* puede no haber thread aún — silencio */ });
            start(t, "comm-docs-list");
        };
        otherIdObs.addListener((o, ov, nv) -> {
            uploadBtn.setDisable(nv == null || nv.isBlank());
            reloadDocs.run();
        });
        table.getSelectionModel().selectedItemProperty().addListener((o, ov, nv) -> {
            boolean sel = nv != null;
            downloadBtn.setDisable(!sel);
            boolean reviewable = sel
                    && com.benjagest.ui.model.AdvisoryDocumentEntry.STATUS_UPLOADED.equals(nv.status());
            acceptBtn.setDisable(!reviewable);
            rejectBtn.setDisable(!reviewable);
        });

        uploadBtn.setOnAction(ev -> {
            String other = otherIdObs.getValue();
            if (other == null || other.isBlank()) return;
            javafx.stage.FileChooser fc = new javafx.stage.FileChooser();
            fc.setTitle(t("advisory.documents.upload"));
            fc.getExtensionFilters().add(new javafx.stage.FileChooser.ExtensionFilter(
                    "PDF / PNG / JPG / DOCX / XLSX",
                    "*.pdf", "*.png", "*.jpg", "*.jpeg", "*.docx", "*.xlsx"));
            java.io.File f = fc.showOpenDialog(root.getScene().getWindow());
            if (f == null) return;
            javafx.scene.control.TextInputDialog td = new javafx.scene.control.TextInputDialog(f.getName());
            td.setTitle(t("advisory.documents.upload"));
            td.setHeaderText(t("advisory.documents.title_prompt"));
            String title2 = td.showAndWait().orElse(f.getName());
            Task<Void> up = new Task<>() {
                @Override protected Void call() throws Exception {
                    altaApiClient.uploadAdvisoryDocument(other, f, title2);
                    return null;
                }
            };
            up.setOnSucceeded(s -> reloadDocs.run());
            up.setOnFailed(s -> showError(t("advisory.documents.fail.title"),
                    up.getException() == null ? "" : up.getException().getMessage()));
            start(up, "comm-docs-upload");
        });
        downloadBtn.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            javafx.stage.FileChooser fc = new javafx.stage.FileChooser();
            fc.setTitle(t("advisory.documents.download"));
            String filename = sel.filePath() == null ? sel.title()
                    : java.nio.file.Paths.get(sel.filePath()).getFileName().toString();
            int dash = filename.indexOf('-');
            if (dash > 0 && dash < 40) filename = filename.substring(dash + 1);
            fc.setInitialFileName(filename);
            java.io.File target = fc.showSaveDialog(root.getScene().getWindow());
            if (target == null) return;
            Task<byte[]> dl = new Task<>() {
                @Override protected byte[] call() throws Exception {
                    return altaApiClient.downloadAdvisoryDocument(sel.id());
                }
            };
            dl.setOnSucceeded(s -> {
                try {
                    java.nio.file.Files.write(target.toPath(), dl.getValue());
                    showInfo(t("advisory.documents.dl.ok.title"),
                            t("advisory.documents.dl.ok.body") + "\n"
                                    + target.getAbsolutePath());
                } catch (java.io.IOException ex) {
                    showError(t("advisory.documents.fail.title"), ex.getMessage());
                }
            });
            dl.setOnFailed(s -> showError(t("advisory.documents.fail.title"),
                    dl.getException() == null ? "" : dl.getException().getMessage()));
            start(dl, "advisory-docs-download");
        });
        acceptBtn.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            Task<Void> task = new Task<>() {
                @Override protected Void call() throws Exception {
                    altaApiClient.reviewAdvisoryDocument(sel.id(),
                            com.benjagest.ui.model.AdvisoryDocumentEntry.STATUS_ACCEPTED, null);
                    return null;
                }
            };
            task.setOnSucceeded(s -> reloadDocs.run());
            task.setOnFailed(s -> showError(t("advisory.documents.fail.title"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "advisory-docs-accept");
        });
        rejectBtn.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            javafx.scene.control.TextInputDialog td =
                    new javafx.scene.control.TextInputDialog();
            td.setTitle(t("advisory.documents.reject"));
            td.setHeaderText(t("advisory.documents.reject_prompt"));
            String note = td.showAndWait().orElse("");
            Task<Void> task = new Task<>() {
                @Override protected Void call() throws Exception {
                    altaApiClient.reviewAdvisoryDocument(sel.id(),
                            com.benjagest.ui.model.AdvisoryDocumentEntry.STATUS_REJECTED, note);
                    return null;
                }
            };
            task.setOnSucceeded(s -> reloadDocs.run());
            task.setOnFailed(s -> showError(t("advisory.documents.fail.title"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "comm-docs-reject");
        });

        reloadDocs.run();

        VBox.setVgrow(table, Priority.ALWAYS);
        root.getChildren().addAll(actions, table);
        return root;
    }

    /** Item del selector del módulo Comunicación. id = otherCompanyId. */
    private record CommRecipient(String id, String label) {
        @Override public String toString() { return label == null ? id : label; }
    }

    /**
     * Módulo Comunicación (slice COMM-MOD 2026-06-11):
     *   - Selector arriba: en BUSINESS la asesoría vinculada (1 item),
     *     en ADVISORY la cartera de clientes.
     *   - Tabs Mensajes / Documentos compartiendo el destinatario activo.
     */
    private void showCommModule() {
        VBox content = content();
        StackPane commIcon = iconBubble("fas-comments", "module-title-icon");
        Label title = label(t("module.comm.title"), "module-detail-title");
        Label hint = new Label(t("module.comm.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");
        VBox commTitleBox = new VBox(2, title, hint);
        HBox commHeader = new HBox(16, commIcon, commTitleBox);
        commHeader.setAlignment(Pos.CENTER_LEFT);
        commHeader.getStyleClass().add("module-detail-header");

        ComboBox<CommRecipient> recipientCombo = new ComboBox<>();
        recipientCombo.setPromptText(t("module.comm.recipient.prompt"));
        recipientCombo.setMinWidth(360);

        javafx.beans.property.SimpleStringProperty otherIdProperty =
                new javafx.beans.property.SimpleStringProperty(null);
        recipientCombo.valueProperty().addListener((o, ov, nv) ->
                otherIdProperty.set(nv == null ? null : nv.id()));

        Label recipientLabel = new Label(appMode == AppMode.ADVISORY
                ? t("module.comm.recipient.client")
                : t("module.comm.recipient.advisory"));
        HBox selectorRow = new HBox(8, recipientLabel, recipientCombo);
        selectorRow.setAlignment(Pos.CENTER_LEFT);

        TabPane tabs = new TabPane();
        tabs.getStyleClass().add("settings-tabs");
        tabs.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);
        Tab tMessages = new Tab(t("module.comm.tab.messages"),
                buildCommMessagesPane(otherIdProperty));
        tMessages.setGraphic(icon("fas-comments"));
        Tab tDocs = new Tab(t("module.comm.tab.documents"),
                buildCommDocumentsPane(otherIdProperty));
        tDocs.setGraphic(icon("fas-folder-open"));
        tabs.getTabs().addAll(tMessages, tDocs);

        // Carga inicial de destinatarios según modo
        Task<java.util.List<CommRecipient>> loadRecipients = new Task<>() {
            @Override protected java.util.List<CommRecipient> call() throws Exception {
                java.util.List<CommRecipient> out = new java.util.ArrayList<>();
                if (appMode == AppMode.ADVISORY) {
                    for (var c : altaApiClient.listAdvisoryPortfolio()) {
                        // Solo clientes con vínculo REAL aceptado: tienen
                        // su propia company y aceptaron la invitación.
                        // Las shadow companies (MANAGED_CLIENT) no tienen
                        // login y nadie podrá leer los mensajes desde el
                        // otro lado — por eso quedan fuera del selector.
                        if (!c.fullyLinked() || c.linkedCompanyId() == null) continue;
                        out.add(new CommRecipient(c.linkedCompanyId(), c.legalName()));
                    }
                } else {
                    var linked = invitationsApi.getLinkedAdvisory();
                    if (linked != null && linked.id() != null) {
                        out.add(new CommRecipient(linked.id(), linked.legalName()));
                    }
                }
                return out;
            }
        };
        loadRecipients.setOnSucceeded(ev -> {
            recipientCombo.getItems().setAll(loadRecipients.getValue());
            if (!loadRecipients.getValue().isEmpty()) {
                recipientCombo.getSelectionModel().selectFirst();
            }
        });
        loadRecipients.setOnFailed(ev -> showError(t("module.comm.recipient.fail.title"),
                loadRecipients.getException() == null ? "" :
                        loadRecipients.getException().getMessage()));
        start(loadRecipients, "comm-load-recipients");

        VBox.setVgrow(tabs, Priority.ALWAYS);
        content.getChildren().addAll(commHeader, selectorRow, tabs);
        setCenterAnimated(scroll(content));
    }

    private String humanizeDocStatus(String raw) {
        if (raw == null || raw.isBlank()) return "";
        return switch (raw) {
            case "UPLOADED" -> t("advisory.documents.status.uploaded");
            case "REVIEWED" -> t("advisory.documents.status.reviewed");
            case "ACCEPTED" -> t("advisory.documents.status.accepted");
            case "REJECTED" -> t("advisory.documents.status.rejected");
            default -> raw;
        };
    }

    private static String humanSize(long bytes) {
        if (bytes < 1024) return bytes + " B";
        if (bytes < 1024L * 1024) return String.format("%.1f KB", bytes / 1024.0);
        return String.format("%.1f MB", bytes / (1024.0 * 1024));
    }

    /**
     * TPB — Pestaña "Mi acuerdo de facturación" en Configuración del
     * empresario. Muestra el estado del acuerdo con la asesoría
     * vinculada, permite descargar el PDF firmado, firmar (si
     * pendiente) y revocar.
     */
    private Node settingsMyTpbTab() {
        Label title = label(t("settings.my_tpb.section"), "settings-section-title");
        Label hint = new Label(t("settings.my_tpb.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        VBox stateSlot = new VBox(10);
        stateSlot.setPadding(new Insets(8, 0, 0, 0));

        Runnable[] reloadHolder = new Runnable[1];
        Runnable reload = () -> {
            stateSlot.getChildren().clear();
            Label loading = new Label(t("settings.my_tpb.loading"));
            loading.getStyleClass().add("settings-hint");
            stateSlot.getChildren().add(loading);
            Task<Object[]> task = new Task<>() {
                @Override
                protected Object[] call() throws Exception {
                    var linked = invitationsApi.getLinkedAdvisory();
                    if (linked == null || linked.id() == null) return null;
                    var a = altaApiClient.tpbFindCurrent(linked.id());
                    return new Object[]{ a, linked };
                }
            };
            task.setOnSucceeded(ev -> renderMyTpbState(stateSlot, task.getValue(),
                    reloadHolder[0]));
            task.setOnFailed(ev -> {
                stateSlot.getChildren().clear();
                Label err = new Label(t("settings.my_tpb.fail") + " "
                        + (task.getException() == null ? "" : task.getException().getMessage()));
                err.setWrapText(true);
                err.setStyle("-fx-text-fill: #b91c1c;");
                stateSlot.getChildren().add(err);
            });
            start(task, "my-tpb-load");
        };
        reloadHolder[0] = reload;
        reload.run();

        Button reloadBtn = new Button(t("tpb.action.reload"));
        reloadBtn.setGraphic(icon("fas-sync-alt"));
        reloadBtn.setOnAction(e -> reload.run());

        Region sp = new Region();
        HBox.setHgrow(sp, Priority.ALWAYS);
        HBox titleRow = new HBox(12, title, sp, reloadBtn);
        titleRow.setAlignment(Pos.CENTER_LEFT);

        VBox layout = new VBox(12, titleRow, hint, stateSlot);
        layout.getStyleClass().add("settings-tab-body");
        return layout;
    }

    private void renderMyTpbState(VBox slot, Object[] res, Runnable reload) {
        slot.getChildren().clear();
        if (res == null) {
            Label none = new Label(t("settings.my_tpb.no_linked"));
            none.setWrapText(true);
            slot.getChildren().add(none);
            return;
        }
        var a = (com.benjagest.ui.model.TpbAgreementEntry) res[0];
        var linked = (com.benjagest.ui.service.AdvisoryInvitationApiClient.LinkedAdvisory) res[1];
        String advisoryName = linked.tradeName() != null && !linked.tradeName().isBlank()
                ? linked.tradeName() : linked.legalName();
        Label advisoryLbl = new Label(t("settings.my_tpb.advisor") + " " + advisoryName);
        advisoryLbl.setStyle("-fx-font-weight: bold;");
        slot.getChildren().add(advisoryLbl);
        if (a == null) {
            Label none = new Label(t("settings.my_tpb.empty"));
            none.setWrapText(true);
            slot.getChildren().add(none);
            return;
        }
        GridPane g = new GridPane();
        g.setHgap(20); g.setVgap(6);
        int r = 0;
        g.add(new Label(t("tpb.field.status")), 0, r);
        Label st = new Label(humanizeTpbStatus(a.status()));
        st.setStyle("-fx-font-weight: bold; -fx-text-fill: "
                + (a.isActive() ? "#16a34a" : a.isPending() ? "#d97706" : "#64748b") + ";");
        g.add(st, 1, r++);
        g.add(new Label(t("tpb.field.scope")), 0, r);
        g.add(new Label(humanizeTpbScope(a)), 1, r++);
        if (a.signedAt() != null && !a.signedAt().isBlank()) {
            g.add(new Label(t("tpb.field.signed_at")), 0, r);
            g.add(new Label(a.signedAt()), 1, r++);
            g.add(new Label(t("tpb.field.signed_method")), 0, r);
            g.add(new Label(humanizeTpbMethod(a.signedMethod())), 1, r++);
        }
        slot.getChildren().add(g);

        HBox actions = new HBox(8);
        actions.setAlignment(Pos.CENTER_LEFT);
        if (a.isPending()) {
            Button sign = new Button(t("tpb.banner.sign"));
            sign.setGraphic(icon("fas-signature"));
            sign.getStyleClass().add("button-primary");
            sign.setOnAction(e -> {
                // Reusamos el mismo dialogo del banner. Tras firmar
                // recargamos este panel para reflejar ACTIVE.
                VBox holder = new VBox();
                showTpbSignWithPinDialog(a, holder);
                reload.run();
            });
            actions.getChildren().add(sign);
        }
        if (a.isActive()) {
            Button dl = new Button(t("tpb.signed.download"));
            dl.setGraphic(icon("fas-file-pdf"));
            dl.setOnAction(e -> tpbDownloadSignedPdfAction(a.id()));
            actions.getChildren().add(dl);
        }
        if (a.isActive() || a.isPending()) {
            Button revoke = new Button(t("tpb.revoke"));
            revoke.setGraphic(icon("fas-ban"));
            revoke.setOnAction(e -> tpbRevokeAction(a.id(), reload));
            actions.getChildren().add(revoke);
        }
        slot.getChildren().add(actions);
    }

    /**
     * BOE-RSS — Pestaña de alertas BOE para la asesoría.
     * Lista alertas históricas (últimos N días, default 30) y permite
     * forzar el barrido del día actual (botón "Buscar ahora").
     */
    private Node settingsBoeAlertsTab() {
        Label sectionTitle = label(t("settings.boe.section"), "settings-section-title");
        Label hint = new Label(t("settings.boe.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        javafx.scene.control.ComboBox<Integer> daysCombo = new javafx.scene.control.ComboBox<>();
        daysCombo.getItems().addAll(7, 30, 90, 180, 365);
        daysCombo.getSelectionModel().select(Integer.valueOf(30));
        daysCombo.getStyleClass().add("form-input");

        TableView<com.benjagest.ui.model.BoeAlertEntry> table = new TableView<>();
        table.getStyleClass().add("data-table");
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPlaceholder(new Label(t("settings.boe.empty")));

        TableColumn<com.benjagest.ui.model.BoeAlertEntry, String> colDate =
                new TableColumn<>(t("settings.boe.col.date"));
        colDate.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().alertDate()));
        colDate.setPrefWidth(110);
        colDate.setComparator(ISO_DATE_COMPARATOR);

        TableColumn<com.benjagest.ui.model.BoeAlertEntry, String> colBoeId =
                new TableColumn<>(t("settings.boe.col.boe_id"));
        colBoeId.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().boeId()));
        colBoeId.setPrefWidth(140);

        TableColumn<com.benjagest.ui.model.BoeAlertEntry, String> colTitle =
                new TableColumn<>(t("settings.boe.col.title"));
        colTitle.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().title()));
        colTitle.setPrefWidth(420);

        TableColumn<com.benjagest.ui.model.BoeAlertEntry, String> colKw =
                new TableColumn<>(t("settings.boe.col.keywords"));
        colKw.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().keywordsMatched()));
        colKw.setPrefWidth(220);

        TableColumn<com.benjagest.ui.model.BoeAlertEntry, String> colDept =
                new TableColumn<>(t("settings.boe.col.department"));
        colDept.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().department()));
        colDept.setPrefWidth(220);

        table.getColumns().addAll(List.of(colDate, colBoeId, colTitle, colKw, colDept));
        VBox.setVgrow(table, Priority.ALWAYS);

        Button openPdf = new Button(t("settings.boe.btn.open"));
        openPdf.setGraphic(icon("fas-external-link-alt"));
        openPdf.setDisable(true);
        openPdf.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null || sel.url() == null || sel.url().isBlank()) return;
            try { java.awt.Desktop.getDesktop().browse(java.net.URI.create(sel.url())); }
            catch (Exception ex) { showError(t("settings.boe.open.fail"), ex.getMessage()); }
        });
        table.getSelectionModel().selectedItemProperty().addListener((obs, o, n) ->
                openPdf.setDisable(n == null || n.url() == null || n.url().isBlank()));

        Button refresh = new Button(t("settings.boe.btn.refresh"));
        refresh.setGraphic(icon("fas-sync-alt"));
        Runnable load = () -> loadBoeAlerts(table, daysCombo.getValue());
        refresh.setOnAction(ev -> load.run());
        daysCombo.setOnAction(ev -> load.run());

        Button runNow = new Button(t("settings.boe.btn.run_now"));
        runNow.setGraphic(icon("fas-bolt"));
        runNow.getStyleClass().add("primary-button");
        runNow.setOnAction(ev -> runBoeNow(load));

        HBox filterRow = new HBox(10,
                label(t("settings.boe.filter.days"), "form-label"),
                daysCombo, refresh, runNow, openPdf);
        filterRow.setAlignment(Pos.CENTER_LEFT);

        load.run();

        VBox layout = new VBox(12, sectionTitle, hint, filterRow, table);
        layout.getStyleClass().add("settings-tab-body");
        return layout;
    }

    private void loadBoeAlerts(TableView<com.benjagest.ui.model.BoeAlertEntry> table, Integer days) {
        int d = days == null ? 30 : days;
        Task<List<com.benjagest.ui.model.BoeAlertEntry>> task = new Task<>() {
            @Override
            protected List<com.benjagest.ui.model.BoeAlertEntry> call() throws Exception {
                return altaApiClient.listBoeAlerts(d);
            }
        };
        task.setOnSucceeded(ev -> table.setItems(FXCollections.observableArrayList(task.getValue())));
        task.setOnFailed(ev -> showError(t("settings.boe.load.fail"),
                task.getException() == null ? "" : task.getException().getMessage()));
        start(task, "boe-alerts-load");
    }

    private void runBoeNow(Runnable onDone) {
        Task<Void> task = new Task<>() {
            @Override
            protected Void call() throws Exception {
                altaApiClient.runBoeAlertsNow(null);
                return null;
            }
        };
        task.setOnSucceeded(ev -> onDone.run());
        task.setOnFailed(ev -> showError(t("settings.boe.run.fail"),
                task.getException() == null ? "" : task.getException().getMessage()));
        start(task, "boe-alerts-run");
    }

    /**
     * BACKUP-LOCAL — pestaña Backups: lista snapshots .sql.zip
     * existentes, muestra ultima fecha + tamaño, permite forzar
     * backup ahora y abrir la carpeta en el explorador.
     */
    private Node settingsBackupTab() {
        Label sectionTitle = label(t("settings.backup.section"), "settings-section-title");
        Label hint = new Label(t("settings.backup.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        TableView<com.benjagest.ui.service.AltaApiClient.BackupInfoEntry> table = new TableView<>();
        table.getStyleClass().add("data-table");
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPlaceholder(new Label(t("settings.backup.empty")));

        TableColumn<com.benjagest.ui.service.AltaApiClient.BackupInfoEntry, String> colName =
                new TableColumn<>(t("settings.backup.col.file"));
        colName.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().filename()));
        colName.setPrefWidth(320);

        TableColumn<com.benjagest.ui.service.AltaApiClient.BackupInfoEntry, String> colSize =
                new TableColumn<>(t("settings.backup.col.size"));
        colSize.setCellValueFactory(c -> new SimpleStringProperty(humanSize(c.getValue().sizeBytes())));
        colSize.setPrefWidth(120);

        TableColumn<com.benjagest.ui.service.AltaApiClient.BackupInfoEntry, String> colWhen =
                new TableColumn<>(t("settings.backup.col.when"));
        colWhen.setCellValueFactory(c -> new SimpleStringProperty(shortIso(c.getValue().lastModified())));
        colWhen.setPrefWidth(180);
        colWhen.setComparator(ISO_DATE_COMPARATOR);

        TableColumn<com.benjagest.ui.service.AltaApiClient.BackupInfoEntry, String> colPath =
                new TableColumn<>(t("settings.backup.col.path"));
        colPath.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().fullPath()));
        colPath.setPrefWidth(420);

        table.getColumns().addAll(List.of(colWhen, colName, colSize, colPath));
        VBox.setVgrow(table, Priority.ALWAYS);

        Button refresh = new Button(t("settings.backup.btn.refresh"));
        refresh.setGraphic(icon("fas-sync-alt"));
        Runnable load = () -> loadBackups(table);
        refresh.setOnAction(ev -> load.run());

        Button runNow = new Button(t("settings.backup.btn.run_now"));
        runNow.setGraphic(icon("fas-save"));
        runNow.getStyleClass().add("primary-button");
        runNow.setOnAction(ev -> runBackupNow(load));

        Button openFolder = new Button(t("settings.backup.btn.open_folder"));
        openFolder.setGraphic(icon("fas-folder-open"));
        openFolder.setDisable(true);
        openFolder.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null || sel.fullPath() == null) return;
            try {
                java.io.File parent = new java.io.File(sel.fullPath()).getParentFile();
                if (parent != null) java.awt.Desktop.getDesktop().open(parent);
            } catch (Exception ex) {
                showError(t("settings.backup.open.fail"), ex.getMessage());
            }
        });
        table.getSelectionModel().selectedItemProperty().addListener((obs, o, n) ->
                openFolder.setDisable(n == null));

        Button purgeOrphans = new Button(t("settings.backup.btn.purge_orphans"));
        purgeOrphans.setGraphic(icon("fas-broom"));
        purgeOrphans.setOnAction(ev -> {
            Alert confirm = new Alert(Alert.AlertType.CONFIRMATION);
            confirm.setTitle(t("settings.backup.purge.title"));
            confirm.setHeaderText(t("settings.backup.purge.confirm"));
            confirm.showAndWait().ifPresent(rsp -> {
                if (rsp != javafx.scene.control.ButtonType.OK) return;
                purgeOrphans.setDisable(true);
                Task<Integer> task = new Task<>() {
                    @Override protected Integer call() throws Exception { return altaApiClient.purgeOrphanFiles(); }
                };
                task.setOnSucceeded(s -> { purgeOrphans.setDisable(false);
                        showInfo(t("settings.backup.purge.title"),
                                t("settings.backup.purge.done").replace("{n}", String.valueOf(task.getValue()))); });
                task.setOnFailed(s -> { purgeOrphans.setDisable(false);
                        showError(t("settings.backup.purge.title"),
                                task.getException() == null ? "" : task.getException().getMessage()); });
                start(task, "backup-purge-orphans");
            });
        });

        HBox row = new HBox(10, runNow, refresh, openFolder, purgeOrphans);
        row.setAlignment(Pos.CENTER_LEFT);

        load.run();

        VBox layout = new VBox(12, sectionTitle, hint, row, table);
        layout.getStyleClass().add("settings-tab-body");
        return layout;
    }

