    // ===================================================================
    //  L1 — Modulo Laboral: empleados + contratos
    // ===================================================================

    private final LaborApiClient laborApiClient = new LaborApiClient();
    private TableView<com.benjagest.ui.model.EmployeeEntry> employeesTable;
    private TableView<com.benjagest.ui.model.ContractEntry> contractsTable;

    /**
     * Modulo Personal unificado con 4 sub-tabs: Empleados, Contratos,
     * Fichajes, Nominas. Carga los datos comunes en paralelo y pinta
     * el TabPane.
     */
    /**
     * Muestra el módulo Contabilidad — delegado a {@link AccountingScreen}
     * para mantener este archivo gestionable. La pantalla incluye:
     * <ul>
     *   <li>Por validar — asientos auto-propuestos con badge confianza</li>
     *   <li>Diario — Libro Diario filtrable</li>
     *   <li>Asientos manuales — botón crear + editor con líneas editables</li>
     *   <li>Reglas aprendidas — listado del feedback contable</li>
     *   <li>Recurrentes — tareas cron contables</li>
     * </ul>
     */
    private void showAccountingModule() {
        com.benjagest.ui.screens.AccountingScreen screen =
                new com.benjagest.ui.screens.AccountingScreen(accountingApiClient, this::t);
        // El módulo es responsivo internamente con TabPane; no necesita
        // scroll externo (es preferible que cada tab maneje su propio
        // scroll en el contenido si lo necesita).
        setCenterAnimated((javafx.scene.Node) screen.buildView());
    }

    // Categoría + sub-pestaña activas de Labor (RR.HH.-CAT): se recuerdan para
    // que, tras cualquier acción que recargue el módulo (calcular nómina, marcar
    // pagada, borrar…), se vuelva a la misma sección en vez de saltar al inicio.
    private int laborCatIndex = 0;
    private int laborSubIndex = 0;

    /** RR.HH.-CAT — TabPane interno de una categoría con sus sub-pestañas. */
    private TabPane laborSubPane(Tab... leaves) {
        TabPane inner = new TabPane();
        inner.getStyleClass().add("settings-tabs");
        inner.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);
        inner.getTabs().addAll(leaves);
        VBox.setVgrow(inner, Priority.ALWAYS);
        return inner;
    }

    /** RR.HH.-CAT — Pestaña de categoría (nivel superior) que contiene un TabPane. */
    private Tab laborCategoryTab(String titleKey, String iconCode, TabPane inner) {
        Tab cat = new Tab(t(titleKey), inner);
        cat.setGraphic(icon(iconCode));
        cat.setClosable(false);
        return cat;
    }

    // BUG-NAV-1 — Refresco contextual de Labor. Las ~14 acciones de los
    // sub-tabs (calcular nómina, marcar pagada, borrar…) llaman a
    // laborRefresh.run() en vez de a showLaborModule() directamente:
    //   - Standalone (módulo del sidebar): apunta a showLaborModule(), que
    //     reemplaza el centro. Es lo correcto, no hay pestañas de ficha.
    //   - Embebido (Mi gestión / ficha de cliente): buildClientLaborTab()
    //     lo reapunta a recargar SU holder en su sitio, sin destruir la
    //     vista con pestañas. Mismo patrón que reloadRetaProfiles para RETA.
    private Runnable laborRefresh = this::showLaborModule;

    /**
     * REFRESH-AUDIT (2026-06-17) — Refresca Labor Y avisa a Contabilidad. Las
     * acciones de nómina que crean/revierten asientos (calcular, marcar pagada,
     * borrar, generar mes, finiquito/despido) tienen un EFECTO CROSS-MÓDULO: el
     * backend escribe en journal_entries vía PayslipJournalEntryService. Sin
     * emitir TOPIC_JOURNAL, la Contabilidad embebida en la ficha (suscrita a ese
     * topic) quedaba obsoleta hasta refrescar a mano (bug reportado por Benjamin).
     */
    private void refreshLaborAndJournal() {
        laborRefresh.run();
        com.benjagest.ui.support.RefreshBus.emit(
                com.benjagest.ui.support.RefreshBus.TOPIC_JOURNAL);
    }

    private void showLaborModule() {
        // Al entrar al módulo standalone, el refresco vuelve a ser standalone.
        laborRefresh = this::showLaborModule;
        Task<LaborBundle> task = new Task<>() {
            @Override
            protected LaborBundle call() throws Exception {
                var employees = laborApiClient.listEmployees(true);
                var contracts = laborApiClient.listContracts(null);
                int year = java.time.LocalDate.now().getYear();
                var payslips = laborApiClient.listPayslips(year, null, null);
                java.util.List<com.benjagest.ui.model.TimeClockEventTypeEntry> evTypes;
                try {
                    evTypes = laborApiClient.listTimeClockEventTypes(true);
                } catch (Exception ex) {
                    // Si el modulo timeclock no esta activo o el endpoint
                    // falla, dejamos lista vacia y la UI cae al hardcode.
                    evTypes = java.util.List.of();
                }
                return new LaborBundle(employees, contracts, payslips, evTypes, year);
            }
        };
        task.setOnSucceeded(ev -> setCenterAnimated(scroll(laborView(task.getValue()))));
        task.setOnFailed(ev -> setCenterAnimated(scroll(errorPanel(t("labor.load_failed")))));
        start(task, "labor-load");
    }

    private record LaborBundle(
            java.util.List<com.benjagest.ui.model.EmployeeEntry> employees,
            java.util.List<com.benjagest.ui.model.ContractEntry> contracts,
            java.util.List<com.benjagest.ui.model.PayslipEntry> payslips,
            java.util.List<com.benjagest.ui.model.TimeClockEventTypeEntry> eventTypes,
            int currentYear) {}

    private VBox laborView(LaborBundle bundle) {
        VBox content = content();
        Label title = new Label(t("labor.title"));
        title.getStyleClass().add("module-detail-title");
        Label subtitle = new Label(t("labor.subtitle"));
        subtitle.getStyleClass().add("module-detail-description");
        VBox titleBox = new VBox(4, title, subtitle);
        StackPane moduleIcon = iconBubble("fas-users", "module-title-icon");
        Region spacer = new Region();
        HBox.setHgrow(spacer, Priority.ALWAYS);

        HBox header = new HBox(16, titleBox, moduleIcon, spacer);
        header.setAlignment(Pos.CENTER_LEFT);
        header.getStyleClass().add("module-detail-header");

        // CTR-6 — banner de alertas activas: prueba próxima, fin de contrato
        // y cumpleaños del día. Si no hay alertas se oculta.
        Node alertsBanner = buildContractAlertsBanner();

        TabPane tabs = new TabPane();
        tabs.getStyleClass().add("settings-tabs");
        tabs.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);

        Tab empTab = new Tab(t("labor.tab.employees"), buildEmployeesTab(bundle.employees()));
        empTab.setGraphic(icon("fas-user"));
        Tab contractsTab = new Tab(t("labor.tab.contracts"), buildContractsGlobalTab(bundle));
        contractsTab.setGraphic(icon("fas-file-contract"));
        Tab clockTab = new Tab(t("labor.tab.timeclock"), buildTimeClockTab(bundle.employees(), bundle.eventTypes()));
        clockTab.setGraphic(icon("fas-clock"));
        Tab auditTab = new Tab(t("labor.tab.audit"), buildTimeClockAuditTab(bundle.employees()));
        auditTab.setGraphic(icon("fas-shield-alt"));
        Tab payslipsTab = new Tab(t("labor.tab.payslips"), buildPayslipsTab(bundle));
        payslipsTab.setGraphic(icon("fas-file-invoice-dollar"));
        // CTR-3 — Plantillas y anexos custom (gestión OWNER).
        Tab templatesTab = new Tab(t("labor.tab.templates"), buildContractTemplatesTab());
        templatesTab.setGraphic(icon("fas-clone"));
        Tab clausesTab = new Tab(t("labor.tab.clauses"), buildCustomClausesTab());
        clausesTab.setGraphic(icon("fas-paragraph"));
        Tab cfgTab = new Tab(t("labor.tab.cfg_timeclock"), buildEventTypeConfigTab(bundle.eventTypes()));
        cfgTab.setGraphic(icon("fas-cog"));
        // L3-4 — Calendario laboral (festivos nacionales + autonómicos
        // + locales). Carga lazy en buildWorkCalendarTab para no penalizar
        // la apertura de Labor en empresas sin calendario configurado.
        Tab calendarTab = new Tab(t("labor.tab.work_calendar"), buildWorkCalendarTab());
        calendarTab.setGraphic(icon("fas-calendar-day"));
        // Bajas (IT) — backend cerrado 2026-06-09, UI pendiente.
        Tab leavesTab = new Tab(t("labor.tab.medical_leaves"),
                buildMedicalLeavesTab(bundle.employees()));
        leavesTab.setGraphic(icon("fas-user-injured"));
        // Vacaciones (CV-VAC) — registro de días disfrutados por empleado.
        Tab vacationsTab = new Tab(t("labor.tab.vacations"),
                buildVacationsTab(bundle.employees()));
        vacationsTab.setGraphic(icon("fas-umbrella-beach"));
        // MEMP-4 — Solicitudes de ausencia pedidas por el empleado (PWA): aprobar/rechazar.
        Tab leaveReqTab = new Tab(t("labor.tab.leave_requests"),
                buildLeaveRequestsTab(bundle.employees()));
        leaveReqTab.setGraphic(icon("fas-inbox"));
        // Cotizaciones SS (TC1/RED) — backend cerrado 2026-06-09, UI
        // pendiente. Solo lectura por ahora — las cuotas se calculan
        // desde las nóminas; el editor manual queda para futuro.
        Tab ssTab = new Tab(t("labor.tab.ss_contributions"),
                buildSsContributionsTab(bundle.employees()));
        ssTab.setGraphic(icon("fas-percent"));
        // Reporte de coste de empresa por empleado (bloque NOM).
        Tab costTab = new Tab(t("labor.tab.employer_cost"), buildEmployerCostTab());
        costTab.setGraphic(icon("fas-coins"));
        // Tipos de cotización SS por año (PARAM-YEAR).
        Tab ratesTab = new Tab(t("labor.tab.ss_rates"), buildSsRatesTab());
        ratesTab.setGraphic(icon("fas-table"));
        // Bases de cotización por GRUPO (1-11) y año (V121, no-code).
        Tab groupBasesTab = new Tab(t("labor.tab.ss_group_bases"), buildSsGroupBasesTab());
        groupBasesTab.setGraphic(icon("fas-layer-group"));
        // Parámetros IRPF por año (escala).
        Tab irpfParamsTab = new Tab(t("labor.tab.irpf_params"), buildIrpfParamsTab());
        irpfParamsTab.setGraphic(icon("fas-percent"));
        // N3(b) — Topes de indemnización por despido y año (V127, no-code).
        Tab severanceTab = new Tab(t("labor.tab.severance"), buildSeveranceParamsTab());
        severanceTab.setGraphic(icon("fas-hand-holding-usd"));
        // RETA-0/RETA-3 — Tramos y Revisión viven ahora en la pestaña "Autónomos
        // (RETA)" de la ficha (consolidado 2026-06-15), NO aquí en Laboral.
        // PORT-2 (2026-06-10 tarde) — Partes/Jornadas como sub-pestaña
        // de Labor (no como módulo de raíz, decisión Benjamin). Lee de
        // /api/work-logs. Cuando llegue la versión tablet/móvil del
        // empleado, esta pestaña visualiza lo que reporta.
        Tab shiftsTab = new Tab(t("labor.tab.shifts"),
                buildShiftsTab(bundle.employees()));
        shiftsTab.setGraphic(icon("fas-business-time"));
        // Centros de trabajo (port CONTENDO centros_trabajo_180, V89).
        Tab centersTab = new Tab(t("labor.tab.work_centers"), buildWorkCentersTab());
        centersTab.setGraphic(icon("fas-map-marker-alt"));
        // FM — Kioscos/PDA de fichaje (alta + QR de activación + empleados).
        Tab kioskTab = new Tab(t("labor.tab.kiosk"), buildKioskDevicesTab(bundle.employees()));
        kioskTab.setGraphic(icon("fas-tablet-alt"));
        // JOR-2 — Planificacion de jornada (plantillas de horario).
        Tab scheduleTab = new Tab(t("labor.tab.schedule"), buildScheduleTemplatesTab(bundle.employees()));
        scheduleTab.setGraphic(icon("fas-calendar-week"));

        // RR.HH.-CAT (2026-06-17) — Los 19 sub-tabs se agrupan en 5 categorías
        // (pestañas anidadas) para no tener una fila ilegible: operativa diaria
        // separada de las tablas de parámetros legales (set-and-forget).
        TabPane personalPane = laborSubPane(empTab, contractsTab, templatesTab, clausesTab);
        TabPane payrollPane = laborSubPane(payslipsTab, costTab, ssTab);
        TabPane timePane = laborSubPane(clockTab, auditTab, shiftsTab, scheduleTab, calendarTab, centersTab, kioskTab, cfgTab);
        TabPane absencePane = laborSubPane(leaveReqTab, leavesTab, vacationsTab);
        TabPane paramsPane = laborSubPane(ratesTab, groupBasesTab, irpfParamsTab, severanceTab);
        final TabPane[] panes = {personalPane, payrollPane, timePane, absencePane, paramsPane};

        tabs.getTabs().addAll(
                laborCategoryTab("labor.cat.personal", "fas-users", personalPane),
                laborCategoryTab("labor.cat.payroll", "fas-file-invoice-dollar", payrollPane),
                laborCategoryTab("labor.cat.time", "fas-clock", timePane),
                laborCategoryTab("labor.cat.absences", "fas-user-injured", absencePane),
                laborCategoryTab("labor.cat.params", "fas-sliders-h", paramsPane));
        VBox.setVgrow(tabs, Priority.ALWAYS);

        // Restaurar categoría + sub-pestaña activas (no perder contexto al
        // recargar tras una acción). laborCatIndex/laborSubIndex se recuerdan.
        if (laborCatIndex < 0 || laborCatIndex >= panes.length) laborCatIndex = 0;
        tabs.getSelectionModel().select(laborCatIndex);
        TabPane activePane = panes[laborCatIndex];
        if (laborSubIndex >= 0 && laborSubIndex < activePane.getTabs().size()) {
            activePane.getSelectionModel().select(laborSubIndex);
        }
        tabs.getSelectionModel().selectedIndexProperty().addListener((o, ov, nv) -> {
            laborCatIndex = nv.intValue();
            laborSubIndex = (laborCatIndex >= 0 && laborCatIndex < panes.length)
                    ? panes[laborCatIndex].getSelectionModel().getSelectedIndex() : 0;
        });
        for (TabPane p : panes) {
            p.getSelectionModel().selectedIndexProperty().addListener((o, ov, nv) -> {
                if (laborCatIndex >= 0 && laborCatIndex < panes.length && panes[laborCatIndex] == p) {
                    laborSubIndex = nv.intValue();
                }
            });
        }

        content.getChildren().addAll(header, alertsBanner, tabs);
        return content;
    }

    /**
     * CTR-6 — Banner colapsable con las alertas pendientes del tenant
     * (prueba próxima, contratos a 30/60d, cumpleaños). El asesor puede
     * descartar cada una. Se carga en hilo de fondo; si falla, el banner
     * queda vacío (no rompe el módulo).
     */
    private Node buildContractAlertsBanner() {
        VBox box = new VBox(6);
        box.setPadding(new Insets(6, 0, 6, 0));
        box.setManaged(false);
        box.setVisible(false);

        Task<java.util.List<com.benjagest.ui.model.ContractAlert>> task = new Task<>() {
            @Override protected java.util.List<com.benjagest.ui.model.ContractAlert> call() throws Exception {
                return altaApiClient.listContractAlerts();
            }
        };
        task.setOnSucceeded(ev -> {
            var alerts = task.getValue();
            if (alerts == null || alerts.isEmpty()) return;
            Label hdr = new Label(t("labor.alerts.title") + " (" + alerts.size() + ")");
            hdr.getStyleClass().add("settings-section-title");
            box.getChildren().add(hdr);
            for (var alert : alerts) {
                box.getChildren().add(renderAlertRow(alert, box));
            }
            box.setManaged(true);
            box.setVisible(true);
        });
        // No mostrar error si falla — banner opcional.
        start(task, "contract-alerts");
        return box;
    }

    private Node renderAlertRow(com.benjagest.ui.model.ContractAlert a, VBox container) {
        HBox row = new HBox(8);
        row.setAlignment(Pos.CENTER_LEFT);
        row.setPadding(new Insets(6, 8, 6, 8));
        String style = switch (a.severity() == null ? "INFO" : a.severity()) {
            case "CRITICAL" -> "-fx-background-color: #fff1f0; -fx-border-color: #ffa39e; -fx-border-radius: 6; -fx-background-radius: 6;";
            case "WARNING" -> "-fx-background-color: #fffbe6; -fx-border-color: #ffe58f; -fx-border-radius: 6; -fx-background-radius: 6;";
            default -> "-fx-background-color: #f0f7ff; -fx-border-color: #91d5ff; -fx-border-radius: 6; -fx-background-radius: 6;";
        };
        row.setStyle(style);

        Label icon = new Label("BIRTHDAY".equals(a.kind()) ? "🎂"
                : "PROBATION_ENDING".equals(a.kind()) ? "⏳"
                : "⚠");
        Label title = new Label(a.title());
        title.getStyleClass().add("settings-section-title");
        Label sub = new Label(a.message() + (a.firesAt() == null ? "" : " — " + a.firesAt()));
        sub.setWrapText(true);
        VBox text = new VBox(2, title, sub);
        HBox.setHgrow(text, Priority.ALWAYS);

        Button dismiss = new Button(t("labor.alerts.dismiss"));
        dismiss.setOnAction(ev -> {
            Task<Void> t = new Task<>() {
                @Override protected Void call() throws Exception {
                    altaApiClient.dismissContractAlert(a.id());
                    return null;
                }
            };
            t.setOnSucceeded(e2 -> container.getChildren().remove(row));
            start(t, "alert-dismiss");
        });

        row.getChildren().addAll(icon, text, dismiss);
        return row;
    }

    // ===================================================================
    //  CTR-3 — Sub-tab "Plantillas" del módulo Laboral
    // ===================================================================

    /**
     * Listado simple de plantillas de contrato del tenant. El OWNER
     * crea/edita/elimina; al lanzar un nuevo contrato desde el wizard
     * puede "Cargar plantilla" para pre-rellenar el state.
     */
    private Node buildContractTemplatesTab() {
        TableView<com.benjagest.ui.model.ContractTemplate> table = new TableView<>();
        table.getStyleClass().add("data-table");
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPlaceholder(new Label(t("labor.templates.empty")));

        TableColumn<com.benjagest.ui.model.ContractTemplate, String> colName =
                new TableColumn<>(t("labor.templates.col.name"));
        colName.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().name()));
        colName.setPrefWidth(200);
        TableColumn<com.benjagest.ui.model.ContractTemplate, String> colSepe =
                new TableColumn<>(t("labor.templates.col.sepe"));
        colSepe.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().sepeContractCode() == null ? "—" : c.getValue().sepeContractCode()));
        colSepe.setPrefWidth(80);
        TableColumn<com.benjagest.ui.model.ContractTemplate, String> colSalary =
                new TableColumn<>(t("labor.templates.col.salary"));
        colSalary.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().grossSalary() == null ? "" : c.getValue().grossSalary().toPlainString() + " €"));
        colSalary.setComparator(NUMERIC_STRING_COMPARATOR);  // VG-FULL-SCAN
        colSalary.setPrefWidth(110);
        TableColumn<com.benjagest.ui.model.ContractTemplate, String> colDescr =
                new TableColumn<>(t("labor.templates.col.descr"));
        colDescr.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().description() == null ? "" : c.getValue().description()));
        table.getColumns().addAll(java.util.List.of(colName, colSepe, colSalary, colDescr));

        Runnable refresh = () -> {
            Task<java.util.List<com.benjagest.ui.model.ContractTemplate>> task = new Task<>() {
                @Override protected java.util.List<com.benjagest.ui.model.ContractTemplate> call() throws Exception {
                    return altaApiClient.listContractTemplates();
                }
            };
            task.setOnSucceeded(ev -> table.setItems(FXCollections.observableArrayList(task.getValue())));
            task.setOnFailed(ev -> showError(t("labor.templates.fail"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "templates-load");
        };
        refresh.run();

        Button newBtn = new Button(t("labor.templates.action.new"));
        newBtn.setGraphic(icon("fas-plus"));
        newBtn.setOnAction(ev -> showContractTemplateEditor(null, refresh));

        Button editBtn = new Button(t("labor.templates.action.edit"));
        editBtn.setGraphic(icon("fas-edit"));
        editBtn.setDisable(true);
        editBtn.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel != null) showContractTemplateEditor(sel, refresh);
        });

        Button delBtn = new Button(t("labor.templates.action.delete"));
        delBtn.setGraphic(icon("fas-trash"));
        delBtn.setDisable(true);
        delBtn.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            Alert confirm = new Alert(Alert.AlertType.CONFIRMATION,
                    t("labor.templates.confirm.delete"), ButtonType.OK, ButtonType.CANCEL);
            confirm.showAndWait().ifPresent(bt -> {
                if (bt != ButtonType.OK) return;
                Task<Void> task = new Task<>() {
                    @Override protected Void call() throws Exception {
                        altaApiClient.deleteContractTemplate(sel.id());
                        return null;
                    }
                };
                task.setOnSucceeded(ev2 -> refresh.run());
                task.setOnFailed(ev2 -> showError(t("labor.templates.fail"),
                        task.getException() == null ? "" : task.getException().getMessage()));
                start(task, "template-delete");
            });
        });

        table.getSelectionModel().selectedItemProperty().addListener((o, ov, nv) -> {
            editBtn.setDisable(nv == null);
            delBtn.setDisable(nv == null);
        });

        Label hint = new Label(t("labor.templates.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        HBox actions = new HBox(8, newBtn, editBtn, delBtn);
        VBox body = new VBox(10, hint, actions, table); // acciones arriba (no debajo)
        VBox.setVgrow(table, Priority.ALWAYS);
        body.setPadding(new Insets(12));
        return body;
    }

    /**
     * Editor de plantilla — combos cargados del catálogo (igual que el wizard),
     * no TextField libres. El campo "SEPE" es ComboBox editable: puedes elegir
     * de la lista oficial o escribir un código a mano si la asesoría usa uno
     * legacy/raro. El "Modelo PDF" se humaniza ES/EN en el desplegable.
     */
    private void showContractTemplateEditor(com.benjagest.ui.model.ContractTemplate existing, Runnable onSaved) {
        Dialog<ButtonType> dialog = new Dialog<>();
        dialog.setTitle(existing == null ? t("labor.templates.title.new") : t("labor.templates.title.edit"));
        ButtonType saveBt = new ButtonType(
                existing == null ? t("labor.templates.action.new") : t("labor.editor.save"),
                ButtonBar.ButtonData.OK_DONE);
        dialog.getDialogPane().getButtonTypes().addAll(saveBt, ButtonType.CANCEL);

        TextField nameF = new TextField(existing == null ? "" : existing.name());
        TextField descrF = new TextField(existing == null ? "" : existing.description());

        // Combo SEPE editable — carga el catálogo en background y permite
        // también escribir libre por si la asesoría tiene un código legacy
        // no listado. El converter pinta "100 — Indefinido…" y devuelve el
        // código limpio.
        ComboBox<com.benjagest.ui.model.ContractCatalog.SepeType> sepeCombo = new ComboBox<>();
        sepeCombo.setEditable(true);
        sepeCombo.setMaxWidth(Double.MAX_VALUE);
        sepeCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(com.benjagest.ui.model.ContractCatalog.SepeType s) {
                return s == null ? "" : s.label();
            }
            @Override public com.benjagest.ui.model.ContractCatalog.SepeType fromString(String s) {
                if (s == null || s.isBlank()) return null;
                String code = s.contains(" ") ? s.substring(0, s.indexOf(' ')).trim() : s.trim();
                return sepeCombo.getItems().stream()
                        .filter(it -> code.equals(it.code()))
                        .findFirst().orElse(null);
            }
        });
        Task<java.util.List<com.benjagest.ui.model.ContractCatalog.SepeType>> sepeTask = new Task<>() {
            @Override protected java.util.List<com.benjagest.ui.model.ContractCatalog.SepeType> call() throws Exception {
                return altaApiClient.listSepeContractTypes();
            }
        };
        sepeTask.setOnSucceeded(ev -> {
            sepeCombo.getItems().setAll(sepeTask.getValue());
            if (existing != null && existing.sepeContractCode() != null) {
                sepeCombo.getItems().stream()
                        .filter(it -> existing.sepeContractCode().equals(it.code()))
                        .findFirst().ifPresent(sepeCombo.getSelectionModel()::select);
            }
        });
        start(sepeTask, "tpl-sepe-load");

        TextField hoursF = new TextField(existing == null || existing.weeklyHours() == null
                ? "40" : existing.weeklyHours().toPlainString());
        TextField salaryF = new TextField(existing == null || existing.grossSalary() == null
                ? "" : existing.grossSalary().toPlainString());
        TextField bonusF = new TextField(existing == null || existing.annualBonuses() == null
                ? "2" : existing.annualBonuses().toString());
        TextField vacF = new TextField(existing == null || existing.vacationDays() == null
                ? "30" : existing.vacationDays().toString());
        TextField probF = new TextField(existing == null || existing.probationDays() == null
                ? "" : existing.probationDays().toString());

        // Combo modelo PDF humanizado (no códigos crudos)
        ComboBox<String> pdfM = new ComboBox<>();
        pdfM.getItems().addAll("UNIFIED_2022", "BY_CODE");
        pdfM.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String c) {
                return c == null ? "" : humanizeFromKey("labor.contract.wizard.step4.pdf_model." + c, c);
            }
            @Override public String fromString(String s) { return null; }
        });
        pdfM.setValue(existing == null ? "UNIFIED_2022" :
                (existing.pdfModel() == null ? "UNIFIED_2022" : existing.pdfModel()));

        GridPane g = new GridPane();
        g.setHgap(10); g.setVgap(8); g.setPadding(new Insets(10));
        int row = 0;
        g.add(new Label(t("labor.templates.field.name")), 0, row); g.add(nameF, 1, row, 3, 1); row++;
        g.add(new Label(t("labor.templates.field.descr")), 0, row); g.add(descrF, 1, row, 3, 1); row++;
        g.add(new Label(t("labor.templates.field.sepe")), 0, row); g.add(sepeCombo, 1, row, 3, 1); row++;
        g.add(new Label(t("labor.templates.field.pdf")), 0, row); g.add(pdfM, 1, row, 3, 1); row++;
        g.add(new Label(t("labor.templates.field.hours")), 0, row); g.add(hoursF, 1, row);
        g.add(new Label(t("labor.templates.field.salary")), 2, row); g.add(salaryF, 3, row); row++;
        g.add(new Label(t("labor.templates.field.bonus")), 0, row); g.add(bonusF, 1, row);
        g.add(new Label(t("labor.templates.field.vac")), 2, row); g.add(vacF, 3, row); row++;
        g.add(new Label(t("labor.templates.field.probation")), 0, row); g.add(probF, 1, row);

        installDialog(dialog, g);
        dialog.showAndWait().ifPresent(bt -> {
            if (bt != saveBt) return;
            if (nameF.getText() == null || nameF.getText().isBlank()) {
                showError(t("labor.templates.fail"), t("labor.templates.fail.name"));
                return;
            }
            // Si el SEPE viene del combo, sacamos su .code(); si el usuario
            // escribió a mano, lo tomamos del editor del combo.
            String sepeCode = null;
            var selSepe = sepeCombo.getSelectionModel().getSelectedItem();
            if (selSepe != null) sepeCode = selSepe.code();
            else if (sepeCombo.getEditor().getText() != null && !sepeCombo.getEditor().getText().isBlank()) {
                String txt = sepeCombo.getEditor().getText().trim();
                sepeCode = txt.contains(" ") ? txt.substring(0, txt.indexOf(' ')) : txt;
            }
            com.benjagest.ui.model.ContractTemplate tpl = new com.benjagest.ui.model.ContractTemplate(
                    existing == null ? null : existing.id(),
                    nameF.getText().trim(),
                    blankToNullOrSelf(descrF.getText()),
                    sepeCode,
                    null, null, null, null,
                    parseDecSafe(hoursF.getText()),
                    parseDecSafe(salaryF.getText()),
                    parseIntSafe(bonusF.getText()),
                    parseIntSafe(vacF.getText()),
                    null,
                    parseIntSafe(probF.getText()),
                    null, null,
                    pdfM.getValue(),
                    false, true);
            Task<Void> task = new Task<>() {
                @Override protected Void call() throws Exception {
                    if (existing == null) altaApiClient.createContractTemplate(tpl);
                    // Update no implementado en altaApiClient v1 — borrar+crear
                    // sería violento (cambia id). Backend tiene endpoint
                    // PUT pero el wrapper UI no lo expone. Sub-slice si hace
                    // falta; por ahora editar = crear nuevo.
                    else { altaApiClient.deleteContractTemplate(existing.id()); altaApiClient.createContractTemplate(tpl); }
                    return null;
                }
            };
            task.setOnSucceeded(ev -> onSaved.run());
            task.setOnFailed(ev -> showError(t("labor.templates.fail"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "template-save");
        });
    }

    // ===================================================================
    //  CTR-7 — Sub-tab "Cláusulas custom" del módulo Laboral
    // ===================================================================

    /**
     * Listado de cláusulas/anexos custom de la asesoría. Las built-in
     * salen pero marcadas y no son editables. Cuando llamamos al
     * endpoint /clauses, el backend ya filtra built-in + custom del
     * tenant; aquí solo distinguimos visualmente.
     */
    private Node buildCustomClausesTab() {
        TableView<com.benjagest.ui.model.ContractCatalog.ClauseTemplate> table = new TableView<>();
        table.getStyleClass().add("data-table");
        table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        table.setPlaceholder(new Label(t("labor.clauses.empty")));

        TableColumn<com.benjagest.ui.model.ContractCatalog.ClauseTemplate, String> colTitle =
                new TableColumn<>(t("labor.clauses.col.title"));
        colTitle.setCellValueFactory(c -> new SimpleStringProperty(c.getValue().title()));
        colTitle.setPrefWidth(280);
        TableColumn<com.benjagest.ui.model.ContractCatalog.ClauseTemplate, String> colCat =
                new TableColumn<>(t("labor.clauses.col.category"));
        colCat.setCellValueFactory(c -> new SimpleStringProperty(
                humanizeFromKey("labor.clauses.cat." + c.getValue().category(), c.getValue().category())));
        colCat.setPrefWidth(160);
        TableColumn<com.benjagest.ui.model.ContractCatalog.ClauseTemplate, String> colOrigin =
                new TableColumn<>(t("labor.clauses.col.origin"));
        colOrigin.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().isBuiltIn() ? t("labor.clauses.origin.builtin")
                                          : t("labor.clauses.origin.custom")));
        colOrigin.setPrefWidth(110);
        table.getColumns().addAll(java.util.List.of(colTitle, colCat, colOrigin));

        Runnable refresh = () -> {
            Task<java.util.List<com.benjagest.ui.model.ContractCatalog.ClauseTemplate>> task = new Task<>() {
                @Override protected java.util.List<com.benjagest.ui.model.ContractCatalog.ClauseTemplate> call() throws Exception {
                    return altaApiClient.listClauseTemplates();
                }
            };
            task.setOnSucceeded(ev -> table.setItems(FXCollections.observableArrayList(task.getValue())));
            task.setOnFailed(ev -> showError(t("labor.clauses.fail"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "clauses-load");
        };
        refresh.run();

        Button newBtn = new Button(t("labor.clauses.action.new"));
        newBtn.setGraphic(icon("fas-plus"));
        newBtn.setOnAction(ev -> showCustomClauseEditor(null, refresh));

        Button editBtn = new Button(t("labor.clauses.action.edit"));
        editBtn.setGraphic(icon("fas-edit"));
        editBtn.setDisable(true);
        editBtn.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            if (sel.isBuiltIn()) {
                showError(t("labor.clauses.fail"), t("labor.clauses.fail.builtin"));
                return;
            }
            showCustomClauseEditor(sel, refresh);
        });

        Button viewBtn = new Button(t("labor.clauses.action.view"));
        viewBtn.setGraphic(icon("fas-eye"));
        viewBtn.setDisable(true);
        viewBtn.setOnAction(ev -> {
            var sel = table.getSelectionModel().getSelectedItem();
            if (sel == null) return;
            Alert info = new Alert(Alert.AlertType.INFORMATION);
            info.setTitle(sel.title());
            info.setHeaderText(sel.title()
                    + (sel.legalBasis() == null ? "" : "\n" + sel.legalBasis()));
            TextArea ta = new TextArea(sel.body());
            ta.setWrapText(true);
            ta.setEditable(false);
            ta.setPrefRowCount(20); ta.setPrefColumnCount(80);
            info.getDialogPane().setContent(ta);
            info.setResizable(true);
            info.showAndWait();
        });

        table.getSelectionModel().selectedItemProperty().addListener((o, ov, nv) -> {
            editBtn.setDisable(nv == null);
            viewBtn.setDisable(nv == null);
        });

        Label hint = new Label(t("labor.clauses.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        HBox actions = new HBox(8, newBtn, editBtn, viewBtn);
        VBox body = new VBox(10, hint, actions, table); // acciones arriba (no debajo)
        VBox.setVgrow(table, Priority.ALWAYS);
        body.setPadding(new Insets(12));
        return body;
    }

    /** Editor de cláusula custom (POST/PUT /api/contracts/catalog/clauses). */
    private void showCustomClauseEditor(com.benjagest.ui.model.ContractCatalog.ClauseTemplate existing,
                                         Runnable onSaved) {
        Dialog<ButtonType> dialog = new Dialog<>();
        dialog.setTitle(existing == null ? t("labor.clauses.title.new") : t("labor.clauses.title.edit"));
        ButtonType saveBt = new ButtonType(t("labor.editor.save"), ButtonBar.ButtonData.OK_DONE);
        dialog.getDialogPane().getButtonTypes().addAll(saveBt, ButtonType.CANCEL);

        TextField codeF = new TextField(existing == null ? "" : existing.code());
        TextField titleF = new TextField(existing == null ? "" : existing.title());
        ComboBox<String> catC = new ComboBox<>();
        catC.getItems().addAll("CONFIDENTIALITY", "NON_COMPETE", "EXCLUSIVITY",
                "RETENTION_TRAINING", "GEOLOCATION_GDPR", "TELEWORK",
                "INTELLECTUAL_PROPERTY", "OBJECTIVES_BONUS", "COMPANY_CAR",
                "COMPANY_PHONE", "EXPENSE_ALLOWANCE", "WORKING_HOURS_FLEX",
                "CUSTOM", "OTHER");
        catC.setValue(existing == null ? "CUSTOM" : existing.category());
        TextField legalF = new TextField(existing == null ? "" : existing.legalBasis());
        TextArea bodyF = new TextArea(existing == null ? "" : existing.body());
        bodyF.setWrapText(true);
        bodyF.setPrefRowCount(15);

        GridPane g = new GridPane();
        g.setHgap(10); g.setVgap(8); g.setPadding(new Insets(10));
        int row = 0;
        g.add(new Label(t("labor.clauses.field.code")), 0, row); g.add(codeF, 1, row);
        g.add(new Label(t("labor.clauses.field.category")), 2, row); g.add(catC, 3, row); row++;
        g.add(new Label(t("labor.clauses.field.title")), 0, row); g.add(titleF, 1, row, 3, 1); row++;
        g.add(new Label(t("labor.clauses.field.legal")), 0, row); g.add(legalF, 1, row, 3, 1); row++;
        g.add(new Label(t("labor.clauses.field.body")), 0, row); g.add(bodyF, 1, row, 3, 1);
        GridPane.setVgrow(bodyF, Priority.ALWAYS);

        installDialog(dialog, g);
        dialog.setResizable(true);
        dialog.showAndWait().ifPresent(bt -> {
            if (bt != saveBt) return;
            Task<Void> task = new Task<>() {
                @Override protected Void call() throws Exception {
                    // Backend expone POST + PUT en ContractCatalogController.
                    // El wrapper de UI no tiene helpers todavía — usamos
                    // HttpClient inline aquí para no inflar AltaApiClient
                    // antes de tiempo.
                    String json = "{\"code\":\"" + js(codeF.getText())
                            + "\",\"title\":\"" + js(titleF.getText())
                            + "\",\"category\":\"" + js(catC.getValue())
                            + "\",\"legalBasis\":\"" + js(legalF.getText())
                            + "\",\"body\":\"" + js(bodyF.getText()) + "\"}";
                    altaApiClient.upsertClauseTemplate(existing == null ? null : existing.id(), json);
                    return null;
                }
            };
            task.setOnSucceeded(ev -> onSaved.run());
            task.setOnFailed(ev -> showError(t("labor.clauses.fail"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "clause-save");
        });
    }

    private static String js(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"")
                .replace("\n", "\\n").replace("\r", "");
    }

    // ----- Sub-tab Empleados -----

    /**
     * CV-ORQ — Dar de baja / despedir a un empleado. El asesor solo indica la
     * fecha de cese y el motivo; el programa calcula el finiquito (última
     * nómina + vacaciones pendientes + prorrata de extras) y la indemnización
     * según el tipo, y al confirmar cierra el contrato.
     */
    private void showTerminationDialog(com.benjagest.ui.model.EmployeeEntry employee) {
        Dialog<ButtonType> d = new Dialog<>();
        d.setTitle(t("labor.term.title") + " — " + employee.fullName());
        ButtonType confirmBt = new ButtonType(t("labor.term.confirm"), ButtonBar.ButtonData.OK_DONE);
        d.getDialogPane().getButtonTypes().addAll(confirmBt, ButtonType.CANCEL);

        DatePicker ceseDate = new DatePicker(java.time.LocalDate.now());
        ComboBox<String> typeCombo = new ComboBox<>();
        typeCombo.getItems().addAll("VOLUNTARY", "END_OF_CONTRACT", "DISMISSAL_OBJECTIVE",
                "DISMISSAL_UNFAIR", "DISMISSAL_DISCIPLINARY", "RETIREMENT");
        typeCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String s) { return s == null ? "" : t("labor.term.type." + s); }
            @Override public String fromString(String s) { return null; }
        });
        typeCombo.getSelectionModel().select("DISMISSAL_OBJECTIVE");
        ComboBox<String> accrualCombo = new ComboBox<>();
        accrualCombo.getItems().addAll("SEMIANNUAL", "ANNUAL");
        accrualCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String s) {
                return "ANNUAL".equals(s) ? t("labor.settlement.accrual.annual") : t("labor.settlement.accrual.semi");
            }
            @Override public String fromString(String s) { return null; }
        });
        accrualCombo.getSelectionModel().select("SEMIANNUAL");
        TextField otherField = new TextField();
        otherField.setPromptText(t("labor.payslips.calc.other_deductions.prompt"));
        TextArea notesArea = new TextArea(); notesArea.setPrefRowCount(2);

        Label summary = new Label(t("labor.term.preview.empty"));
        summary.getStyleClass().add("settings-hint");
        summary.setWrapText(true);
        Button previewBtn = new Button(t("labor.payslips.calc.preview_btn"));
        previewBtn.getStyleClass().add("button-secondary");
        Runnable doPreview = () -> {
            java.time.LocalDate ce = ceseDate.getValue();
            if (ce == null || typeCombo.getValue() == null) return;
            Task<com.benjagest.ui.model.TerminationPreviewEntry> tk = new Task<>() {
                @Override protected com.benjagest.ui.model.TerminationPreviewEntry call() throws Exception {
                    return laborApiClient.previewTermination(employee.id(), ce, typeCombo.getValue(),
                            accrualCombo.getValue(), parseDecSafe(otherField.getText()),
                            blankToNullOrSelf(notesArea.getText()));
                }
            };
            tk.setOnSucceeded(ev -> {
                var p = tk.getValue();
                summary.setText(t("labor.term.preview.text")
                        .replace("{gross}", money(p.settlementGross()))
                        .replace("{ss}", money(p.settlementSs()))
                        .replace("{irpf}", money(p.settlementIrpf()))
                        .replace("{net}", money(p.settlementNet()))
                        .replace("{years}", formatAntiquity(p.antiqYears(), p.antiqMonths(), p.antiqDays()))
                        .replace("{sevdays}", p.sevDays() == null ? "0" : p.sevDays().toPlainString())
                        .replace("{sev}", money(p.sevGross()))
                        .replace("{sevexempt}", money(p.sevExempt()))
                        .replace("{sevtax}", money(p.sevTaxable())));
            });
            tk.setOnFailed(ev -> {
                Throwable ex = tk.getException();
                String dd = ex == null ? null : humanizeBackendError(ex.getMessage());
                summary.setText(dd == null || dd.isBlank() ? t("labor.payslips.calc.fail.body") : dd);
            });
            start(tk, "term-preview");
        };
        previewBtn.setOnAction(e -> doPreview.run());
        ceseDate.valueProperty().addListener((o, ov, nv) -> doPreview.run());
        typeCombo.valueProperty().addListener((o, ov, nv) -> doPreview.run());
        accrualCombo.valueProperty().addListener((o, ov, nv) -> doPreview.run());

        GridPane g = new GridPane();
        g.setHgap(10); g.setVgap(8); g.setPadding(new Insets(10));
        int r = 0;
        g.add(new Label(t("labor.settlement.cese_date")), 0, r); g.add(ceseDate, 1, r++);
        g.add(new Label(t("labor.term.reason")), 0, r); g.add(typeCombo, 1, r++);
        g.add(new Label(t("labor.settlement.accrual")), 0, r); g.add(accrualCombo, 1, r++);
        g.add(new Label(t("labor.payslips.calc.other_deductions")), 0, r); g.add(otherField, 1, r++);
        g.add(new Label(t("labor.payslips.calc.notes")), 0, r); g.add(notesArea, 1, r++);

        Label hint = new Label(t("labor.term.hint"));
        hint.getStyleClass().add("settings-hint"); hint.setWrapText(true);
        VBox box = new VBox(10, hint, g, new Separator(), new HBox(8, previewBtn), summary);
        installDialog(d, box);
        javafx.application.Platform.runLater(doPreview);
        d.showAndWait().ifPresent(bt -> {
            if (bt != confirmBt) return;
            java.time.LocalDate ce = ceseDate.getValue();
            if (ce == null || typeCombo.getValue() == null) {
                showError(t("labor.term.title"), t("labor.term.reason")); return;
            }
            Alert c = new Alert(Alert.AlertType.CONFIRMATION,
                    t("labor.term.confirm_body").replace("{name}", employee.fullName())
                            .replace("{date}", ce.toString()),
                    ButtonType.OK, ButtonType.CANCEL);
            c.setHeaderText(t("labor.term.confirm"));
            c.showAndWait().ifPresent(bt2 -> {
                if (bt2 != ButtonType.OK) return;
                Task<Void> tk = new Task<>() {
                    @Override protected Void call() throws Exception {
                        laborApiClient.executeTermination(employee.id(), ce, typeCombo.getValue(),
                                accrualCombo.getValue(), parseDecSafe(otherField.getText()),
                                blankToNullOrSelf(notesArea.getText()));
                        return null;
                    }
                };
                tk.setOnSucceeded(ev -> {
                    // El finiquito crea asiento (SETTLEMENT) y cierra el contrato:
                    // refresca Labor + Contabilidad antes de los documentos de baja.
                    refreshLaborAndJournal();
                    showTerminationDocsDialog(employee, ce, typeCombo.getValue());
                });
                tk.setOnFailed(ev -> showError(t("labor.term.title"),
                        humanizeBackendError(tk.getException() == null ? "" : tk.getException().getMessage())));
                start(tk, "term-execute");
            });
        });
    }

    /** Antigüedad legible: "X años, Y meses y Z días" (omite las partes a 0). */
    private String formatAntiquity(int y, int m, int dd) {
        java.util.List<String> parts = new java.util.ArrayList<>();
        if (y > 0) parts.add(y + (y == 1 ? " año" : " años"));
        if (m > 0) parts.add(m + (m == 1 ? " mes" : " meses"));
        if (dd > 0) parts.add(dd + (dd == 1 ? " día" : " días"));
        if (parts.isEmpty()) return "0 días";
        if (parts.size() == 1) return parts.get(0);
        return String.join(", ", parts.subList(0, parts.size() - 1)) + " y " + parts.get(parts.size() - 1);
    }

    /** Tras una baja, ofrece descargar la carta de despido y el certificado de
     *  empresa. Al cerrar, recarga el módulo. */
    private void showTerminationDocsDialog(com.benjagest.ui.model.EmployeeEntry employee,
                                            java.time.LocalDate ceseDate, String type) {
        Dialog<ButtonType> d = new Dialog<>();
        d.setTitle(t("labor.term.docs.title"));
        d.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);
        String safeName = employee.fullName() == null ? employee.id() : employee.fullName().replace(" ", "_");
        // Recibo de finiquito — el documento legal que firma el trabajador.
        Button receipt = new Button(t("labor.term.docs.receipt"));
        receipt.setGraphic(icon("fas-file-signature"));
        receipt.getStyleClass().add("button-primary");
        receipt.setOnAction(e -> downloadTermDoc("settlement-receipt", employee.id(), ceseDate, type,
                "recibo-finiquito-" + safeName + ".pdf"));
        Button letter = new Button(t("labor.term.docs.letter"));
        letter.setGraphic(icon("fas-file-pdf"));
        letter.setOnAction(e -> downloadTermDoc("dismissal-letter", employee.id(), ceseDate, type,
                "carta-despido-" + safeName + ".pdf"));
        Button cert = new Button(t("labor.term.docs.cert"));
        cert.setGraphic(icon("fas-file-pdf"));
        cert.setOnAction(e -> downloadTermDoc("company-certificate", employee.id(), ceseDate, type,
                "certificado-empresa-" + safeName + ".pdf"));
        Label hint = new Label(t("labor.term.docs.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");
        VBox box = new VBox(12, hint, new HBox(8, receipt, letter, cert));
        box.setPadding(new Insets(12));
        installDialog(d, box);
        d.showAndWait();
        laborRefresh.run();
    }

    private void downloadTermDoc(String which, String employeeId, java.time.LocalDate date,
                                  String type, String filename) {
        Task<byte[]> tk = new Task<>() {
            @Override protected byte[] call() throws Exception {
                return laborApiClient.downloadTerminationDoc(which, employeeId, date, type);
            }
        };
        tk.setOnSucceeded(ev -> savePdfBytes(tk.getValue(), filename));
        tk.setOnFailed(ev -> showError(t("labor.term.docs.title"),
                humanizeBackendError(tk.getException() == null ? "" : tk.getException().getMessage())));
        start(tk, "term-doc");
    }

    /** Guarda unos bytes PDF en un fichero elegido por el usuario y lo abre. */
    private void savePdfBytes(byte[] bytes, String filename) {
        javafx.stage.FileChooser fc = new javafx.stage.FileChooser();
        fc.setInitialFileName(filename);
        fc.getExtensionFilters().add(new javafx.stage.FileChooser.ExtensionFilter("PDF", "*.pdf"));
        java.io.File f = fc.showSaveDialog(root.getScene().getWindow());
        if (f == null) return;
        try {
            java.nio.file.Files.write(f.toPath(), bytes);
            if (java.awt.Desktop.isDesktopSupported()) {
                try { java.awt.Desktop.getDesktop().open(f); } catch (Exception ignored) {}
            }
        } catch (java.io.IOException ex) {
            showError(t("labor.payslips.pdf.fail.title"), ex.getMessage());
        }
    }

