        ownDis.getSelectionModel().select(m.ownDisability() == null || m.ownDisability().isBlank() ? "NONE" : m.ownDisability());
        CheckBox mobility = new CheckBox(t("labor.irpf.mobility")); mobility.setSelected(m.ownMobility());
