    private void openCustomerDetailDialog(com.benjagest.ui.model.CustomerExtendedEntry c) {
        openCustomerDetailDialog(c, false, null);
    }

    /**
     * TPB-CLIENT-SETUP F1 — Abre la ficha vacia para dar de alta un
     * cliente-receptor nuevo bajo el tenant actual. onSaved se ejecuta
     * tras crear (p.ej. recargar el combo del editor de factura).
     */
    private void openNewCustomerDialog(Runnable onSaved) {
        com.benjagest.ui.model.CustomerExtendedEntry empty =
                new com.benjagest.ui.model.CustomerExtendedEntry(
                        null, "", "", "", "COMPANY", "", "", "",
                        java.math.BigDecimal.valueOf(21), java.math.BigDecimal.ZERO, false,
                        "", "", "", "", "", "", "España", "", "", "", "", "", "");
        openCustomerDetailDialog(empty, true, onSaved);
    }

    private void openCustomerDetailDialog(com.benjagest.ui.model.CustomerExtendedEntry c,
                                            boolean isNew, Runnable onSaved) {
        Dialog<Void> dialog = new Dialog<>();
        dialog.setTitle(isNew ? t("cli.editor.title.new") : t("cli.editor.title"));
        dialog.setHeaderText(isNew ? t("cli.editor.header.new")
                : (c.legalName() == null || c.legalName().isBlank() ? "—" : c.legalName()));

        // PORT-4 CLI v3 (2026-06-10 tarde tras feedback): editor con
        // datos basicos + DIRECCION POSTAL (necesaria para PDF de
        // factura). Sigue siendo 1 seccion sin TabPane. Combo Tipo
        // traducido. Labels con ColumnConstraints para no truncarse.
        TextField fLegal = new TextField(safe(c.legalName()));
        TextField fTrade = new TextField(safe(c.tradeName()));
        TextField fNif = new TextField(safe(c.taxIdentifier()));
        ComboBox<String> fType = new ComboBox<>(FXCollections.observableArrayList(
                "COMPANY", "SELF_EMPLOYED", "PUBLIC_ENTITY", "OTHER"));
        fType.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String code) {
                if (code == null) return "";
                return switch (code) {
                    case "COMPANY" -> t("cli.type.company");
                    case "SELF_EMPLOYED" -> t("cli.type.self_employed");
                    case "PUBLIC_ENTITY" -> t("cli.type.public_entity");
                    case "OTHER" -> t("cli.type.other");
                    default -> code;
                };
            }
            @Override public String fromString(String s) { return s; }
        });
        fType.setValue(c.customerType() == null || c.customerType().isBlank()
                ? "COMPANY" : c.customerType());
        TextField fPhone = new TextField(safe(c.phone()));
        TextField fEmail = new TextField(safe(c.email()));
        TextField fWebsite = new TextField(safe(c.website()));

        // Direccion postal — NECESARIA para que el PDF de factura
        // pueda pintar el bloque del cliente con NIF + direccion.
        TextField fAddress = new TextField(safe(c.address()));
        TextField fCity = new TextField(safe(c.city()));
        TextField fProvince = new TextField(safe(c.province()));
        TextField fCp = new TextField(safe(c.postalCode()));
        TextField fCountry = new TextField(
                c.country() == null || c.country().isBlank() ? "España" : c.country());

        TextArea fNotes = new TextArea(safe(c.notes()));
        fNotes.setPrefRowCount(3);
        fNotes.setWrapText(true);

        VBox root = new VBox(16);
        root.setPadding(new Insets(8));

        VBox sectionBasic = new VBox(8);
        sectionBasic.getStyleClass().add("settings-section");
        Label basicTitle = new Label(t("cli.section.main"));
        basicTitle.getStyleClass().add("settings-section-title");
        Label basicHint = new Label(t("cli.section.main.hint"));
        basicHint.getStyleClass().add("settings-hint");
        basicHint.setWrapText(true);
        GridPane basicGrid = formGrid(
                t("cli.field.legalName"), fLegal,
                t("cli.field.tradeName"), fTrade,
                t("cli.field.taxId"), fNif,
                t("cli.field.type"), fType,
                t("cli.field.phone"), fPhone,
                t("cli.field.email"), fEmail,
                t("cli.field.website"), fWebsite);
        sectionBasic.getChildren().addAll(basicTitle, basicHint, basicGrid);

        VBox sectionAddr = new VBox(8);
        sectionAddr.getStyleClass().add("settings-section");
        Label addrTitle = new Label(t("cli.section.address"));
        addrTitle.getStyleClass().add("settings-section-title");
        Label addrHint = new Label(t("cli.section.address.hint"));
        addrHint.getStyleClass().add("settings-hint");
        addrHint.setWrapText(true);
        GridPane addrGrid = formGrid(
                t("cli.field.address"), fAddress,
                t("cli.field.city"), fCity,
                t("cli.field.province"), fProvince,
                t("cli.field.postalCode"), fCp,
                t("cli.field.country"), fCountry);
        sectionAddr.getChildren().addAll(addrTitle, addrHint, addrGrid);

        VBox sectionNotes = new VBox(8);
        sectionNotes.getStyleClass().add("settings-section");
        Label notesTitle = new Label(t("cli.field.notes"));
        notesTitle.getStyleClass().add("settings-section-title");
        sectionNotes.getChildren().addAll(notesTitle, fNotes);

        root.getChildren().addAll(sectionBasic, sectionAddr, sectionNotes);
        root.setPrefWidth(620);

        ScrollPane scroll = new ScrollPane(root);
        scroll.setFitToWidth(true);
        scroll.setPrefViewportHeight(520);
        scroll.getStyleClass().add("content-scroll");

        dialog.getDialogPane().setContent(scroll);
        dialog.getDialogPane().getButtonTypes().addAll(
                javafx.scene.control.ButtonType.CANCEL, javafx.scene.control.ButtonType.OK);
        javafx.scene.control.Button okBtn = (javafx.scene.control.Button)
                dialog.getDialogPane().lookupButton(javafx.scene.control.ButtonType.OK);
        okBtn.setText(t("cli.editor.save"));

        dialog.setResultConverter(bt -> {
            if (bt == javafx.scene.control.ButtonType.OK) {
                // Preservamos los campos de facturacion que aun no se
                // editan aqui (fiscalType, billingEmail, IBAN, etc.) —
                // no queremos pisarlos con vacios. Direccion SI la
                // pisamos porque ahora es editable.
                com.benjagest.ui.model.CustomerExtendedEntry upd =
                        new com.benjagest.ui.model.CustomerExtendedEntry(
                                c.id(),
                                fLegal.getText(), fTrade.getText(), fNif.getText(),
                                fType.getValue(),
                                c.fiscalType(),
                                c.billingEmail(), c.billingPhone(),
                                c.defaultVatPercent(), c.defaultRetentionPercent(),
                                c.vatExempt(),
                                c.paymentMethod(), c.iban(),
                                fAddress.getText(), fCity.getText(), fProvince.getText(),
                                fCp.getText(), fCountry.getText(),
                                c.internalCode(), c.defaultMode(),
                                fPhone.getText(), fEmail.getText(), fWebsite.getText(),
                                fNotes.getText());
                // Validacion minima en alta: nombre + NIF obligatorios
                // (el backend tambien valida, pero damos feedback claro).
                if (isNew && (fLegal.getText() == null || fLegal.getText().isBlank()
                        || fNif.getText() == null || fNif.getText().isBlank())) {
                    showError(t("cli.editor.fail.title"), t("cli.editor.required.body"));
                    return null;
                }
                Task<Void> save = new Task<>() {
                    @Override protected Void call() throws Exception {
                        if (isNew) {
                            altaApiClient.createCustomerExtended(upd);
                        } else {
                            altaApiClient.updateCustomerExtended(upd);
                        }
                        return null;
                    }
                };
                save.setOnSucceeded(s -> { if (onSaved != null) onSaved.run(); });
                save.setOnFailed(s -> showError(t("cli.editor.fail.title"),
                        save.getException() == null ? "" : save.getException().getMessage()));
                start(save, "customer-detail-save");
            }
            return null;
        });
        dialog.showAndWait();
    }

    private GridPane formGrid(Object... pairs) {
        GridPane grid = new GridPane();
        grid.setHgap(12);
        grid.setVgap(10);
        grid.setPadding(new Insets(16));
        // Fix 2026-06-10 tarde: sin ColumnConstraints, JavaFX truncaba
        // los Labels y dejaba "Nombr...". Damos a la columna de etiquetas
        // un minWidth holgado y a la columna de inputs que se estire.
        javafx.scene.layout.ColumnConstraints labelCol = new javafx.scene.layout.ColumnConstraints();
        labelCol.setMinWidth(140);
        labelCol.setPrefWidth(140);
        labelCol.setHalignment(javafx.geometry.HPos.LEFT);
        javafx.scene.layout.ColumnConstraints inputCol = new javafx.scene.layout.ColumnConstraints();
        inputCol.setHgrow(Priority.ALWAYS);
        inputCol.setFillWidth(true);
        grid.getColumnConstraints().addAll(labelCol, inputCol);
        int row = 0;
        for (int i = 0; i + 1 < pairs.length; i += 2) {
            Label lab = new Label((String) pairs[i]);
            lab.getStyleClass().add("form-label");
            lab.setMinWidth(javafx.scene.layout.Region.USE_PREF_SIZE);
            lab.setWrapText(true);
            Node input = (Node) pairs[i + 1];
            if (input instanceof javafx.scene.layout.Region r) {
                r.setMaxWidth(Double.MAX_VALUE);
            }
            grid.addRow(row++, lab, input);
        }
        return grid;
    }

    private static String safe(String s) { return s == null ? "" : s; }

    // ============================================================
    //  PORT-3 PERFIL — Modulo Mi perfil
    //  ----------------------------------------------------------
    //  Preferencias personales del usuario logueado: idioma, bloqueo
    //  por inactividad (timeout PIN), estilo de salvapantallas, AI
    //  Copilot (reservado), avatar, plantilla jornada (reservado).
    //
    //  La fila vive en user_settings (V84). El servicio crea defaults
    //  on-the-fly si no existe.
    // ============================================================
    private void showProfileModule() {
        currentModule = "profile";
        recordNav(() -> showProfileModule());
        select("profile");

        VBox root = new VBox(16);
        root.getStyleClass().add("content");

        Label header = label(t("profile.title"), "settings-section-title");
        Label hint = new Label(t("profile.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        VBox sections = new VBox(18);

        // --- Seccion: Idioma ---
        VBox sLang = settingsSection(t("profile.section.language"),
                t("profile.section.language.hint"));
        ComboBox<String> langCombo = new ComboBox<>(FXCollections.observableArrayList("es", "en"));
        langCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(String s) {
                return "es".equals(s) ? "Español"
                        : ("en".equals(s) ? "English" : (s == null ? "" : s));
            }
            @Override public String fromString(String s) { return s; }
        });
        sLang.getChildren().add(langCombo);

        // --- Seccion: Bloqueo por inactividad (PORT-3 LOCK) ---
        VBox sLock = settingsSection(t("profile.section.lock"),
                t("profile.section.lock.hint"));
        javafx.scene.control.Spinner<Integer> timeoutSpin =
                new javafx.scene.control.Spinner<>(0, 120, 0, 1);
        timeoutSpin.setEditable(true);
        Label timeoutHint = new Label(t("profile.lock.zero_hint"));
        timeoutHint.getStyleClass().add("settings-hint");
        timeoutHint.setWrapText(true);
        sLock.getChildren().addAll(
                new Label(t("profile.lock.timeout_label")), timeoutSpin, timeoutHint);

        // --- Seccion: IA Copilot (reservado) ---
        VBox sAi = settingsSection(t("profile.section.ai"),
                t("profile.section.ai.hint"));
        CheckBox aiBox = new CheckBox(t("profile.ai.enable"));
        sAi.getChildren().add(aiBox);

        // --- Seccion: Avatar (ruta local) ---
        VBox sAvatar = settingsSection(t("profile.section.avatar"),
                t("profile.section.avatar.hint"));
        TextField avatarField = new TextField();
        avatarField.setPromptText(t("profile.avatar.path_prompt"));
        Button browseBtn = new Button(t("profile.avatar.browse"));
        browseBtn.setOnAction(ev -> {
            javafx.stage.FileChooser fc = new javafx.stage.FileChooser();
            fc.setTitle(t("profile.avatar.browse"));
            fc.getExtensionFilters().add(new javafx.stage.FileChooser.ExtensionFilter(
                    "PNG / JPG", "*.png", "*.jpg", "*.jpeg"));
            java.io.File f = fc.showOpenDialog(root.getScene().getWindow());
            if (f != null) avatarField.setText(f.getAbsolutePath());
        });
        HBox avatarRow = new HBox(8, avatarField, browseBtn);
        HBox.setHgrow(avatarField, Priority.ALWAYS);
        sAvatar.getChildren().add(avatarRow);

        // Footer
        Button saveBtn = new Button(t("profile.btn.save"));
        saveBtn.setGraphic(icon("fas-save"));
        saveBtn.getStyleClass().add("button-primary");
        HBox footer = new HBox(8, saveBtn);
        footer.setAlignment(Pos.CENTER_RIGHT);

        sections.getChildren().addAll(sLang, sLock, sAi, sAvatar);
        root.getChildren().addAll(header, hint, sections, footer);

        // Carga inicial
        Task<com.benjagest.ui.model.UserSettingsEntry> load = new Task<>() {
            @Override protected com.benjagest.ui.model.UserSettingsEntry call() throws Exception {
                return altaApiClient.getUserSettings();
            }
        };
        load.setOnSucceeded(ev -> {
            var s = load.getValue();
            langCombo.setValue(s.language() == null || s.language().isBlank() ? "es" : s.language());
            timeoutSpin.getValueFactory().setValue(s.pinTimeoutMin());
            aiBox.setSelected(s.aiEnabled());
            avatarField.setText(s.avatarPath() == null ? "" : s.avatarPath());
        });
        load.setOnFailed(ev -> showError(t("profile.fail.title"),
                load.getException() == null ? "" : load.getException().getMessage()));
        start(load, "profile-load");

        saveBtn.setOnAction(ev -> {
            Task<com.benjagest.ui.model.UserSettingsEntry> save = new Task<>() {
                @Override protected com.benjagest.ui.model.UserSettingsEntry call() throws Exception {
                    return altaApiClient.saveUserSettings(
                            langCombo.getValue(),
                            timeoutSpin.getValue(),
                            "clock",
                            aiBox.isSelected(),
                            avatarField.getText(),
                            "");
                }
            };
            save.setOnSucceeded(s -> {
                // Aplicar inmediatamente cambio de idioma
                String newLang = save.getValue().language();
                if ("en".equalsIgnoreCase(newLang) && language != Language.EN) {
                    language = Language.EN;
                } else if ("es".equalsIgnoreCase(newLang) && language != Language.ES) {
                    language = Language.ES;
                }
                // Aplicar nuevo timeout LOCK
                refreshLockTimeout(save.getValue().pinTimeoutMin());
                Alert ok = new Alert(Alert.AlertType.INFORMATION);
                ok.setTitle(t("profile.save.success.title"));
                ok.setHeaderText(t("profile.save.success.body"));
                ok.showAndWait();
            });
            save.setOnFailed(s -> showError(t("profile.fail.title"),
                    save.getException() == null ? "" : save.getException().getMessage()));
            start(save, "profile-save");
        });

        setCenterAnimated(scroll(root));
    }

    private VBox settingsSection(String title, String hint) {
        VBox box = new VBox(8);
        box.getStyleClass().add("settings-section");
        Label t = new Label(title);
        t.getStyleClass().add("settings-section-title");
        Label h = new Label(hint);
        h.setWrapText(true);
        h.getStyleClass().add("settings-hint");
        box.getChildren().addAll(t, h);
        return box;
    }

    // ============================================================
    //  PORT-3 LOCK — Bloqueo por inactividad
    //  ----------------------------------------------------------
    //  Cuando el usuario lleva N minutos sin tocar el raton ni el
    //  teclado (configurado en user_settings.pin_timeout_min, 0 =
    //  desactivado), aparece una Stage modal UNDECORATED que pide el
    //  PIN del dispositivo. Solo se cierra cuando el PIN se valida
    //  con pinLogin.
    //
    //  Implementacion minimalista: un Timeline que tick cada 30s y
    //  compara now contra lastInputAt. lastInputAt se actualiza con
    //  event filters globales en la Scene.
    // ============================================================
    private long lastInputAt = System.currentTimeMillis();
    private int lockTimeoutMin = 0;
    private javafx.animation.Timeline lockChecker = null;
    private boolean lockShowing = false;

    /** Actualiza el timeout activo y arranca/detiene el checker. */
    private void refreshLockTimeout(int newTimeoutMin) {
        this.lockTimeoutMin = Math.max(0, newTimeoutMin);
        if (lockChecker != null) lockChecker.stop();
        if (this.lockTimeoutMin <= 0) return;
        installLockInputTracker();
        lockChecker = new javafx.animation.Timeline(
                new javafx.animation.KeyFrame(
                        javafx.util.Duration.seconds(30),
                        ev -> checkLock()));
        lockChecker.setCycleCount(javafx.animation.Timeline.INDEFINITE);
        lockChecker.play();
    }

    private boolean lockTrackerInstalled = false;
    private void installLockInputTracker() {
        if (lockTrackerInstalled) return;
        if (root == null || root.getScene() == null) return;
        root.getScene().addEventFilter(javafx.scene.input.MouseEvent.ANY,
                ev -> lastInputAt = System.currentTimeMillis());
        root.getScene().addEventFilter(javafx.scene.input.KeyEvent.ANY,
                ev -> lastInputAt = System.currentTimeMillis());
        lockTrackerInstalled = true;
    }

    private void checkLock() {
        if (lockShowing || lockTimeoutMin <= 0) return;
        long elapsedMin = (System.currentTimeMillis() - lastInputAt) / 60000L;
        if (elapsedMin >= lockTimeoutMin) {
            // El checker corre dentro del pulso del Timeline; showAndWait() NO se
            // permite durante animación/layout → se difiere con runLater. Marcamos
            // lockShowing ya para no reentrar en el siguiente tick.
            lockShowing = true;
            javafx.application.Platform.runLater(this::showLockStage);
        }
    }

    /** Muestra una Stage UNDECORATED modal pidiendo el PIN.
     *  PORT-4 SESSION (2026-06-10): verifica contra session_pin_hash
     *  via /api/settings/session/pin/verify (no contra el PIN de
     *  vinculación del dispositivo). Fondo varía según
     *  {@link #screensaverStyle}. */
    private void showLockStage() {
        lockShowing = true;
        javafx.stage.Stage stage = new javafx.stage.Stage();
        stage.initStyle(javafx.stage.StageStyle.UNDECORATED);
        stage.initModality(javafx.stage.Modality.APPLICATION_MODAL);
        stage.setTitle("BENJAGEST — " + t("lock.title"));

        Label title = new Label(t("lock.title"));
        title.setStyle("-fx-text-fill: white; -fx-font-size: 22px; -fx-font-weight: 800;");
        Label sub = new Label(t("lock.subtitle"));
        sub.setStyle("-fx-text-fill: #d7deea;");
        sub.setWrapText(true);

        PasswordField pin = new PasswordField();
        pin.setPromptText("PIN");
        pin.setMaxWidth(220);
        Label err = new Label("");
        err.setStyle("-fx-text-fill: #fca5a5; -fx-font-weight: 700;");

        Button unlock = new Button(t("lock.btn.unlock"));
        unlock.getStyleClass().add("button-primary");
        Button logoutBtn = new Button(t("lock.btn.logout"));

        Runnable tryUnlock = () -> {
            if (pin.getText() == null || pin.getText().isBlank()) return;
            Task<Boolean> task = new Task<>() {
                @Override protected Boolean call() throws Exception {
                    return altaApiClient.verifySessionPin(pin.getText().trim());
                }
            };
            task.setOnSucceeded(s -> {
                if (Boolean.TRUE.equals(task.getValue())) {
                    lastInputAt = System.currentTimeMillis();
                    lockShowing = false;
                    stage.close();
                } else {
                    err.setText(t("lock.fail"));
                    pin.clear();
                }
            });
            task.setOnFailed(s -> {
                err.setText(t("lock.fail"));
                pin.clear();
            });
            start(task, "lock-verify");
        };
        unlock.setOnAction(ev -> tryUnlock.run());
        pin.setOnAction(ev -> tryUnlock.run());
        logoutBtn.setOnAction(ev -> {
            lockShowing = false;
            stage.close();
            try { authApiClient.logout(); } catch (Exception ignore) {}
            AuthSession.get().clear();
            showLogin();
        });

        // Pantalla donde está la app (multi-monitor): detectada por el CENTRO de la
        // ventana de la app. El salvapantallas cubre ESA pantalla entera. Se calcula
        // ANTES del fondo para poder dimensionar el logo respecto a la pantalla.
        javafx.geometry.Rectangle2D area = javafx.stage.Screen.getPrimary().getBounds();
        try {
            javafx.stage.Window owner = (root != null && root.getScene() != null)
                    ? root.getScene().getWindow() : null;
            if (owner != null && owner.getWidth() > 0 && owner.getHeight() > 0) {
                double cx = owner.getX() + owner.getWidth() / 2;
                double cy = owner.getY() + owner.getHeight() / 2;
                var screens = javafx.stage.Screen.getScreensForRectangle(cx, cy, 1, 1);
                if (!screens.isEmpty()) area = screens.get(0).getBounds();
            }
        } catch (Exception ignored) {
        }

        // ---- Fondo según salvapantallas ----
        StackPane background = new StackPane();
        background.setStyle("-fx-background-color: linear-gradient(to bottom right, #0a0f1a, #0e1830);");
        String style = screensaverStyle == null ? "clock" : screensaverStyle;
        switch (style) {
            case "logo" -> background.getChildren().add(buildScreensaverLogo(area.getWidth(), area.getHeight()));
            case "carousel" -> background.getChildren().add(buildScreensaverCarousel(stage, area.getWidth(), area.getHeight()));
            case "clock" -> background.getChildren().add(buildScreensaverClock(stage));
            case "dark" -> { /* fondo oscuro liso, nada más */ }
            default -> { /* tipo desconocido → liso */ }
        }

        // Teclado numérico OCULTO (por si falla el teclado físico). Se muestra con
        // el enlace "Teclado" y escribe en el campo del PIN.
        GridPane keypad = new GridPane();
        keypad.setHgap(8); keypad.setVgap(8); keypad.setAlignment(Pos.CENTER);
        keypad.setVisible(false); keypad.setManaged(false);
        String[] keys = {"1", "2", "3", "4", "5", "6", "7", "8", "9", "C", "0", "⌫"};
        for (int i = 0; i < keys.length; i++) {
            String k = keys[i];
            Button kb = new Button(k);
            kb.setMinSize(58, 48);
            kb.setFocusTraversable(false);
            kb.setStyle("-fx-font-size: 18px; -fx-background-radius: 8;"
                    + " -fx-background-color: rgba(255,255,255,0.10); -fx-text-fill: white;");
            kb.setOnAction(ev -> {
                String cur = pin.getText() == null ? "" : pin.getText();
                if ("C".equals(k)) pin.setText("");
                else if ("⌫".equals(k)) pin.setText(cur.isEmpty() ? "" : cur.substring(0, cur.length() - 1));
                else pin.setText(cur + k);
            });
            keypad.add(kb, i % 3, i / 3);
        }
        javafx.scene.control.Hyperlink toggleKeypad = new javafx.scene.control.Hyperlink(t("lock.keypad.show"));
        toggleKeypad.setStyle("-fx-text-fill: #93c5fd;");
        toggleKeypad.setOnAction(ev -> {
            boolean show = !keypad.isVisible();
            keypad.setVisible(show); keypad.setManaged(show);
            toggleKeypad.setText(show ? t("lock.keypad.hide") : t("lock.keypad.show"));
        });

        VBox pinBox = new VBox(14, title, sub, pin, err, toggleKeypad, keypad, unlock, logoutBtn);
        pinBox.setAlignment(Pos.CENTER);
        pinBox.setMaxWidth(360);
        pinBox.setStyle("-fx-background-color: rgba(15, 27, 45, 0.85);"
                + " -fx-background-radius: 14; -fx-padding: 30;");
        background.getChildren().add(pinBox);
        StackPane.setAlignment(pinBox, Pos.CENTER);

        // La Scene se crea CON el tamaño de la pantalla y el StackPane raíz la
        // rellena entera (antes, sin tamaño, quedaba del ancho del contenido → la
        // franja central que se veía). setFill oscuro como red de seguridad.
        background.setMinSize(area.getWidth(), area.getHeight());
        background.setPrefSize(area.getWidth(), area.getHeight());
        Scene scene = new Scene(background, area.getWidth(), area.getHeight());
        scene.setFill(javafx.scene.paint.Color.web("#0a0f1a"));
        stage.setScene(scene);
        stage.setOnCloseRequest(ev -> ev.consume());  // no se cierra por X
        stage.setFullScreenExitHint("");
        stage.setFullScreenExitKeyCombination(javafx.scene.input.KeyCombination.NO_MATCH);
        stage.setX(area.getMinX());
        stage.setY(area.getMinY());
        stage.setWidth(area.getWidth());
        stage.setHeight(area.getHeight());
        stage.setAlwaysOnTop(true);
        javafx.application.Platform.runLater(pin::requestFocus);
        stage.showAndWait();
    }

    private Node buildScreensaverClock(javafx.stage.Stage owner) {
        Label clock = new Label();
        clock.setStyle("-fx-text-fill: white; -fx-font-size: 96px;"
                + " -fx-font-family: 'Segoe UI Light', 'Inter', monospace;"
                + " -fx-opacity: 0.65;");
        Label date = new Label();
        date.setStyle("-fx-text-fill: #cbd5e1; -fx-font-size: 16px; -fx-opacity: 0.6;");
        VBox box = new VBox(8, clock, date);
        box.setAlignment(Pos.TOP_CENTER);
        box.setPadding(new Insets(60, 0, 0, 0));
        Runnable tick = () -> {
            java.time.LocalTime now = java.time.LocalTime.now();
            java.time.LocalDate today = java.time.LocalDate.now();
            clock.setText(String.format("%02d:%02d", now.getHour(), now.getMinute()));
            date.setText(today.format(java.time.format.DateTimeFormatter.ofPattern(
                    "EEEE, d MMMM yyyy", activeLocale())));
        };
        tick.run();
        javafx.animation.Timeline tl = new javafx.animation.Timeline(
                new javafx.animation.KeyFrame(javafx.util.Duration.seconds(15),
                        ev -> tick.run()));
        tl.setCycleCount(javafx.animation.Timeline.INDEFINITE);
        tl.play();
        owner.setOnHidden(ev -> tl.stop());
        return box;
    }

    /**
     * Logo GRANDE centrado (≈ mitad de la pantalla de alto), sobre un panel
     * del tamaño completo de la pantalla para que el salvapantallas llene de
     * verdad. fitHeight/fitWidth fijos: cuando la imagen carga (async) NO
     * cambia el layout → sin saltos.
     */
    private Node buildScreensaverLogo(double w, double h) {
        javafx.scene.image.ImageView iv = new javafx.scene.image.ImageView();
        iv.setPreserveRatio(true);
        iv.setSmooth(true);
        iv.setFitHeight(Math.max(220, h * 0.5));
        iv.setFitWidth(Math.max(220, w * 0.6));
        iv.setOpacity(0.9);
        Task<byte[]> load = new Task<>() {
            @Override protected byte[] call() throws Exception {
                return altaApiClient.getCompanyLogoBytes();
            }
        };
        load.setOnSucceeded(s -> {
            byte[] b = load.getValue();
            if (b != null && b.length > 0) iv.setImage(new javafx.scene.image.Image(
                    new java.io.ByteArrayInputStream(b)));
        });
        start(load, "lock-saver-logo");
        StackPane p = new StackPane(iv);
        p.setMinSize(w, h);
        p.setPrefSize(w, h);
        StackPane.setAlignment(iv, Pos.CENTER);
        return p;
    }

    /**
     * Carrusel = logo grande con un zoom lento y una deriva horizontal suave
     * (efecto "flotar"), ambos con Interpolator.EASE_BOTH para que sea fluido
     * (sin los saltitos del escalado lineal anterior).
     */
    private Node buildScreensaverCarousel(javafx.stage.Stage owner, double w, double h) {
        Node base = buildScreensaverLogo(w, h);
        javafx.animation.ScaleTransition st = new javafx.animation.ScaleTransition(
                javafx.util.Duration.seconds(9), base);
        st.setFromX(1.0); st.setFromY(1.0);
        st.setToX(1.14); st.setToY(1.14);
        st.setInterpolator(javafx.animation.Interpolator.EASE_BOTH);
        st.setAutoReverse(true);
        st.setCycleCount(javafx.animation.Animation.INDEFINITE);
        javafx.animation.TranslateTransition tt = new javafx.animation.TranslateTransition(
                javafx.util.Duration.seconds(13), base);
        tt.setFromX(-w * 0.04); tt.setToX(w * 0.04);
        tt.setInterpolator(javafx.animation.Interpolator.EASE_BOTH);
        tt.setAutoReverse(true);
        tt.setCycleCount(javafx.animation.Animation.INDEFINITE);
        st.play();
        tt.play();
        owner.setOnHidden(ev -> { st.stop(); tt.stop(); });
        return base;
    }

