    private TableView<com.benjagest.ui.model.AdvisoryInvitationEntry> buildAdvisoryInvitationsTable() {
        TableView<com.benjagest.ui.model.AdvisoryInvitationEntry> tbl = new TableView<>();
        tbl.getStyleClass().add("data-table");
        tbl.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);
        tbl.setPlaceholder(new Label(t("advisory.invitations.placeholder.empty")));
        tbl.setPrefHeight(200);

        TableColumn<com.benjagest.ui.model.AdvisoryInvitationEntry, String> colDate =
                new TableColumn<>(t("advisory.invitations.col.date"));
        colDate.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().createdAt() == null ? "—"
                        : c.getValue().createdAt().atZone(java.time.ZoneId.systemDefault())
                                .toLocalDate().toString()));
        colDate.setComparator(ISO_DATE_COMPARATOR);
        colDate.setPrefWidth(110);
        TableColumn<com.benjagest.ui.model.AdvisoryInvitationEntry, String> colEmail =
                new TableColumn<>(t("advisory.invitations.col.email"));
        colEmail.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().invitedEmail() == null ? "—" : c.getValue().invitedEmail()));
        TableColumn<com.benjagest.ui.model.AdvisoryInvitationEntry, String> colNif =
                new TableColumn<>(t("advisory.invitations.col.nif"));
        colNif.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().invitedNif() == null ? "—" : c.getValue().invitedNif()));
        colNif.setPrefWidth(110);
        TableColumn<com.benjagest.ui.model.AdvisoryInvitationEntry, String> colCompany =
                new TableColumn<>(t("advisory.invitations.col.company"));
        colCompany.setCellValueFactory(c -> new SimpleStringProperty(
                c.getValue().invitedCompanyName() == null ? "—" : c.getValue().invitedCompanyName()));
        TableColumn<com.benjagest.ui.model.AdvisoryInvitationEntry, String> colStatus =
                new TableColumn<>(t("advisory.invitations.col.status"));
        colStatus.setCellValueFactory(c -> new SimpleStringProperty(
                t("advisory.invitations.status." + c.getValue().status())));
        colStatus.setPrefWidth(110);
        tbl.getColumns().setAll(colDate, colEmail, colNif, colCompany, colStatus);
        return tbl;
    }

    private void reloadAdvisoryInvitations() {
        if (advisoryInvitationsTable == null) return;
        Task<java.util.List<com.benjagest.ui.model.AdvisoryInvitationEntry>> task = new Task<>() {
            @Override
            protected java.util.List<com.benjagest.ui.model.AdvisoryInvitationEntry> call() throws Exception {
                return invitationsApi.listMine();
            }
        };
        task.setOnSucceeded(e -> advisoryInvitationsTable.getItems().setAll(task.getValue()));
        task.setOnFailed(e -> showError(t("advisory.invitations.fail.list.title"),
                t("advisory.invitations.fail.list.body")));
        start(task, "advisory-invitations-list");
    }

    private void showCreateInvitationDialog() {
        Dialog<ButtonType> dialog = new Dialog<>();
        dialog.setTitle(t("advisory.invitations.create.title"));
        ButtonType saveBt = new ButtonType(t("advisory.invitations.create.save"),
                ButtonBar.ButtonData.OK_DONE);
        dialog.getDialogPane().getButtonTypes().addAll(saveBt, ButtonType.CANCEL);

        TextField emailField = new TextField();
        TextField nifField = new TextField();
        TextField nameField = new TextField();
        TextArea notesArea = new TextArea();
        notesArea.setPrefRowCount(3);
        for (TextField tf : new TextField[]{emailField, nifField, nameField}) {
            tf.setPrefColumnCount(28);
        }
        Label hint = new Label(t("advisory.invitations.create.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        GridPane g = new GridPane();
        g.setHgap(12); g.setVgap(8);
        int r = 0;
        g.add(new Label(t("advisory.invitations.create.email")), 0, r); g.add(emailField, 1, r++);
        g.add(new Label(t("advisory.invitations.create.nif")), 0, r); g.add(nifField, 1, r++);
        g.add(new Label(t("advisory.invitations.create.company_name")), 0, r); g.add(nameField, 1, r++);
        g.add(new Label(t("advisory.invitations.create.notes")), 0, r); g.add(notesArea, 1, r++);
        g.add(hint, 0, r++, 2, 1);
        installDialog(dialog, g);

        Button save = (Button) dialog.getDialogPane().lookupButton(saveBt);
        save.addEventFilter(javafx.event.ActionEvent.ACTION, ev -> {
            ev.consume();
            String email = nullIfBlank(emailField.getText());
            String nif = nullIfBlank(nifField.getText());
            if (email == null && nif == null) {
                showError(t("advisory.invitations.create.fail.missing.title"),
                        t("advisory.invitations.create.fail.missing.body"));
                return;
            }
            Task<com.benjagest.ui.model.AdvisoryInvitationEntry> task = new Task<>() {
                @Override
                protected com.benjagest.ui.model.AdvisoryInvitationEntry call() throws Exception {
                    return invitationsApi.create(email, nif,
                            nullIfBlank(nameField.getText()),
                            nullIfBlank(notesArea.getText()));
                }
            };
            task.setOnSucceeded(e -> {
                var inv = task.getValue();
                // Copiar el token al portapapeles automáticamente
                if (inv.token() != null) {
                    javafx.scene.input.Clipboard.getSystemClipboard().setContent(
                            java.util.Map.of(javafx.scene.input.DataFormat.PLAIN_TEXT, inv.token()));
                }
                showInfo(t("advisory.invitations.create.ok.title"),
                        t("advisory.invitations.create.ok.body") + "\n\n"
                                + t("advisory.invitations.token_label") + " " + inv.token());
                dialog.setResult(saveBt);
                dialog.close();
                // Refresco local inmediato: la nueva invitación PENDING
                // aparece YA en el listado + el badge de la fila del
                // cliente en el portfolio pasa a "📩 Invitación
                // pendiente" sin esperar al tick de 5s.
                reloadAdvisoryInvitations();
                pollAdvisoryClients();
            });
            task.setOnFailed(e -> showError(t("advisory.invitations.create.fail.title"),
                    t("advisory.invitations.create.fail.body")));
            start(task, "advisory-invitations-create");
        });

        dialog.showAndWait();
    }

    private void revokeInvitation(com.benjagest.ui.model.AdvisoryInvitationEntry row) {
        Alert confirm = new Alert(Alert.AlertType.CONFIRMATION,
                t("advisory.invitations.revoke.confirm.body"),
                ButtonType.OK, ButtonType.CANCEL);
        confirm.setHeaderText(t("advisory.invitations.revoke.confirm.title"));
        confirm.showAndWait().filter(b -> b == ButtonType.OK).ifPresent(b -> {
            Task<Void> task = new Task<>() {
                @Override
                protected Void call() throws Exception {
                    invitationsApi.revoke(row.id());
                    return null;
                }
            };
            task.setOnSucceeded(e -> {
                // Refresco local inmediato: el listado de invitaciones
                // muestra YA la fila como REVOKED + el portfolio se
                // actualiza para que el botón "Invitar cliente
                // seleccionado" vuelva a habilitarse sin esperar a 5s.
                reloadAdvisoryInvitations();
                pollAdvisoryClients();
            });
            task.setOnFailed(e -> showError(t("advisory.invitations.revoke.fail.title"),
                    t("advisory.invitations.revoke.fail.body")));
            start(task, "advisory-invitations-revoke");
        });
    }

    /**
     * Abre la pantalla de gestión del cliente desde la asesoría.
     *
     * <p>NO cambia el activeCompanyId (la asesoría sigue siendo la
     * empresa activa de la sesión, el sidebar es el suyo, el header
     * conserva la marca de la asesoría). Solo activa el override
     * "acting for" en AuthSession para que las llamadas de esta
     * pantalla viajen con {@code X-Company-Id = cliente.id}.
     *
     * <p>Cuando el usuario pulsa "Volver" se limpia el override y se
     * regresa al listado de clientes — recuperando el contexto puro
     * de asesoría.
     */
    private void switchToClient(com.benjagest.ui.model.ManagedClientEntry client) {
        switchToClient(client, true);
    }

    /**
     * Slice 3G-2 — La asesoría entra a su propia gestión reutilizando
     * el flujo de "cliente vinculado". Crea un ManagedClientEntry
     * sintético con los datos del activeCompany (la asesoría está en
     * SU propio tenant cuando hace click) y arranca el switch al modo
     * cliente apuntando a SU MISMO company_id. Como
     * actingForCompanyId pasa a ser igual al activeCompanyId, todas
     * las llamadas API siguen golpeando el mismo tenant — solo cambia
     * la PANTALLA que se le muestra al asesor (entra al detalle del
     * cliente con todos los tabs: Diario, Mayor, Recurrentes, AEAT, …).
     */
    private void goToMyCompany() {
        var session = com.benjagest.ui.service.AuthSession.get();
        String id = session.activeCompanyId();
        if (id == null || id.isBlank()) return;
        String legalName = session.activeCompanyLegalName() == null
                ? t("sidebar.my_company") : session.activeCompanyLegalName();
        var synthetic = new com.benjagest.ui.model.ManagedClientEntry(
                id, legalName, null, null,
                "ADVISORY", null, null, null, null);
        // Slice 3H-6 — Garantiza la self-link de la asesoría ANTES de
        // entrar. Si la migración V64 no se aplicó o la asesoría es
        // anterior a esa migración, el backend creará la fila en
        // advisory_invitations en este momento. Llamada best-effort:
        // si falla por cualquier motivo (red, permisos), entramos
        // igual al modo cliente — la peor consecuencia es que el
        // banner de cliente vinculado no muestre el sello.
        new Thread(() -> {
            try {
                altaApiClient.ensureAdvisorySelfLink();
            } catch (Exception ignored) { /* defensivo */ }
            javafx.application.Platform.runLater(() ->
                    switchToClient(synthetic, true));
        }, "ensure-self-link").start();
    }

    /**
     * Variante con flag de vinculación: si {@code isLinked=false} la
     * pantalla del cliente unifica Ventas y Gastos en un solo tab
     * (modelo A3/Contasol: el asesor SOLO archiva las facturas que el
     * cliente emitió en otro sistema, no las emite él).
     */
    private void switchToClient(com.benjagest.ui.model.ManagedClientEntry client,
                                  boolean isLinked) {
        AuthSession.get().setActingForCompanyId(client.id());
        actingClientName = client.legalName();
        // Slice 3T — Persistir el flag para que botones contextuales
        // (p.ej. "Hacer recurrente" en listados) sepan si están en
        // shadow company y abran el editor contable apropiado.
        actingForClientLinked = isLinked;
        refreshClientModeBanner();
        // Slice 5D — Consultamos qué módulos puede ver este usuario en
        // este cliente antes de construir el TabPane. Si la respuesta
        // incluye "*" (OWNER o asignación abierta), se muestran todos
        // los tabs. En caso contrario solo los que estén en la lista.
        // La llamada es defensiva: ante cualquier error caemos a ["*"]
        // (ver myModulesInClient) — preferimos mostrar de más a romper
        // el flujo de acceso al cliente.
        Task<List<String>> task = new Task<>() {
            @Override protected List<String> call() throws Exception {
                // CLIENT-CONFIG (2026-06-15): auto-activar los módulos operativos
                // del cliente ANTES de cargar las pestañas (evita "módulo no
                // activo" en no vinculados). Best-effort: si falla, seguimos.
                try { altaApiClient.ensureOperativaModules(); } catch (Exception ignored) { }
                return altaApiClient.myModulesInClient(client.id());
            }
        };
        task.setOnSucceeded(ev -> {
            activeClientEntry = client;
            activeClientModules = task.getValue();
            setCenterAnimated(buildClientDetailView(client, isLinked, task.getValue()));
        });
        task.setOnFailed(ev -> {
            activeClientEntry = client;
            activeClientModules = List.of("*");
            setCenterAnimated(buildClientDetailView(client, isLinked, List.of("*")));
        });
        start(task, "team-my-modules");
    }

    /**
     * NAV-CLIENT-BACK — "Volver" inteligente: si la asesoria esta
     * actuando-como un cliente, reconstruye la pantalla de detalle de
     * ESE cliente (con sus tabs). Si no, vuelve a la facturacion normal
     * de la asesoria/empresa. Lo usan los editores que reemplazan el
     * centro (Nueva factura, etc.) para no dejar al asesor atrapado.
     */
    private void returnToClientOrBilling() {
        if (com.benjagest.ui.service.AuthSession.get().isActingForClient()
                && activeClientEntry != null) {
            setCenterAnimated(buildClientDetailView(
                    activeClientEntry, actingForClientLinked, activeClientModules));
        } else {
            showBilling();
        }
    }

    /**
     * GESTOR-NAVEGADOR (Fase 1b) — Lanza el navegador embebido (módulo
     * `gestor-navegador`, Chromium/JCEF) como PROCESO/ventana aparte, con el
     * título = nombre del cliente y pestañas a las sedes (AEAT/DEHú/SS RED). Usa
     * el mismo JRE que la app y el almacén de certificados del sistema.
     */
    private void launchGestorNavegador(String clientName) {
        java.io.File jar = locateGestorJar();
        if (jar == null) {
            showError(t("advisory.client.gestor_navegador"), t("gestor.jar.notfound"));
            return;
        }
        String javaBin = System.getProperty("java.home") + java.io.File.separator
                + "bin" + java.io.File.separator + "java";
        java.util.List<String> cmd = new java.util.ArrayList<>();
        cmd.add(javaBin);
        cmd.add("-jar");
        cmd.add(jar.getAbsolutePath());
        cmd.add("--title=" + (clientName == null || clientName.isBlank() ? "Cliente" : clientName));
        cmd.add("AEAT=https://sede.agenciatributaria.gob.es");
        cmd.add("DEHú=https://dehu.redsara.es/");
        cmd.add("Import@ss=https://portal.seg-social.gob.es/");
        Task<Void> task = new Task<>() {
            @Override protected Void call() throws Exception {
                // Fase 2: importar el .p12 del cliente activo (X-Company-Id) al
                // almacen de Windows para que Chromium lo ofrezca en su dialogo
                // nativo de certificado. Best-effort: si falla, el navegador abre
                // igual y el usuario usa su almacen del sistema.
                String thumbprint = null;
                try {
                    thumbprint = altaApiClient.openBrowserCertSession();
                } catch (Exception ex) {
                    System.err.println("[gestor] No se pudo preparar el certificado del cliente: "
                            + ex.getMessage());
                }
                Process proc = new ProcessBuilder(cmd).inheritIO().start();
                // Esperar al cierre del gestor (hilo dedicado) para luego quitar la
                // huella del almacen — no dejamos la clave del cliente residente.
                proc.waitFor();
                if (thumbprint != null) {
                    try {
                        altaApiClient.closeBrowserCertSession(thumbprint);
                    } catch (Exception ex) {
                        System.err.println("[gestor] No se pudo quitar el certificado del almacen: "
                                + ex.getMessage());
                    }
                }
                return null;
            }
        };
        task.setOnFailed(ev -> showError(t("advisory.client.gestor_navegador"), t("gestor.launch.fail")));
        start(task, "gestor-navegador-launch");
    }

    /** Localiza el fat-jar del gestor-navegador (dev: relativo al repo; override por -D). */
    private java.io.File locateGestorJar() {
        String override = System.getProperty("benjagest.gestor.jar");
        if (override != null && !override.isBlank()) {
            java.io.File f = new java.io.File(override);
            if (f.isFile()) return f;
        }
        String[] candidates = {
                "gestor-navegador/target/gestor-navegador.jar",
                "../gestor-navegador/target/gestor-navegador.jar",
        };
        for (String c : candidates) {
            java.io.File f = new java.io.File(System.getProperty("user.dir"), c);
            if (f.isFile()) return f;
        }
        return null;
    }

    /**
     * Entrada unificada para abrir un cliente desde la cartera:
     * <ul>
     *   <li>Si el cliente está vinculado → {@link #switchToClient} directo
     *       con la company existente.</li>
     *   <li>Si NO está vinculado → llama al backend para crear (o recuperar)
     *       la shadow company gestionada por la asesoría con su NIF,
     *       después hace el switch a esa company.</li>
     * </ul>
     * Así la asesoría puede llevar la contabilidad/facturación/AEAT de
     * un cliente que aún no ha aceptado invitación, igual que de uno
     * vinculado. La fusión cuando el cliente acepte la invitación
     * después queda para un slice futuro.
     */
    private void openPortfolioClient(com.benjagest.ui.model.CustomerPortfolioEntry sel) {
        // Distinción REAL de vinculación:
        //   - fullyLinked = el cliente aceptó la invitación
        //     (advisory_invitations.status='ACCEPTED'). Tiene su propia
        //     company, emite facturas con VeriFactu desde BENJAGEST.
        //     → UI con tabs Facturación + Compras y Gastos.
        //   - hasCompany() && !fullyLinked = solo hay shadow company
        //     (MANAGED_CLIENT). El asesor archiva facturas que el
        //     cliente emitió en otro sistema.
        //     → UI con tab unificado Ventas y Gastos.
        if (sel.hasCompany()) {
            switchToClient(sel.asManagedClient(), sel.fullyLinked());
            return;
        }
        Task<String> task = new Task<>() {
            @Override
            protected String call() throws Exception {
                return altaApiClient.startClientManagement(sel.customerId());
            }
        };
        task.setOnSucceeded(ev -> {
            String companyId = task.getValue();
            // Construir un ManagedClientEntry "sintético" con la company
            // shadow recién obtenida y los datos del customer.
            var synthetic = new com.benjagest.ui.model.ManagedClientEntry(
                    companyId,
                    sel.legalName(),
                    sel.tradeName(),
                    sel.taxIdentifier(),
                    sel.customerType(),
                    sel.email(),
                    sel.phone(),
                    sel.city(),
                    null);
            // Cliente NO vinculado: la pantalla unifica Ventas y Gastos
            // (no hay Facturación porque el asesor no emite, solo archiva).
            switchToClient(synthetic, false);
            // El portfolio cambia (ahora el cliente aparece como vinculado
            // virtualmente). Refrescamos para que el badge se actualice.
            com.benjagest.ui.support.RefreshBus.emit(
                    com.benjagest.ui.support.RefreshBus.TOPIC_PORTFOLIO);
        });
        task.setOnFailed(ev -> showError(
                t("advisory.portfolio.start_management.fail.title"),
                t("advisory.portfolio.start_management.fail.body")));
        start(task, "advisory-start-client-management");
    }

    private Node buildClientDetailView(com.benjagest.ui.model.ManagedClientEntry client) {
        return buildClientDetailView(client, true, List.of("*"));
    }

    /**
     * Slice 5D — Compatibilidad: cuando el llamador no necesita filtrar
     * por asignación (p.ej. flujos internos previos al reparto), se
     * comporta como antes y muestra todos los tabs.
     */
    private Node buildClientDetailView(com.benjagest.ui.model.ManagedClientEntry client,
                                         boolean isLinked) {
        return buildClientDetailView(client, isLinked, List.of("*"));
    }

    /**
     * Construye la vista de detalle de un cliente desde la asesoría.
     *
     * <p>Estructura de pestañas según {@code isLinked}:
     * <ul>
     *   <li><b>Cliente vinculado</b>: Facturación (emisión propia con
     *       VeriFactu) + Compras y Gastos + Contabilidad + …</li>
     *   <li><b>Cliente NO vinculado</b>: Ventas y Gastos unificado
     *       (modelo A3/Contasol — el asesor solo archiva, no emite)
     *       + Contabilidad + …</li>
     * </ul>
     */
    private Node buildClientDetailView(com.benjagest.ui.model.ManagedClientEntry client,
                                         boolean isLinked,
                                         List<String> visibleModules) {
        // Slice 5D — Helper local: true si el slug se ve para el user actual
        // en este cliente. visibleModules es lo que devuelve
        // /api/advisory/team/assignments/mine/modules/{clientId}.
        //   - Si contiene "*" → OWNER o asignación abierta → todo visible.
        //   - Si no, solo se muestran los slugs presentes.
        // Los tabs "estructurales" (Resumen, Certificado) son siempre
        // visibles porque pertenecen a la identidad fiscal del cliente,
        // no a un módulo concreto del catálogo — un asesor sin "billing"
        // sigue necesitando ver quién es el cliente y su certificado.
        final boolean seeAll = visibleModules == null || visibleModules.contains("*");
        java.util.function.Predicate<String> canSee = slug ->
                seeAll || visibleModules.contains(slug);

        // ¿Es "Mi gestión" (la propia empresa de la asesoría) y no un cliente
        // real? En ese caso las pestañas operativas (Facturación, Compras,
        // Fiscal) usan las PANTALLAS COMPLETAS del módulo (las mismas que el
        // sidebar), no las versiones reducidas de cliente. Decisión Benjamin
        // 2026-06-15: sidebar = administración; "Mi gestión" = operativa completa.
        final String ownCompanyId = com.benjagest.ui.service.AuthSession.get().activeCompanyId();
        final boolean isOwn = client.id() != null && client.id().equals(ownCompanyId);

        Button backBtn = new Button(t("advisory.client.back"));
        backBtn.setGraphic(icon("fas-arrow-left"));
        backBtn.setOnAction(ev -> {
            exitClientMode();
            showAdvisoryClients();
        });

        Label clientNameLabel = new Label(client.legalName());
        clientNameLabel.getStyleClass().add("module-detail-title");
        Label clientMeta = new Label(
                (client.taxIdentifier() == null ? "" : client.taxIdentifier())
                        + (client.city() == null || client.city().isBlank()
                                ? "" : "  ·  " + client.city()));
        clientMeta.getStyleClass().add("module-detail-description");
        VBox clientTitle = new VBox(2, clientNameLabel, clientMeta);

        StackPane clientIcon = iconBubble("fas-building", "module-title-icon");
        Region spacer = new Region();
        HBox.setHgrow(spacer, Priority.ALWAYS);
        // GESTOR-NAVEGADOR — abre el navegador embebido (proceso aparte) con las sedes
        // (AEAT/DEHú/SS RED) y el certificado del cliente. Título = nombre del cliente.
        Button gestorBtn = new Button(t("advisory.client.gestor_navegador"));
        gestorBtn.setGraphic(icon("fas-globe"));
        gestorBtn.getStyleClass().add("button-secondary");
        gestorBtn.setOnAction(ev -> launchGestorNavegador(client.legalName()));
        HBox header = new HBox(16, backBtn, clientIcon, clientTitle, spacer, gestorBtn);
        header.setAlignment(Pos.CENTER_LEFT);
        header.getStyleClass().add("module-detail-header");

        Label hint = new Label(t("advisory.client.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        // TabPane: cada sección hace queries con X-Company-Id=cliente
        // gracias al actingForCompanyId activo en AuthSession.
        TabPane tabs = new TabPane();
        tabs.getStyleClass().add("settings-tabs");
        tabs.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);

        // KPIs en el Resumen solo para vinculados — en el no vinculado
        // viven dentro de "Ventas y Gastos" para no duplicarse.
        Tab summaryTab = new Tab(t("advisory.client.tab.summary"),
                buildClientSummaryTab(client, isLinked));
        summaryTab.setGraphic(icon("fas-chart-line"));

        // Tabs de facturas según vinculación del cliente:
        //
        //   - Vinculado: dos tabs (Facturación + Compras y Gastos)
        //     porque el cliente sí emite facturas desde BENJAGEST
        //     (con VeriFactu, series, PDF generado por nosotros).
        //
        //   - No vinculado: un solo tab unificado "Ventas y Gastos"
        //     que muestra TODAS las facturas archivadas por el asesor
        //     (sub-tabs Ventas | Gastos | Todo, filtrados por
        //     source_type). Estilo A3/Contasol — no hay emisión.
        Tab billingTab = null;
        Tab purchasesTab = null;
        Tab salesAndExpensesTab = null;
        if (isLinked) {
            // Slice 3Q — Pestañas Facturación y Compras del cliente
            // vinculado envueltas con sub-tab "Recurrentes" para que
            // la asesoría pueda crear plantillas DENTRO del tenant
            // del cliente (recurring_tasks.company_id = cliente). El
            // cliente las ve también en su propia app.
            // "Mi gestión" (empresa propia): pantalla COMPLETA del módulo
            // (incluye su propio sub-tab Recurrentes). Cliente real: vista de
            // cliente envuelta con el sub-tab Recurrentes del tenant del cliente.
            billingTab = new Tab(t("advisory.client.tab.billing"),
                    isOwn ? buildOwnBillingTab()
                          : wrapWithRecurringSubTab(
                            buildClientBillingTab(),
                            "SALES_INVOICE",
                            t("advisory.client.tab.billing")));
            billingTab.setGraphic(icon("fas-file-invoice-dollar"));
            purchasesTab = new Tab(t("advisory.client.tab.purchases"),
                    isOwn ? buildOwnPurchasesTab()
                          : wrapWithRecurringSubTab(
                            buildClientPurchasesTab(),
                            "PURCHASE",
                            t("advisory.client.tab.purchases")));
            purchasesTab.setGraphic(icon("fas-receipt"));
        } else {
            salesAndExpensesTab = new Tab(
                    t("advisory.client.tab.sales_and_expenses"),
                    buildClientSalesAndExpensesTab(client.taxIdentifier()));
            salesAndExpensesTab.setGraphic(icon("fas-receipt"));
        }

        // Contabilidad del cliente — reutiliza AccountingScreen. Las
        // llamadas API llevan el X-Company-Id del cliente porque
        // AuthSession.actingForCompanyId ya está activo. El asesor revisa
        // asientos auto-propuestos, valida, edita reglas aprendidas y
        // ejecuta recurrentes desde aquí, sin salir del contexto del
        // cliente.
        com.benjagest.ui.screens.AccountingScreen accountingScreen =
                new com.benjagest.ui.screens.AccountingScreen(accountingApiClient, this::t);
        // FICHA-TABS (2026-06-15): Contabilidad se agrupa (Diario/Validar, Bancos,
        // Préstamos, Inmovilizado) como sub-tabs — ver el bloque de añadido.
        com.benjagest.ui.screens.ClientFinancialsScreen financials =
                new com.benjagest.ui.screens.ClientFinancialsScreen(accountingApiClient, this::t);

        Tab laborTab = new Tab(t("advisory.client.tab.labor"),
                buildClientLaborTab());
        laborTab.setGraphic(icon("fas-users"));

        // La asesoría genera/edita los modelos de SUS clientes (vinculados o no) desde
        // su ficha, igual que en "Mi gestión": el editor completo opera sobre la empresa
        // activa (X-Company-Id del cliente). Antes el cliente solo tenía un listado.
        Tab taxTab = new Tab(t("advisory.client.tab.tax_models"), buildOwnTaxTab());
        taxTab.setGraphic(icon("fas-landmark"));

        Tab certificateTab = new Tab(t("advisory.client.tab.certificate"),
                settingsCertificateTab());
        certificateTab.setGraphic(icon("fas-certificate"));

        // Slice 5D — Resumen siempre visible (es identidad del cliente,
        // no un módulo del catálogo). Equivalente al "perfil" del cliente
        // que todo empleado autorizado puede consultar.
        tabs.getTabs().add(summaryTab);
        // CLIENT-CONFIG (2026-06-15) — "Configuración" en 2º lugar, para TODOS los
        // clientes (vinculados o no): datos fiscales, cifras manuales sin
        // contabilidad, contacto y notas internas.
        Tab clientConfigTab = new Tab(t("advisory.client.tab.config"), buildClientConfigTab());
        clientConfigTab.setGraphic(icon("fas-sliders-h"));
        tabs.getTabs().add(clientConfigTab);
        if (isLinked) {
            if (canSee.test("billing")) tabs.getTabs().add(billingTab);
            if (canSee.test("purchases")) tabs.getTabs().add(purchasesTab);
            // TPB-CLIENT-SETUP F2 — tab "Clientes" del titular (sus
            // receptores). Para vinculados siempre; para sin-vinculo se
            // anade dinamicamente al activar TPB (onTpbActivated).
            if (canSee.test("billing")) {
                Tab linkedCustomersTab = new Tab(t("advisory.client.tab.customers"),
                        buildClientCustomersTab());
                linkedCustomersTab.setGraphic(icon("fas-address-book"));
                tabs.getTabs().add(linkedCustomersTab);
                // F3 — config de facturacion del titular (Verifactu, series).
                Tab linkedBillingCfgTab = new Tab(t("advisory.client.tab.billing_config"),
                        buildClientBillingConfigTab());
                linkedBillingCfgTab.setGraphic(icon("fas-cog"));
                tabs.getTabs().add(linkedBillingCfgTab);
            }
        } else {
            // En no vinculado, el tab unificado contiene Ventas y Gastos —
            // por seguridad lo enseñamos si tiene billing O purchases.
            if (canSee.test("billing") || canSee.test("purchases")) {
                tabs.getTabs().add(salesAndExpensesTab);
            }
        }
        if (canSee.test("accounting")) {
            // FICHA-TABS: una sola pestaña "Contabilidad" con sub-tabs.
            TabPane accSub = new TabPane();
            accSub.getStyleClass().add("settings-tabs");
            accSub.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);
            Tab subDiary = new Tab(t("advisory.client.tab.accounting_diary"), accountingScreen.buildView());
            subDiary.setGraphic(icon("fas-book"));
            Tab subBanks = new Tab(t("advisory.client.tab.banks"), financials.buildBanksTab());
            subBanks.setGraphic(icon("fas-university"));
            Tab subLoans = new Tab(t("advisory.client.tab.loans"), financials.buildLoansTab());
            subLoans.setGraphic(icon("fas-hand-holding-usd"));
            Tab subAssets = new Tab(t("advisory.client.tab.assets"), financials.buildAssetsTab());
            subAssets.setGraphic(icon("fas-cubes"));
            accSub.getTabs().addAll(subDiary, subBanks, subLoans, subAssets);
            Tab contabGroup = new Tab(t("advisory.client.tab.accounting"), accSub);
            contabGroup.setGraphic(icon("fas-book"));
            tabs.getTabs().add(contabGroup);
        }
        if (canSee.test("labor")) tabs.getTabs().add(laborTab);
        // Autónomos (RETA) — operativa por-tenant. Decisión 2026-06-15: la
        // operativa RETA vive en la ficha (no como módulo suelto del sidebar).
        if (canSee.test("self-employed") || canSee.test("labor")) {
            Tab retaTab = new Tab(t("advisory.client.tab.reta"), buildClientRetaTab());
            retaTab.setGraphic(icon("fas-user-tie"));
            tabs.getTabs().add(retaTab);
        }
        // Módulo Trabajos dentro de la ficha (Mi gestión y clientes con "shifts"):
        // opera sobre la empresa activa (X-Company-Id). Antes solo estaba en el
        // sidebar — petición Benjamin de tenerlo también como pestaña.
        if (canSee.test("shifts")) {
            Tab trabajosTab = new Tab(t("advisory.client.tab.trabajos"), buildWorkLogsModule());
            trabajosTab.setGraphic(icon("fas-briefcase"));
            tabs.getTabs().add(trabajosTab);
        }
        if (canSee.test("tax")) tabs.getTabs().add(taxTab);
        // Certificado: identidad fiscal del cliente. Lo mantenemos siempre
        // visible para que cualquier empleado pueda consultar/subir el
        // certificado vigente cuando trabaje con cualquiera de sus tabs.
        tabs.getTabs().add(certificateTab);
        // TPB-1 — Acuerdo previo de facturación por tercero (RD 1619/2012
        // art. 5). Siempre visible: es prerrequisito legal antes de
        // emitir facturas en nombre del cliente.
        //
        // El callback onTpbActivated se invoca cuando el polling del tab
        // acuerdo detecta que el cliente acaba de firmar via magic link.
        // Aprovechamos para anadir el tab "Facturacion" al cliente no
        // vinculado en caliente (sin tener que cerrar y reabrir).
        final TabPane finalTabs = tabs;
        final boolean finalIsLinked = isLinked;
        final java.util.function.Predicate<String> finalCanSee = canSee;
        // Referencia mutable al tab Resumen para poder reconstruirlo
        // dinamicamente cuando el TPB se active/revoque (caso cliente
        // no vinculado: con TPB ACTIVE pasa a tener KPIs como cualquier
        // vinculado; al revocar, vuelve a la version sin KPIs).
        final Tab summaryTabRef = summaryTab;
        final com.benjagest.ui.model.ManagedClientEntry finalClient = client;

        Runnable onTpbActivated = () -> {
            if (finalIsLinked) return;
            // 1) Reconstruir el Resumen mostrando KPIs (el TPB activo
            //    equivale funcionalmente al vinculado para facturacion).
            summaryTabRef.setContent(buildClientSummaryTab(finalClient, true));
            // 2) Anadir tab Facturacion si procede.
            if (!finalCanSee.test("billing")) return;
            // Idempotente: si ya hay tab "Facturacion" no anadimos otro.
            for (Tab existing : finalTabs.getTabs()) {
                if (existing.getText() != null
                        && existing.getText().equals(t("advisory.client.tab.billing"))) {
                    return;
                }
            }
            Tab newBillingTab = new Tab(t("advisory.client.tab.billing"),
                    wrapWithRecurringSubTab(
                            buildClientBillingTab(),
                            "SALES_INVOICE",
                            t("advisory.client.tab.billing")));
            newBillingTab.setGraphic(icon("fas-file-invoice-dollar"));
            // Insertar tras Resumen (indice 1).
            int insertAt = Math.min(1, finalTabs.getTabs().size());
            finalTabs.getTabs().add(insertAt, newBillingTab);
            // TPB-CLIENT-SETUP F2 — tab "Clientes" del titular junto a
            // Facturacion (para dar de alta sus receptores). Idempotente.
            String custLabel = t("advisory.client.tab.customers");
            boolean hasCust = finalTabs.getTabs().stream().anyMatch(tab ->
                    custLabel.equals(tab.getText()));
            if (!hasCust) {
                Tab custTab = new Tab(custLabel, buildClientCustomersTab());
                custTab.setGraphic(icon("fas-address-book"));
                finalTabs.getTabs().add(insertAt + 1, custTab);
            }
            // F3 — config facturacion del titular junto a Clientes.
            String cfgLabel = t("advisory.client.tab.billing_config");
            boolean hasCfg = finalTabs.getTabs().stream().anyMatch(tab ->
                    cfgLabel.equals(tab.getText()));
            if (!hasCfg) {
                Tab cfgTab = new Tab(cfgLabel, buildClientBillingConfigTab());
                cfgTab.setGraphic(icon("fas-cog"));
                finalTabs.getTabs().add(insertAt + 2, cfgTab);
            }
        };

        // V105 — Si el cliente revoca el acuerdo (via magic link de
        // revocacion), el polling lo detecta y dispara este callback
        // para quitar el tab Facturacion del cliente no vinculado y
        // volver el Resumen a la version sin KPIs.
        Runnable onTpbRevoked = () -> {
            if (finalIsLinked) return;
            summaryTabRef.setContent(buildClientSummaryTab(finalClient, false));
            String billingLabel = t("advisory.client.tab.billing");
            String customersLabel = t("advisory.client.tab.customers");
            String cfgLabel = t("advisory.client.tab.billing_config");
            finalTabs.getTabs().removeIf(tab -> tab.getText() != null
                    && (tab.getText().equals(billingLabel)
                        || tab.getText().equals(customersLabel)
                        || tab.getText().equals(cfgLabel)));
        };

        Tab tpbTab = new Tab(t("advisory.client.tab.tpb_agreement"),
                buildClientTpbAgreementTab(client, isLinked, onTpbActivated, onTpbRevoked));
        tpbTab.setGraphic(icon("fas-file-signature"));
        tabs.getTabs().add(tpbTab);
        VBox.setVgrow(tabs, Priority.ALWAYS);

        // Cliente NO vinculado: comprobar al entrar si ya hay TPB activo
        // (caso en que el asesor abre el cliente despues de que el
        // empresario haya firmado por magic link en un evento anterior).
        // Si lo hay, anadir el tab Facturacion inmediatamente.
        if (!isLinked) {
            Task<com.benjagest.ui.model.TpbAgreementEntry> initialCheck = new Task<>() {
                @Override
                protected com.benjagest.ui.model.TpbAgreementEntry call() throws Exception {
                    return altaApiClient.tpbFindCurrent(client.id());
                }
            };
            initialCheck.setOnSucceeded(ev -> {
                var a = initialCheck.getValue();
                if (a != null && a.isActive() && a.scopeSales()) {
                    onTpbActivated.run();
                }
            });
            initialCheck.setOnFailed(ev -> { /* silencio */ });
            start(initialCheck, "tpb-initial-tab-check");
        }

        // Salto directo desde un aviso de cartera: si venimos de "Abrir" en un
        // aviso, seleccionamos la pestaña que lo resuelve (asientos por validar →
        // Contabilidad, que abre en "Por validar"; gastos → Compras y Gastos;
        // facturas → Facturación; etc.). Antes el aviso solo abría la ficha.
        if (pendingClientBucketType != null) {
            java.util.List<String> candidates = clientTabKeysFor(pendingClientBucketType);
            pendingClientBucketType = null;
            outer:
            for (String key : candidates) {
                String label = t(key);
                for (Tab tb : tabs.getTabs()) {
                    if (label.equals(tb.getText())) {
                        tabs.getSelectionModel().select(tb);
                        break outer;
                    }
                }
            }
        }

        VBox body = new VBox(12, header, hint, tabs);
        body.setPadding(new Insets(20));
        // DOBLE PANTALLA — la ficha de asesoría apila mucho chrome (cabecera de
        // cliente + 2 filas de pestañas + filtros + acciones). En un portátil eso
        // supera el alto y el listado quedaba INACCESIBLE (sin scroll). Envolvemos
        // SOLO esta ficha en un scroll de página: si no cabe, se baja hasta el
        // listado (la tabla mantiene su alto y scrollea por dentro = doble scroll).
        // El empresario standalone NO pasa por aquí (su chrome es ligero y la tabla
        // sigue rellenando con tabLayoutFill).
        ScrollPane fichaScroll = new ScrollPane(body);
        fichaScroll.setFitToWidth(true);
        fichaScroll.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
        fichaScroll.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);
        fichaScroll.getStyleClass().add("content-scroll");
        return fichaScroll;
    }

    private Node buildClientSummaryTab(com.benjagest.ui.model.ManagedClientEntry client) {
        return buildClientSummaryTab(client, true);
    }

    /**
     * TPB-1 — Pestaña "Acuerdo de facturación por tercero" en la pantalla
     * del cliente activo (modo asesoría).
     *
     * @param onActivated callback que se invoca cuando el polling detecta
     *                    que el acuerdo acaba de pasar a ACTIVE (caso
     *                    tipico: cliente sin vinculo firma via magic link
     *                    desde su navegador). El parent lo usa para
     *                    anadir el tab "Facturacion" en caliente.
     * @param onRevoked   callback simetrico para REVOKED (cliente revoca
     *                    via magic link). El parent quita el tab
     *                    "Facturacion".
     */
    private Node buildClientTpbAgreementTab(
            com.benjagest.ui.model.ManagedClientEntry client, boolean isLinked,
            Runnable onActivated, Runnable onRevoked) {
        VBox root = new VBox(14);
        root.setPadding(new Insets(20));

        Label title = label(t("tpb.title"), "settings-section-title");
        Label hint = new Label(t("tpb.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        VBox stateSlot = new VBox(10);

        // Guardamos el ultimo estado conocido para detectar transiciones
        // (p.ej. PROPOSED -> ACTIVE cuando el cliente firma via magic link).
        // Sin esto el polling sobreescribiria el UI cada 5s aunque nada
        // hubiera cambiado.
        final String[] lastStatus = new String[]{ null };

        Runnable[] reloadHolder = new Runnable[1];
        Runnable realReload = () -> {
            stateSlot.getChildren().clear();
            Task<com.benjagest.ui.model.TpbAgreementEntry> task = new Task<>() {
                @Override
                protected com.benjagest.ui.model.TpbAgreementEntry call() throws Exception {
                    return altaApiClient.tpbFindCurrent(client.id());
                }
            };
            task.setOnSucceeded(ev -> {
                var a = task.getValue();
                renderTpbState(stateSlot, a, client, isLinked, reloadHolder[0]);
                String newStatus = a == null ? null : a.status();
                String prev = lastStatus[0];
                lastStatus[0] = newStatus;
                // Transicion a ACTIVE: notificar al parent para que pueda
                // anadir el tab Facturacion en caliente.
                if ("ACTIVE".equals(newStatus) && !"ACTIVE".equals(prev)
                        && onActivated != null) {
                    onActivated.run();
                }
                // Transicion a REVOKED: simetrico, quitar Facturacion.
                if ("REVOKED".equals(newStatus) && !"REVOKED".equals(prev)
                        && onRevoked != null) {
                    onRevoked.run();
                }
            });
            task.setOnFailed(ev -> {
                Label err = new Label(t("tpb.fail.load") + " "
                        + (task.getException() == null ? "" : task.getException().getMessage()));
                err.setWrapText(true);
                err.setStyle("-fx-text-fill: #b91c1c;");
                stateSlot.getChildren().add(err);
            });
            start(task, "tpb-load");
        };
        reloadHolder[0] = realReload;
        realReload.run();

        // Polling cada 5 segundos para auto-detectar firma del cliente
        // (magic link) sin necesidad de que el asesor pulse "Recargar".
        // Se inicia siempre; el Timeline se detiene cuando el nodo se
        // quita de la escena (parentProperty listener).
        javafx.animation.Timeline poller = new javafx.animation.Timeline(
                new javafx.animation.KeyFrame(
                        javafx.util.Duration.seconds(5),
                        ev -> {
                            // Poleamos mientras no este REVOKED (estado
                            // terminal). PROPOSED → detectar firma del
                            // cliente. ACTIVE → detectar revocacion del
                            // cliente via magic link.
                            String s = lastStatus[0];
                            if (!"REVOKED".equals(s)) {
                                realReload.run();
                            }
                        }));
        poller.setCycleCount(javafx.animation.Animation.INDEFINITE);
        // Lifecycle: cuando el tab se desvincule de la escena (asesor
        // cierra el cliente, navega a otro lado), detenemos el polling
        // para no hacer requests fantasma.
        root.sceneProperty().addListener((obs, oldScene, newScene) -> {
            if (newScene == null) {
                poller.stop();
            } else {
                poller.play();
            }
        });
        poller.play();

        // Boton recargar manual (por si el asesor quiere forzar antes
        // del proximo tick del Timeline).
        Button reloadBtn = new Button(t("tpb.action.reload"));
        reloadBtn.setGraphic(icon("fas-sync-alt"));
        reloadBtn.setOnAction(e -> realReload.run());
        HBox titleRow = new HBox(12, title, new Region(), reloadBtn);
        HBox.setHgrow(titleRow.getChildren().get(1), Priority.ALWAYS);
        titleRow.setAlignment(Pos.CENTER_LEFT);

        root.getChildren().addAll(titleRow, hint, stateSlot);
        return root;
    }

    private void renderTpbState(VBox slot,
                                  com.benjagest.ui.model.TpbAgreementEntry a,
                                  com.benjagest.ui.model.ManagedClientEntry client,
                                  boolean isLinked,
                                  Runnable reload) {
        slot.getChildren().clear();
        if (a == null) {
            // Sin acuerdo — botón proponer
            Label empty = new Label(t("tpb.empty"));
            empty.setWrapText(true);
            slot.getChildren().add(empty);
            if (!isLinked) {
                // Aviso temprano: sin vinculo no hay forma legal de
                // firmar el acuerdo. No bloqueamos proponerlo (el
                // backend lo permite), pero advertimos que el cliente
                // tendra que vincularse para firmar.
                Label warn = new Label(t("tpb.propose.needs_link"));
                warn.setWrapText(true);
                warn.setStyle("-fx-text-fill: #b91c1c; -fx-font-weight: bold;");
                slot.getChildren().add(warn);
            }
            Button propose = new Button(t("tpb.propose.button"));
            propose.setGraphic(icon("fas-plus"));
            propose.getStyleClass().add("button-primary");
            propose.setOnAction(e -> showTpbProposeDialog(client, reload));
            slot.getChildren().add(propose);
            return;
        }
        // Estado del acuerdo
        GridPane g = new GridPane();
        g.setHgap(20); g.setVgap(6);
        int r = 0;
        g.add(new Label(t("tpb.field.status")), 0, r);
        Label statusLbl = new Label(humanizeTpbStatus(a.status()));
        statusLbl.setStyle("-fx-font-weight: bold; -fx-text-fill: "
                + (a.isActive() ? "#16a34a" : a.isPending() ? "#d97706" : "#64748b") + ";");
        g.add(statusLbl, 1, r++);
        g.add(new Label(t("tpb.field.scope")), 0, r);
        g.add(new Label(humanizeTpbScope(a)), 1, r++);
        if (a.signedAt() != null && !a.signedAt().isBlank()) {
            g.add(new Label(t("tpb.field.signed_at")), 0, r);
            g.add(new Label(a.signedAt()), 1, r++);
            g.add(new Label(t("tpb.field.signed_method")), 0, r);
            g.add(new Label(humanizeTpbMethod(a.signedMethod())), 1, r++);
        }
        slot.getChildren().add(g);

        HBox actions = new HBox(8);
        actions.setAlignment(Pos.CENTER_LEFT);

        if (a.isPending()) {
            if (!isLinked) {
                // Cliente NO vinculado — flujo Magic Link + OTP (V104,
                // decision Benjamin 2026-06-12 tras bloquear offline-PDF).
                // La asesoria envia al email del cliente un enlace de
                // firma electronica simple (eIDAS art. 25). El cliente
                // abre el enlace en cualquier navegador, lee el PDF, e
                // introduce el OTP que tambien le ha llegado por email.
                Label hint = new Label(t("tpb.magic.hint"));
                hint.setWrapText(true);
                hint.getStyleClass().add("settings-hint");

                TextField emailField = new TextField();
                emailField.setPromptText(t("tpb.magic.email_prompt"));
                emailField.setPrefColumnCount(28);
                if (client.email() != null && !client.email().isBlank()) {
                    emailField.setText(client.email());
                }

                Button send = new Button(t("tpb.magic.send"));
                send.setGraphic(icon("fas-paper-plane"));
                send.getStyleClass().add("button-primary");
                send.setOnAction(e -> tpbSendMagicLinkAction(
                        a.id(), emailField.getText(), reload));

                HBox row = new HBox(8, emailField, send);
                row.setAlignment(Pos.CENTER_LEFT);
                slot.getChildren().addAll(hint, row);
            } else {
                // Cliente vinculado — esperando firma con PIN desde su lado
                Label wait = new Label(t("tpb.pending.waiting_client"));
                wait.setWrapText(true);
                wait.getStyleClass().add("settings-hint");
                slot.getChildren().add(wait);
            }
        } else if (a.isActive()) {
            Button dl = new Button(t("tpb.signed.download"));
            dl.setGraphic(icon("fas-file-pdf"));
            dl.setOnAction(e -> tpbDownloadSignedPdfAction(a.id()));
            actions.getChildren().add(dl);
            // Boton de diagnostico: si el acuerdo esta ACTIVE y cubre
            // ventas, fuerza la creacion de la serie TPB. Util para
            // reparar acuerdos firmados antes del fix de auto-repair
            // (caso Benjamin 2026-06-12).
            if (a.scopeSales()) {
                Button repair = new Button(t("tpb.action.repair_series"));
                repair.setGraphic(icon("fas-wrench"));
                repair.setOnAction(e -> tpbRepairSeriesAction(a.id(), reload));
                actions.getChildren().add(repair);
            }
            // V105: si el cliente firmo via Magic Link (no vinculado),
            // ofrecemos a la asesoria reenviar el enlace de revocacion
            // por si el cliente perdio el original.
            if (!isLinked && "MAGIC_LINK_OTP".equals(a.signedMethod())) {
                Button resend = new Button(t("tpb.action.resend_revoke"));
                resend.setGraphic(icon("fas-paper-plane"));
                resend.setOnAction(e -> tpbResendRevokeLinkAction(a.id()));
                actions.getChildren().add(resend);
            }
        }

        Button revoke = new Button(t("tpb.revoke"));
        revoke.setGraphic(icon("fas-ban"));
        revoke.setOnAction(e -> tpbRevokeAction(a.id(), reload));
        actions.getChildren().add(revoke);
        slot.getChildren().add(actions);
    }

    private void tpbResendRevokeLinkAction(String agreementId) {
        Task<String> task = new Task<>() {
            @Override
            protected String call() throws Exception {
                return altaApiClient.tpbResendRevokeLink(agreementId);
            }
        };
        task.setOnSucceeded(e -> showInfo(t("tpb.resend_revoke.ok.title"),
                t("tpb.resend_revoke.ok.body")));
        task.setOnFailed(e -> showError(t("tpb.resend_revoke.fail.title"),
                task.getException() == null ? "" : task.getException().getMessage()));
        start(task, "tpb-resend-revoke");
    }

    private void tpbSendMagicLinkAction(String agreementId, String email, Runnable reload) {
        if (email == null || email.isBlank() || !email.contains("@")) {
            showError(t("tpb.magic.fail.title"), t("tpb.magic.fail.bad_email"));
            return;
        }
        Task<String> task = new Task<>() {
            @Override
            protected String call() throws Exception {
                return altaApiClient.tpbSendMagicLink(agreementId, email);
            }
        };
        task.setOnSucceeded(e -> {
            showInfo(t("tpb.magic.ok.title"), t("tpb.magic.ok.body") + " " + email);
            if (reload != null) reload.run();
        });
        task.setOnFailed(e -> showError(t("tpb.magic.fail.title"),
                task.getException() == null ? "" : task.getException().getMessage()));
        start(task, "tpb-send-magic-link");
    }

    private void tpbRepairSeriesAction(String agreementId, Runnable reload) {
        Task<String> task = new Task<>() {
            @Override
            protected String call() throws Exception {
                return altaApiClient.tpbEnsureSeries(agreementId);
            }
        };
        task.setOnSucceeded(e -> {
            String json = task.getValue();
            java.util.regex.Matcher mCode = java.util.regex.Pattern
                    .compile("\"code\"\\s*:\\s*\"([^\"]+)\"").matcher(json);
            java.util.regex.Matcher mCreated = java.util.regex.Pattern
                    .compile("\"created\"\\s*:\\s*(true|false)").matcher(json);
            String code = mCode.find() ? mCode.group(1) : "?";
            boolean created = mCreated.find() && "true".equals(mCreated.group(1));
            showInfo(t("tpb.repair.ok.title"),
                    (created ? t("tpb.repair.ok.created") : t("tpb.repair.ok.existed"))
                    + " " + code);
            if (reload != null) reload.run();
        });
        task.setOnFailed(e -> showError(t("tpb.repair.fail.title"),
                task.getException() == null ? "" : task.getException().getMessage()));
        start(task, "tpb-repair-series");
    }

    private void showTpbProposeDialog(com.benjagest.ui.model.ManagedClientEntry client,
                                        Runnable onSaved) {
        Dialog<ButtonType> dlg = new Dialog<>();
        dlg.setTitle(t("tpb.propose.dialog.title"));
        dlg.getDialogPane().getButtonTypes().addAll(ButtonType.OK, ButtonType.CANCEL);

        CheckBox sales = new CheckBox(t("tpb.scope.sales"));
        CheckBox purchases = new CheckBox(t("tpb.scope.purchases"));
        CheckBox taxModels = new CheckBox(t("tpb.scope.tax_models"));
        sales.setSelected(true);

        Label intro = new Label(t("tpb.propose.dialog.intro"));
        intro.setWrapText(true);
        intro.getStyleClass().add("settings-hint");
        VBox content = new VBox(10, intro, sales, purchases, taxModels);
        content.setPadding(new Insets(16));
        content.setPrefWidth(440);
        dlg.getDialogPane().setContent(content);

        dlg.showAndWait().ifPresent(bt -> {
            if (bt != ButtonType.OK) return;
            if (!sales.isSelected() && !purchases.isSelected() && !taxModels.isSelected()) {
                showError(t("tpb.propose.fail.title"), t("tpb.propose.fail.empty_scope"));
                return;
            }
            String advisoryId = com.benjagest.ui.service.AuthSession.get().activeCompanyId();
            Task<com.benjagest.ui.model.TpbAgreementEntry> task = new Task<>() {
                @Override
                protected com.benjagest.ui.model.TpbAgreementEntry call() throws Exception {
                    return altaApiClient.tpbPropose(advisoryId, client.id(),
                            sales.isSelected(), purchases.isSelected(), taxModels.isSelected());
                }
            };
            task.setOnSucceeded(e -> onSaved.run());
            task.setOnFailed(e -> showError(t("tpb.propose.fail.title"),
                    task.getException() == null ? "" : task.getException().getMessage()));
            start(task, "tpb-propose");
        });
    }

    private void tpbDownloadProposalPdfAction(String agreementId) {
        javafx.stage.FileChooser fc = new javafx.stage.FileChooser();
        fc.setTitle(t("tpb.proposal.download"));
        fc.setInitialFileName("acuerdo-facturacion-tercero.pdf");
        fc.getExtensionFilters().add(
                new javafx.stage.FileChooser.ExtensionFilter("PDF", "*.pdf"));
        java.io.File target = fc.showSaveDialog(root.getScene().getWindow());
        if (target == null) return;
        Task<byte[]> dl = new Task<>() {
            @Override protected byte[] call() throws Exception {
                return altaApiClient.tpbDownloadProposalPdf(agreementId);
            }
        };
        dl.setOnSucceeded(s -> {
            try { java.nio.file.Files.write(target.toPath(), dl.getValue());
                showInfo(t("tpb.proposal.download.ok"), target.getAbsolutePath());
            } catch (java.io.IOException ex) {
                showError(t("tpb.fail.io"), ex.getMessage());
            }
        });
        dl.setOnFailed(s -> showError(t("tpb.fail.io"),
                dl.getException() == null ? "" : dl.getException().getMessage()));
        start(dl, "tpb-dl-proposal");
    }

