    private void tpbUploadSignedAction(String agreementId, Runnable onDone) {
        javafx.stage.FileChooser fc = new javafx.stage.FileChooser();
        fc.setTitle(t("tpb.proposal.upload_signed"));
        fc.getExtensionFilters().add(
                new javafx.stage.FileChooser.ExtensionFilter("PDF", "*.pdf"));
        java.io.File f = fc.showOpenDialog(root.getScene().getWindow());
        if (f == null) return;
        Task<com.benjagest.ui.model.TpbAgreementEntry> up = new Task<>() {
            @Override
            protected com.benjagest.ui.model.TpbAgreementEntry call() throws Exception {
                return altaApiClient.tpbSignWithOfflinePdf(agreementId, f);
            }
        };
        up.setOnSucceeded(s -> onDone.run());
        up.setOnFailed(s -> showError(t("tpb.fail.upload"),
                up.getException() == null ? "" : up.getException().getMessage()));
        start(up, "tpb-up-signed");
    }

    private void tpbRevokeAction(String agreementId, Runnable onDone) {
        javafx.scene.control.TextInputDialog td = new javafx.scene.control.TextInputDialog();
        td.setTitle(t("tpb.revoke"));
        td.setHeaderText(t("tpb.revoke.prompt"));
        String reason = td.showAndWait().orElse(null);
        if (reason == null) return;
        Task<Void> task = new Task<>() {
            @Override protected Void call() throws Exception {
                altaApiClient.tpbRevoke(agreementId, reason);
                return null;
            }
        };
        task.setOnSucceeded(s -> onDone.run());
        task.setOnFailed(s -> showError(t("tpb.fail.revoke"),
                task.getException() == null ? "" : task.getException().getMessage()));
        start(task, "tpb-revoke");
    }

    private String humanizeTpbStatus(String s) {
        if (s == null) return "";
        return switch (s) {
            case "PROPOSED" -> t("tpb.status.proposed");
            case "ACTIVE"   -> t("tpb.status.active");
            case "REVOKED"  -> t("tpb.status.revoked");
            default         -> s;
        };
    }

    private String humanizeTpbMethod(String m) {
        if (m == null) return "";
        return switch (m) {
            case "PIN_SESSION"    -> t("tpb.method.pin_session");
            case "OFFLINE_PDF"    -> t("tpb.method.offline_pdf");
            case "MAGIC_LINK_OTP" -> t("tpb.method.magic_link_otp");
            default               -> m;
        };
    }

    /**
     * I18N-ENUMS — Traduce un valor enum/codigo de BD a su etiqueta
     * localizada. Construye la clave {@code enum.<prefix>.<CODIGO>} y la
     * pasa por {@link #t}. Si el valor es null/blank devuelve "". Si la
     * clave no existe en el switch de t() se devuelve el codigo en bruto
     * (fallback del propio t()), nunca rompe.
     *
     * <p>Centraliza la traduccion de los muchos enums que antes se
     * pintaban en crudo (COMPANY, RETA, MONTHLY, BANK_TRANSFER, ...).
     */
    private String localizedEnum(String prefix, String code) {
        if (code == null || code.isBlank()) return "";
        return t("enum." + prefix + "." + code);
    }

    /**
     * Humaniza un código sin etiqueta i18n específica (LOGIN_OK → "Login ok"): quita
     * guiones bajos y capitaliza. Para conjuntos de valores grandes/abiertos (p.ej.
     * tipos de evento de auditoría) donde mantener un catálogo completo no compensa.
     */
    private String humanizeCode(String code) {
        if (code == null || code.isBlank()) return "";
        String s = code.replace('_', ' ').trim().toLowerCase();
        return s.isEmpty() ? "" : Character.toUpperCase(s.charAt(0)) + s.substring(1);
    }

    /**
     * I18N-ENUMS — Configura un ComboBox&lt;String&gt; cuyos items son
     * codigos enum para que muestre la etiqueta traducida (via
     * {@link #localizedEnum}) sin cambiar el valor interno. El usuario
     * ve "Transferencia" pero el combo sigue devolviendo "BANK_TRANSFER".
     */
    private void localizeEnumCombo(ComboBox<String> combo, String prefix) {
        combo.setCellFactory(lv -> new javafx.scene.control.ListCell<>() {
            @Override protected void updateItem(String item, boolean empty) {
                super.updateItem(item, empty);
                setText(empty || item == null ? "" : localizedEnum(prefix, item));
            }
        });
        combo.setButtonCell(new javafx.scene.control.ListCell<>() {
            @Override protected void updateItem(String item, boolean empty) {
                super.updateItem(item, empty);
                setText(empty || item == null ? "" : localizedEnum(prefix, item));
            }
        });
    }

    private String humanizeTpbScope(com.benjagest.ui.model.TpbAgreementEntry a) {
        java.util.List<String> parts = new java.util.ArrayList<>();
        if (a.scopeSales()) parts.add(t("tpb.scope.sales"));
        if (a.scopePurchases()) parts.add(t("tpb.scope.purchases"));
        if (a.scopeTaxModels()) parts.add(t("tpb.scope.tax_models"));
        return String.join(" · ", parts);
    }

    /**
     * Resumen del cliente. Si {@code showKpis=true}, incluye el bloque
     * de KPIs (Ventas, Gastos, IVA, Modelo 303). En el cliente NO
     * vinculado los KPIs viven en la pestaña "Ventas y Gastos" para
     * estar junto a los listados, así que no se duplican aquí.
     */
    private Node buildClientSummaryTab(com.benjagest.ui.model.ManagedClientEntry client,
                                         boolean showKpis) {
        Label title = label(t("advisory.client.summary.title"), "settings-section-title");
        Label hint = new Label(t("advisory.client.summary.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        GridPane g = new GridPane();
        g.setHgap(20); g.setVgap(8);
        // Etiquetas con color explícito: sin -fx-text-fill heredarían el texto
        // claro del tema sobre el fondo blanco → casi invisibles (bug Benjamin
        // 2026-06-24). Campo en gris medio, valor en oscuro.
        java.util.function.Function<String, Label> fld = s -> {
            Label l = new Label(s);
            l.setStyle("-fx-text-fill: #64748b;");
            return l;
        };
        java.util.function.Function<String, Label> val = s -> {
            Label l = new Label(s);
            l.setStyle("-fx-text-fill: #1e293b; -fx-font-weight: bold;");
            return l;
        };
        int r = 0;
        g.add(fld.apply(t("advisory.client.field.legal_name")), 0, r);
        g.add(val.apply(client.legalName() == null ? "—" : client.legalName()), 1, r++);
        g.add(fld.apply(t("advisory.client.field.nif")), 0, r);
        g.add(val.apply(client.taxIdentifier() == null ? "—" : client.taxIdentifier()), 1, r++);
        if (client.companyType() != null) {
            g.add(fld.apply(t("advisory.client.field.type")), 0, r);
            g.add(val.apply(localizedEnum("customer_type", client.companyType())), 1, r++);
        }
        if (client.email() != null) {
            g.add(fld.apply(t("advisory.client.field.email")), 0, r);
            g.add(val.apply(client.email()), 1, r++);
        }
        if (client.city() != null && !client.city().isBlank()) {
            g.add(fld.apply(t("advisory.client.field.city")), 0, r);
            g.add(val.apply(client.city()), 1, r++);
        }

        VBox body = new VBox(14, title, hint, g);
        // KPIs reales (Slice 2A). Solo los pintamos aquí si el cliente
        // está vinculado — en el NO vinculado los KPIs ya viven en la
        // pestaña "Ventas y Gastos" para estar junto a los listados,
        // y duplicarlos en el Resumen confundiría.
        if (showKpis) {
            Label kpisTitle = label(t("advisory.client.kpis.title"),
                    "settings-section-title");
            LocalDate todaySum = LocalDate.now();
            int currentQuarterSum = (todaySum.getMonthValue() - 1) / 3 + 1;
            LocalDate initFromSum = LocalDate.of(todaySum.getYear(),
                    (currentQuarterSum - 1) * 3 + 1, 1);
            LocalDate initToSum = initFromSum.plusMonths(3).minusDays(1);
            javafx.beans.property.ObjectProperty<LocalDate> fromPropSum =
                    new javafx.beans.property.SimpleObjectProperty<>(initFromSum);
            javafx.beans.property.ObjectProperty<LocalDate> toPropSum =
                    new javafx.beans.property.SimpleObjectProperty<>(initToSum);
            Node kpisBlock = buildClientKpisBlock(fromPropSum, toPropSum);
            body.getChildren().addAll(new Separator(), kpisTitle, kpisBlock);
        }
        body.setPadding(new Insets(20));
        return body;
    }

    /**
     * Pestaña Compras y Gastos dentro de la pantalla del cliente.
     * Renderiza el listado COMPLETO de gastos directamente dentro del
     * tab (no navega fuera). Gracias al actingForCompanyId activo en
     * AuthSession, las queries van al tenant del cliente — los gastos
     * que se ven son los de SU empresa, no los de la asesoría.
     *
     * El asesor puede importar PDF, filtrar por año / trimestre /
     * proveedor y eliminar gastos sin salir del contexto del cliente.
     */
    /**
     * Pestaña Facturación dentro de la pantalla del cliente. Listado
     * compacto de facturas emitidas (sales_invoices) con estado y total.
     * Usa el {@link BillingApiClient} existente — las llamadas heredan
     * el actingForCompanyId del cliente.
     */
    /**
     * Pestaña UNIFICADA "Ventas y Gastos" para clientes NO vinculados.
     * El asesor solo archiva facturas que el cliente emitió/recibió en
     * otro sistema — no las emite BENJAGEST. Modelo A3/Contasol.
     *
     * <p>Estructura: 3 sub-tabs reutilizando los listados existentes
     * (ya están suscritos al RefreshBus y traen el visor PDF):
     * <ul>
     *   <li><b>Ventas</b>: ingresos importados por PDF
     *       ({@code source_type=SALES_PDF_IMPORT}).</li>
     *   <li><b>Gastos</b>: facturas recibidas y archivadas como
     *       {@code purchase_invoices}.</li>
     *   <li><b>Todo</b>: futuro slice — vista mezclada por fecha con
     *       filtros. Hoy redirige al Diario contable que ya hace eso.</li>
     * </ul>
     *
     * <p>NO tiene tab Facturación porque emitir facturas legales
     * (con VeriFactu) requiere que el cliente esté vinculado y
     * configurado como emisor SIF. Sin vínculo, lo único que tiene
     * sentido es archivar lo que el cliente emitió por su cuenta.
     */
    private Node buildClientSalesAndExpensesTab() {
        return buildClientSalesAndExpensesTab(null);
    }

    /**
     * Overload con NIF del cliente actual. Habilita el botón
     * "Importar PDFs" con auto-detección venta/gasto (Slice 2C):
     * comparando el NIF emisor del PDF con el del cliente se decide
     * si el PDF entra como venta (emisor=yo) o como gasto.
     */
    private Node buildClientSalesAndExpensesTab(String selfTaxId) {
        // Periodo (trimestre + año) COMPARTIDO entre el bloque KPIs y
        // la tabla Ventas. El selector vive arriba con los KPIs; al
        // cambiar, los KPIs y la tabla se recargan juntos.
        LocalDate today = LocalDate.now();
        int currentQuarter = (today.getMonthValue() - 1) / 3 + 1;
        LocalDate initFrom = LocalDate.of(today.getYear(),
                (currentQuarter - 1) * 3 + 1, 1);
        LocalDate initTo = initFrom.plusMonths(3).minusDays(1);
        javafx.beans.property.ObjectProperty<LocalDate> fromProp =
                new javafx.beans.property.SimpleObjectProperty<>(initFrom);
        javafx.beans.property.ObjectProperty<LocalDate> toProp =
                new javafx.beans.property.SimpleObjectProperty<>(initTo);

        TabPane sub = new TabPane();
        sub.getStyleClass().add("inner-tabs");
        sub.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);

        // En cliente NO vinculado las "ventas" NO viven en sales_invoices
        // (esa tabla solo guarda las que el cliente emite con VeriFactu).
        // Las ventas importadas por PDF son ASIENTOS contables con
        // source_type=SALES_PDF_IMPORT. Por eso el sub-tab Ventas aquí
        // muestra el diario filtrado, no sales_invoices.
        Tab salesTab = new Tab(t("client.tab.sales"),
                buildClientSalesArchivedTab(fromProp, toProp, selfTaxId));
        salesTab.setGraphic(icon("fas-file-invoice"));

        // Slice 3S — En cliente NO vinculado (shadow company) los
        // recurrentes usan los kinds ACCOUNTING_INCOME / ACCOUNTING_EXPENSE
        // que generan asiento contable directo con base/IVA/retención.
        // No tiene sentido SALES_INVOICE aquí porque la shadow no tiene
        // serie de facturación ni VeriFactu — el asesor lleva la
        // contabilidad, no factura por el cliente.
        Tab salesRecurringTab = new Tab(t("client.tab.sales_recurring"),
                buildRecurringTab("ACCOUNTING_INCOME", "client.tab.sales_recurring"));
        salesRecurringTab.setGraphic(icon("fas-arrows-rotate"));

        Tab expensesTab = new Tab(t("client.tab.expenses"), buildClientPurchasesTab());
        expensesTab.setGraphic(icon("fas-receipt"));

        Tab expensesRecurringTab = new Tab(t("client.tab.expenses_recurring"),
                buildRecurringTab("ACCOUNTING_EXPENSE", "client.tab.expenses_recurring"));
        expensesRecurringTab.setGraphic(icon("fas-arrows-rotate"));

        sub.getTabs().addAll(salesTab, salesRecurringTab,
                expensesTab, expensesRecurringTab);

        // Sincronizar el periodo Año/Trimestre de los KPIs con el
        // sub-tab Gastos. buildClientPurchasesTab usa sus propios
        // comboboxes (purchaseYearFilter / purchaseQuarterFilter); aquí
        // cuando cambia el periodo compartido, los actualizamos.
        Runnable syncPurchasesFilters = () -> {
            if (purchaseYearFilter == null || purchaseQuarterFilter == null) return;
            LocalDate f = fromProp.get();
            if (f == null) return;
            int y = f.getYear();
            int q = (f.getMonthValue() - 1) / 3 + 1;
            String yStr = String.valueOf(y);
            if (purchaseYearFilter.getItems().contains(yStr)
                    && !yStr.equals(purchaseYearFilter.getValue())) {
                purchaseYearFilter.setValue(yStr);
            }
            String qStr = "T" + q;
            if (purchaseQuarterFilter.getItems().contains(qStr)
                    && !qStr.equals(purchaseQuarterFilter.getValue())) {
                purchaseQuarterFilter.setValue(qStr);
            }
        };
        fromProp.addListener((o, a, b) -> syncPurchasesFilters.run());
        // Sincronización inicial diferida — el tab Gastos se construye
        // perezosamente; los comboboxes pueden no existir todavía
        // cuando entramos en la pestaña. Reintentamos al seleccionar.
        sub.getSelectionModel().selectedItemProperty().addListener(
                (o, a, b) -> syncPurchasesFilters.run());

        // KPIs en cards arriba: ventas, gastos, IVA repercutido,
        // IVA soportado, Modelo 303 estimado, asientos pendientes.
        // Selector de trimestre/año arriba de las cards. Auto-refresh
        // suscrito al RefreshBus.
        Node kpisBlock = buildClientKpisBlock(fromProp, toProp);

        // Banner informativo: explica al asesor por qué la pantalla es
        // distinta de un cliente vinculado.
        Label hint = new Label(t("client.sales_expenses.hint"));
        hint.setWrapText(true);
        hint.getStyleClass().add("settings-hint");

        VBox box = new VBox(10, hint, kpisBlock, sub);
        VBox.setVgrow(sub, Priority.ALWAYS);
        box.setPadding(new Insets(8));
        return box;
    }

    /**
     * Cabecera de KPIs del cliente NO vinculado: selector de
     * trimestre/año + cards con totales. Refresco automático cuando
     * cambian asientos o se importan PDFs.
     */
    private Node buildClientKpisBlock(
            javafx.beans.property.ObjectProperty<LocalDate> fromProp,
            javafx.beans.property.ObjectProperty<LocalDate> toProp) {
        // Selector de período: año + trimestre. Por defecto el actual.
        LocalDate today = LocalDate.now();
        int currentQuarter = (today.getMonthValue() - 1) / 3 + 1;

        ComboBox<Integer> yearCombo = new ComboBox<>();
        for (int y = today.getYear() - 5; y <= today.getYear() + 1; y++) yearCombo.getItems().add(y);
        yearCombo.setValue(today.getYear());

        ComboBox<Integer> quarterCombo = new ComboBox<>();
        quarterCombo.getItems().addAll(1, 2, 3, 4);
        quarterCombo.setValue(currentQuarter);
        quarterCombo.setConverter(new javafx.util.StringConverter<>() {
            @Override public String toString(Integer q) {
                return q == null ? "" : "T" + q;
            }
            @Override public Integer fromString(String s) {
                return s == null || s.isBlank() ? null
                        : Integer.parseInt(s.replace("T", ""));
            }
        });

        // 6 cards (HBox). Cada una un VBox con título + valor en grande.
        Label salesValue = kpiCardValue();
        Label salesCount = kpiCardCaption();
        VBox salesCard = kpiCard(t("client.kpi.sales"), salesValue, salesCount);

        Label expensesValue = kpiCardValue();
        Label expensesCount = kpiCardCaption();
        VBox expensesCard = kpiCard(t("client.kpi.expenses"), expensesValue, expensesCount);

        Label vatChargedValue = kpiCardValue();
        VBox vatChargedCard = kpiCard(t("client.kpi.vat_charged"), vatChargedValue, null);

        Label vatBorneValue = kpiCardValue();
        VBox vatBorneCard = kpiCard(t("client.kpi.vat_borne"), vatBorneValue, null);

        Label model303Value = kpiCardValue();
        Label model303Caption = kpiCardCaption();
        VBox model303Card = kpiCard(t("client.kpi.model_303"), model303Value, model303Caption);

        Label draftsValue = kpiCardValue();
        VBox draftsCard = kpiCard(t("client.kpi.drafts"), draftsValue, null);

        HBox cards = new HBox(10, salesCard, expensesCard,
                vatChargedCard, vatBorneCard, model303Card, draftsCard);
        cards.setFillHeight(true);
        for (Node c : cards.getChildren()) HBox.setHgrow(c, Priority.ALWAYS);

        Runnable reload = () -> {
            Integer y = yearCombo.getValue();
            Integer q = quarterCombo.getValue();
            if (y == null || q == null) return;
            LocalDate from = LocalDate.of(y, (q - 1) * 3 + 1, 1);
            LocalDate to = from.plusMonths(3).minusDays(1);
            // Publicamos el periodo en las props compartidas — la tabla
            // Ventas escucha cambios y recarga automáticamente.
            fromProp.set(from);
            toProp.set(to);
            Task<com.benjagest.ui.service.AccountingApiClient.SalesAndExpensesKpis> task = new Task<>() {
                @Override
                protected com.benjagest.ui.service.AccountingApiClient.SalesAndExpensesKpis call()
                        throws Exception {
                    return accountingApiClient.kpisSalesAndExpenses(from, to);
                }
            };
            task.setOnSucceeded(ev -> {
                var k = task.getValue();
                salesValue.setText(formatMoney(k.salesTotal()));
                salesCount.setText(k.salesCount() + " " + t("client.kpi.invoices"));
                expensesValue.setText(formatMoney(k.expensesTotal()));
                expensesCount.setText(k.expensesCount() + " " + t("client.kpi.invoices"));
                vatChargedValue.setText(formatMoney(k.vatCharged()));
                vatBorneValue.setText(formatMoney(k.vatBorne()));
                model303Value.setText(formatMoney(k.model303Estimated()));
                model303Caption.setText(k.model303Estimated().signum() > 0
                        ? t("client.kpi.model_303.to_pay")
                        : k.model303Estimated().signum() < 0
                                ? t("client.kpi.model_303.to_refund")
                                : t("client.kpi.model_303.neutral"));
                draftsValue.setText(String.valueOf(k.draftCount()));
            });
            task.setOnFailed(ev -> {
                salesValue.setText("—"); expensesValue.setText("—");
                vatChargedValue.setText("—"); vatBorneValue.setText("—");
                model303Value.setText("—"); draftsValue.setText("—");
            });
            start(task, "client-kpis");
        };

        yearCombo.valueProperty().addListener((o, a, b) -> reload.run());
        quarterCombo.valueProperty().addListener((o, a, b) -> reload.run());

        HBox selectorRow = new HBox(8,
                new Label(t("client.kpi.year")), yearCombo,
                new Label(t("client.kpi.quarter")), quarterCombo);
        selectorRow.setAlignment(Pos.CENTER_LEFT);

        VBox block = new VBox(8, selectorRow, cards);
        block.setPadding(new Insets(4, 0, 4, 0));

        // Auto-refresh cuando se modifican asientos.
        com.benjagest.ui.support.RefreshBus.subscribe(
                com.benjagest.ui.support.RefreshBus.TOPIC_JOURNAL,
                reload, block);
        com.benjagest.ui.support.RefreshBus.subscribe(
                com.benjagest.ui.support.RefreshBus.TOPIC_PURCHASES,
                reload, block);
        com.benjagest.ui.support.RefreshBus.subscribe(
                com.benjagest.ui.support.RefreshBus.TOPIC_SALES,
                reload, block);

        reload.run();
        return block;
    }

    private VBox kpiCard(String title, Label valueLabel, Label captionLabel) {
        Label titleLabel = new Label(title);
        titleLabel.setStyle("-fx-text-fill: #666; -fx-font-size: 11px;");
        VBox card = new VBox(2);
        card.getChildren().add(titleLabel);
        card.getChildren().add(valueLabel);
        if (captionLabel != null) card.getChildren().add(captionLabel);
        card.setStyle("-fx-background-color: white;"
                + "-fx-background-radius: 6;"
                + "-fx-border-color: #e0e0e0;"
                + "-fx-border-radius: 6;"
                + "-fx-border-width: 1;"
                + "-fx-padding: 10 14 10 14;");
        return card;
    }

    private Label kpiCardValue() {
        Label l = new Label("—");
        // -fx-text-fill explícito: sin él, el valor hereda el texto claro del tema
        // sobre el fondo blanco de la card → invisible (el dato estaba, pero en
        // blanco; bug Benjamin 2026-06-24). El título/caption ya tenían color.
        l.setStyle("-fx-font-size: 18px; -fx-font-weight: bold; -fx-text-fill: #1e293b;");
        return l;
    }

    private Label kpiCardCaption() {
        Label l = new Label("");
        l.setStyle("-fx-text-fill: #888; -fx-font-size: 11px;");
        return l;
    }

    private String formatMoney(java.math.BigDecimal v) {
        if (v == null) return "—";
        // Formato es-ES: 1.234,56 €
        return String.format(java.util.Locale.forLanguageTag("es-ES"),
                "%,.2f €", v);
    }

    /**
     * Sub-tab "Ventas" del cliente NO vinculado. Modelo A3/Contasol:
     * las ventas archivadas son ASIENTOS contables con
     * {@code source_type='SALES_PDF_IMPORT'}, no facturas en
     * {@code sales_invoices} (esa tabla es para facturas emitidas con
     * VeriFactu desde BENJAGEST).
     *
     * <p>Muestra: nº asiento, fecha, concepto, total. Con botón
     * "Importar PDFs" + auto-refresh por RefreshBus.
     */
    /**
     * Sub-tab "Recurrentes" del cliente — listado de tareas recurrentes
     * filtradas por {@code kind} (SALES_INVOICE o PURCHASE). Pensado
     * para que el asesor vea de un vistazo qué plantillas tiene el
     * cliente, ejecutarlas manualmente, activarlas/desactivarlas y
     * editarlas. El cron del backend ({@code 0 10 6 * * *}) las
     * ejecuta cada día a las 06:10 automáticamente — esta pantalla
     * es solo gestión y vista.
     *
     * <p>Slice 3C-1: scaffolding + listado real (sin acciones todavía).
     * Slices 3C-2..5 añaden ejecutar/activar/historial + editor.
     *
     * @param kind            "SALES_INVOICE" o "PURCHASE".
     * @param emptyMessageKey i18n key para el placeholder cuando la
     *                        lista viene vacía.
     */
    private Node buildRecurringTab(String kind, String emptyMessageKey) {
        javafx.scene.control.TableView<com.benjagest.ui.model.AccountingModels.RecurringTask> table =
                new javafx.scene.control.TableView<>();
        table.getStyleClass().add("data-table");
        table.setPlaceholder(new Label(t("recurring.placeholder.empty")));

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringTask, com.benjagest.ui.model.AccountingModels.RecurringTask> colName =
                new javafx.scene.control.TableColumn<>(t("recurring.col.name"));
        colName.setCellValueFactory(c -> new javafx.beans.property.SimpleObjectProperty<>(c.getValue()));
        colName.setCellFactory(c -> new javafx.scene.control.TableCell<>() {
            @Override protected void updateItem(
                    com.benjagest.ui.model.AccountingModels.RecurringTask v,
                    boolean empty) {
                super.updateItem(v, empty);
                if (empty || v == null) {
                    setText(null);
                    setGraphic(null);
                    return;
                }
                Label nameLabel = new Label(v.name() == null ? "" : v.name());
                nameLabel.getStyleClass().add("table-cell-text");
                // Slice 3R — Mostrar badge "Creada por tu asesoría"
                // solo cuando el viewer NO es la asesoría (es decir,
                // el empresario cliente abriendo SU app). Si el asesor
                // está viendo la plantilla, no tiene sentido el badge
                // porque la creó él mismo.
                if (v.createdByAdvisor() && appMode != AppMode.ADVISORY) {
                    Label badge = new Label(t("recurring.badge.created_by_advisor"));
                    badge.getStyleClass().add("status-pill");
                    badge.setStyle("-fx-background-color: #e0f2fe; "
                            + "-fx-text-fill: #075985; -fx-padding: 1 6 1 6; "
                            + "-fx-background-radius: 8; -fx-font-size: 10px;");
                    javafx.scene.control.Tooltip tip = new javafx.scene.control.Tooltip(
                            t("recurring.badge.created_by_advisor.tip"));
                    tip.setStyle("-fx-background-color: #1f2937; -fx-text-fill: white;");
                    javafx.scene.control.Tooltip.install(badge, tip);
                    javafx.scene.layout.HBox row =
                            new javafx.scene.layout.HBox(8, nameLabel, badge);
                    row.setAlignment(javafx.geometry.Pos.CENTER_LEFT);
                    setText(null);
                    setGraphic(row);
                } else {
                    setText(v.name() == null ? "" : v.name());
                    setGraphic(null);
                }
            }
        });
        colName.setPrefWidth(260);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringTask, String> colDesc =
                new javafx.scene.control.TableColumn<>(t("recurring.col.description"));
        colDesc.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null ? "" : c.getValue().description()));
        colDesc.setPrefWidth(260);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringTask, String> colFreq =
                new javafx.scene.control.TableColumn<>(t("recurring.col.frequency"));
        colFreq.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null ? "" : humanizeFrequency(c.getValue())));
        colFreq.setPrefWidth(140);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringTask, LocalDate> colNext =
                new javafx.scene.control.TableColumn<>(t("recurring.col.next_run"));
        colNext.setCellValueFactory(c -> new javafx.beans.property.SimpleObjectProperty<>(
                c.getValue() == null ? null : c.getValue().nextRunDate()));
        colNext.setCellFactory(c -> new javafx.scene.control.TableCell<>() {
            @Override protected void updateItem(LocalDate v, boolean empty) {
                super.updateItem(v, empty);
                setText(empty || v == null ? "" : v.toString());
            }
        });
        colNext.setPrefWidth(110);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringTask, LocalDate> colLast =
                new javafx.scene.control.TableColumn<>(t("recurring.col.last_run"));
        colLast.setCellValueFactory(c -> new javafx.beans.property.SimpleObjectProperty<>(
                c.getValue() == null ? null : c.getValue().lastRunDate()));
        colLast.setCellFactory(c -> new javafx.scene.control.TableCell<>() {
            @Override protected void updateItem(LocalDate v, boolean empty) {
                super.updateItem(v, empty);
                setText(empty || v == null ? "—" : v.toString());
            }
        });
        colLast.setPrefWidth(110);

        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringTask, String> colStatus =
                new javafx.scene.control.TableColumn<>(t("recurring.col.status"));
        colStatus.setCellValueFactory(c -> new javafx.beans.property.SimpleStringProperty(
                c.getValue() == null ? "" : (c.getValue().active()
                        ? t("recurring.status.active")
                        : t("recurring.status.inactive"))));
        colStatus.setPrefWidth(90);

        // Slice 3C-2 + 3N — Columna Acciones por fila:
        //   ▶ Ejecutar ahora (POST /run-now con date=hoy)
        //   ⏸/▶ Toggle activo/inactivo (PUT /active)
        //   🕐 Ver historial (GET /runs) → diálogo con las últimas 50
        //   🗑 Eliminar plantilla recurrente (DELETE) — Slice 3N
        javafx.scene.control.TableColumn<com.benjagest.ui.model.AccountingModels.RecurringTask, Void> colActions =
                new javafx.scene.control.TableColumn<>(t("recurring.col.actions"));
        colActions.setSortable(false);
        colActions.setPrefWidth(240);
        colActions.setCellFactory(c -> new javafx.scene.control.TableCell<>() {
            private final Button run = new Button();
            private final Button toggle = new Button();
            private final Button history = new Button();
            private final Button delete = new Button();
            private final HBox actionsBox = new HBox(4, run, toggle, history, delete);
            {
                run.setGraphic(icon("fas-play"));
                run.setTooltip(legibleTooltip(t("recurring.action.run_now")));
                run.getStyleClass().add("button-icon");
                toggle.getStyleClass().add("button-icon");
                history.setGraphic(icon("fas-clock-rotate-left"));
                history.setTooltip(legibleTooltip(t("recurring.action.history")));
                history.getStyleClass().add("button-icon");
                delete.setGraphic(icon("fas-trash"));
                delete.setTooltip(legibleTooltip(t("recurring.action.delete")));
                delete.getStyleClass().addAll("button-icon", "button-danger-outline");
                actionsBox.setAlignment(javafx.geometry.Pos.CENTER_LEFT);
            }
            @Override protected void updateItem(Void v, boolean empty) {
                super.updateItem(v, empty);
                if (empty || getIndex() < 0 || getIndex() >= getTableView().getItems().size()) {
                    setGraphic(null);
                    return;
                }
                var task = getTableView().getItems().get(getIndex());
                if (task == null) { setGraphic(null); return; }
                // Refrescar ícono y tooltip del toggle según estado actual.
                toggle.setGraphic(icon(task.active() ? "fas-pause" : "fas-play"));
                toggle.setTooltip(legibleTooltip(task.active()
                        ? t("recurring.action.pause") : t("recurring.action.activate")));
                run.setOnAction(e -> runRecurringTaskNow(task,
                        () -> loadRecurring(table, kind)));
                toggle.setOnAction(e -> toggleRecurringTaskActive(task,
                        () -> loadRecurring(table, kind)));
                history.setOnAction(e -> showRecurringHistory(task));
                delete.setOnAction(e -> deleteRecurringTask(task,
                        () -> loadRecurring(table, kind)));
                setGraphic(actionsBox);
            }
        });

        table.getColumns().add(colName);
        table.getColumns().add(colDesc);
        table.getColumns().add(colFreq);
        table.getColumns().add(colNext);
        table.getColumns().add(colLast);
        table.getColumns().add(colStatus);
        table.getColumns().add(colActions);

        // Banner informativo: avisa de que el cron corre cada día a las
        // 06:10 y que las acciones son solo gestión manual.
        Label cronInfo = new Label(t("recurring.cron_info"));
        cronInfo.getStyleClass().addAll("muted", "small");
        cronInfo.setWrapText(true);

        Button refreshBtn = new Button(t("button.refresh"));
        refreshBtn.setGraphic(icon("fas-rotate"));
        refreshBtn.setOnAction(e -> loadRecurring(table, kind));

        // Slice 3S — En shadow companies (cliente sin vínculo desde
        // asesoría) los kinds nativos son ACCOUNTING_INCOME/EXPENSE,
        // que generan asiento contable directo SIN pasar por la
        // facturación legal. El botón cambia de etiqueta y de editor.
        boolean accountingKind = "ACCOUNTING_INCOME".equals(kind)
                || "ACCOUNTING_EXPENSE".equals(kind);
        Button newBtn = new Button(
                "ACCOUNTING_INCOME".equals(kind) ? t("recurring.new.accounting_income")
                : "ACCOUNTING_EXPENSE".equals(kind) ? t("recurring.new.accounting_expense")
                : "SALES_INVOICE".equals(kind) ? t("recurring.new.sales")
                : t("recurring.new.expense"));
        newBtn.setGraphic(icon("fas-plus"));
        newBtn.getStyleClass().add("button-primary");
        newBtn.setOnAction(e -> {
            if (accountingKind) {
                showAccountingRecurringEditor(kind, null,
                        () -> loadRecurring(table, kind));
            } else {
                showRecurringEditor(kind, null,
                        () -> loadRecurring(table, kind));
            }
        });

        // Slice 3F-2 — Botón adicional SOLO en el sub-tab de Gastos
        // para crear un "Pago periódico sin factura" (kind=JOURNAL_ENTRY).
        // No tiene sentido en Ventas: una venta siempre genera factura.
        Button newJournalBtn = null;
        if ("PURCHASE".equals(kind)) {
            newJournalBtn = new Button(t("recurring.new.journal_entry.button"));
            newJournalBtn.setGraphic(icon("fas-piggy-bank"));
            newJournalBtn.setOnAction(e -> showJournalEntryRecurringEditor(null,
                    () -> loadRecurring(table, kind)));
        }

        // Doble click en una fila → editar la tarea
        table.setRowFactory(tv -> {
            javafx.scene.control.TableRow<com.benjagest.ui.model.AccountingModels.RecurringTask> row =
                    new javafx.scene.control.TableRow<>();
            row.setOnMouseClicked(ev -> {
                if (ev.getClickCount() == 2 && !row.isEmpty() && row.getItem() != null) {
                    var item = row.getItem();
                    // Derivar al editor correcto según el kind real de
                    // la tarea (puede ser JOURNAL_ENTRY aunque la
                    // pestaña sea PURCHASE — sub-tab "Pago sin factura";
                    // o ACCOUNTING_INCOME/EXPENSE — Slice 3S).
                    if ("JOURNAL_ENTRY".equals(item.kind())) {
                        showJournalEntryRecurringEditor(item,
                                () -> loadRecurring(table, kind));
                    } else if ("ACCOUNTING_INCOME".equals(item.kind())
                            || "ACCOUNTING_EXPENSE".equals(item.kind())) {
                        showAccountingRecurringEditor(item.kind(), item,
                                () -> loadRecurring(table, kind));
                    } else {
                        showRecurringEditor(kind, item,
                                () -> loadRecurring(table, kind));
                    }
                }
            });
            return row;
        });

        HBox toolbar = newJournalBtn == null
                ? new HBox(8, newBtn, refreshBtn)
                : new HBox(8, newBtn, newJournalBtn, refreshBtn);
        toolbar.setAlignment(javafx.geometry.Pos.CENTER_LEFT);

        VBox box = new VBox(8, cronInfo, toolbar, table);
        VBox.setVgrow(table, Priority.ALWAYS);
        box.setPadding(new Insets(12));
        loadRecurring(table, kind);
        // Slice 3X — Auto-refresh cuando alguien crea/edita/elimina/
        // ejecuta una recurrente desde OTRA pantalla (botón "Hacer
        // recurrente" en listado de Ventas/Gastos, run-now desde editor,
        // etc). Antes el sub-tab Recurrentes solo se refrescaba via su
        // propio botón refresh.
        com.benjagest.ui.support.RefreshBus.subscribe(
                com.benjagest.ui.support.RefreshBus.TOPIC_RECURRING,
                () -> loadRecurring(table, kind), box);
        return box;
    }

    /**
     * Carga el listado de tareas recurrentes del cliente actual desde
     * el backend filtrado por {@code kind}. Pintado en el hilo JavaFX,
     * llamada HTTP en hilo aparte.
     */
    /**
     * Slice 3Q — Envuelve un Node existente (Facturas o Compras del
     * cliente desde asesoría) en un TabPane con un segundo sub-tab
     * "Recurrentes". Pensado para que cuando la asesoría entre a
     * gestionar un cliente vinculado, pueda crear plantillas
     * recurrentes en el tenant del cliente.
     *
     * @param originalContent   listado original (Facturas o Compras).
     * @param recurringKind     "SALES_INVOICE" o "PURCHASE".
     * @param originalTabLabel  etiqueta del primer tab (ya traducida).
     */
    private Node wrapWithRecurringSubTab(Node originalContent,
                                          String recurringKind,
                                          String originalTabLabel) {
        TabPane wrapper = new TabPane();
        wrapper.getStyleClass().add("inner-tabs");
        wrapper.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);

        Tab mainTab = new Tab(originalTabLabel, originalContent);
        Tab recurringTab = new Tab(
                "SALES_INVOICE".equals(recurringKind)
                        ? t("client.tab.sales_recurring")
                        : t("client.tab.expenses_recurring"),
                buildRecurringTab(recurringKind,
                        "SALES_INVOICE".equals(recurringKind)
                                ? "client.tab.sales_recurring"
                                : "client.tab.expenses_recurring"));
        recurringTab.setGraphic(icon("fas-arrows-rotate"));

        wrapper.getTabs().addAll(mainTab, recurringTab);
        return wrapper;
    }

    private void loadRecurring(
            javafx.scene.control.TableView<com.benjagest.ui.model.AccountingModels.RecurringTask> table,
            String kind) {
        new Thread(() -> {
            try {
                java.util.List<com.benjagest.ui.model.AccountingModels.RecurringTask> rows =
                        new java.util.ArrayList<>(
                                accountingApiClient.listRecurring(kind, null));
                // Slice 3F — En el sub-tab de Gastos también mostramos
                // los pagos sin factura (kind=JOURNAL_ENTRY). Una
                // factura recibida y un asiento de cuota autónomo son
                // ambos "gastos recurrentes" para el asesor; queremos
                // verlos juntos en la misma tabla.
                if ("PURCHASE".equals(kind)) {
                    try {
                        rows.addAll(accountingApiClient.listRecurring("JOURNAL_ENTRY", null));
                    } catch (Exception ignored) { /* opcional, no bloquea */ }
                }
                javafx.application.Platform.runLater(() -> {
                    table.getItems().setAll(rows);
                });
            } catch (Exception ex) {
                javafx.application.Platform.runLater(() -> {
                    table.getItems().clear();
                    table.setPlaceholder(new Label(
                            t("recurring.error.load") + ": " + ex.getMessage()));
                });
            }
        }, "load-client-recurring").start();
    }

    /**
     * Devuelve una representación legible de la frecuencia de la tarea
     * recurrente: "Mensual (día 5)", "Trimestral", "Anual", "Semanal
     * (lunes)", "Cada N meses". Pensada para la columna Frecuencia.
     */
    private String humanizeFrequency(com.benjagest.ui.model.AccountingModels.RecurringTask task) {
        if (task == null) return "";
        String freq = task.frequency() == null ? "" : task.frequency().toUpperCase();
        Integer dom = task.dayOfMonth();
        Integer dow = task.dayOfWeek();
        return switch (freq) {
            case "MONTHLY" -> dom == null
                    ? t("recurring.freq.monthly")
                    : t("recurring.freq.monthly") + " (" + t("recurring.freq.day") + " " + dom + ")";
            case "QUARTERLY" -> t("recurring.freq.quarterly");
            case "YEARLY" -> t("recurring.freq.yearly");
            case "WEEKLY" -> dow == null
                    ? t("recurring.freq.weekly")
                    : t("recurring.freq.weekly") + " (" + dayName(dow) + ")";
            case "CUSTOM" -> t("recurring.freq.every") + " " + Math.max(1, task.monthsBetween())
                    + " " + t("recurring.freq.months");
            default -> freq;
        };
    }

